struct ProjectSettings {
    std::array<float, 4> backgroundColor{0.0F, 0.0F, 0.0F, 1.0F};
    int liveViewWindowWidth = 1440;
    int liveViewWindowHeight = 900;
    bool lockLiveViewWindowSize = false;
    bool eyeDomeLightingEnabled = false;
    bool proResAlphaPreviewEnabled = false;
    float eyeDomeLightingThickness = 1.0F;
    bool constantUpdateView = false;
    bool liveVisualEffects = false;
    // Preview-only speedups that may slightly change how overlapping points
    // blend in the live viewport (never in exports). Off preserves the
    // original preview appearance exactly.
    bool previewPerformanceMode = false;
    // Escape hatch for scalar-field residency: when set, point-cloud loads
    // materialise every on-disk scalar field exactly as before field
    // filtering existed. Takes effect on the next load of each cloud.
    bool loadAllScalarFields = false;
    // Soft ceiling for the combined CPU+GPU scalar-field payload. When the
    // resident total exceeds it, the residency sweep evicts the least-
    // recently-referenced disk-backed fields (the on-demand loader streams
    // them back if referenced again). Zero disables eviction.
    float scalarFieldBudgetGigabytes = 0.0F;
    bool autoLowerGsplatQualityWhileNavigating = true;
    PointCloudPreviewLodMode pointCloudPreviewLodMode = PointCloudPreviewLodMode::FullResolution;
    std::uint64_t interactivePointCap = kDefaultInteractivePointCap;
    PointCloudRendererMode pointCloudRendererMode = PointCloudRendererMode::Beauty;
    float gaussianSplatFootprintBoost = 1.5F;
    GsplatTransformConvention gsplatTransformConvention = GsplatTransformConvention::AsEncoded;
    GaussianSplatStyleState gsplatVisualStyle{};
};

struct PersistenceState {
    std::string projectName = "Invisible Places";
    std::string sharedDataPath;
    std::string sharedDataEditBuffer;
    std::string authoredWorkspacePath;
    std::string authoredWorkspaceEditBuffer;
    std::string projectFilePath;
    std::filesystem::path trackedProjectFilePath;
    std::optional<invisible_places::app::workspace::FileRevision>
        trackedProjectRevision;
    // Raw portable JSON corresponding to the in-memory project state when it
    // was loaded or last saved.  It is the local side's merge ancestor; after
    // a cloud merge it intentionally remains the serialized local snapshot so
    // remote-only edits are not mistaken for deletions on a later save.
    std::optional<nlohmann::json> trackedProjectMergeBaseJson;
    std::string pointStylePresetPath;
    std::string animationDirectoryPath;
    std::vector<QueuedLayerLoad> queuedLoads;
};

