struct PreviewLayerSession {
    LayerKind kind = LayerKind::PointCloud;
    std::filesystem::path sourcePath;
    std::filesystem::path transformPath;
    std::string sceneGroupName;
    std::string sceneRole;
    // Generated Flow trail sessions are source-local so profile edits and deletion
    // never require repacking unrelated sources.
    std::optional<std::uint32_t> waterFlowSourceId;
    std::uint64_t waterFlowGpuFingerprint = 0U;
    std::uint64_t waterFlowGpuRevision = 0U;
    std::uint64_t waterFlowCpuSnapshotRevision = 0U;
    // Applies to both CPU fallback snapshots and GPU-native Flow outputs. It
    // records the speed encoded in the immutable scalar/output buffer.
    float waterFlowBakedSpeedMetersPerSecond = 0.45F;
    // Runtime content semantics. Authored/source clouds remain false even if
    // a user applies a Water-looking visual or enables flow animation.
    bool generatedWaterOverlay = false;
    bool waterFlowGpuPreview = false;
    bool dynamicMeshFlowGpuPreview = false;
    float inferredPointSpacingMeters = 0.0F;
    float pointSpacingMeters = 0.0F;
    bool pointSpacingManualOverride = false;
    bool scenePrimaryRole = false;
    std::filesystem::path selectedSceneVariantPath;
    std::string displayName;
    // `loaded` remains as the compatibility mirror for GPU residency. The
    // explicit flags below make analysis-only CPU sources distinguishable from
    // renderable display sources.
    bool loaded = false;
    bool visible = false;
    bool cpuResident = false;
    bool gpuResident = false;
    bool analysisSource = false;
    bool committedDisplaySource = false;
    bool pendingDisplaySource = false;
    bool hasSourceRgb = false;
    bool hasNormals = false;
    bool hasFocusPoint = false;
    std::uint64_t totalPrimitives = 0;
    // Monotonic identity for the CPU payload installed in this session. It is
    // runtime-only and prevents standalone Seepage guides from surviving an
    // unload/reload of different content at the same path.
    std::uint64_t pointCloudContentGeneration = 0U;
    invisible_places::io::Bounds3f localBounds{};
    invisible_places::io::Bounds3f bounds{};
    invisible_places::io::Float3 localFocusPoint{};
    invisible_places::io::Float3 focusPoint{};
    invisible_places::io::Matrix4d localToWorld{};
    bool hasLocalFocusPoint = false;
    std::vector<invisible_places::io::ScalarFieldStats> scalarFields;
    // Every scalar field the source file offers (mirrors
    // offlinePointCloud->availableScalarFields): the resident subset in
    // scalarFields plus the fields the load filter left on disk, which the
    // on-demand loader can stream in later.
    std::vector<invisible_places::io::AvailableScalarField> availableScalarFields;
    // Residency sweep clock value from the last sweep whose required set
    // contained each field; drives least-recently-referenced eviction.
    std::unordered_map<std::string, std::uint64_t> scalarFieldLastRequiredTick;
    std::vector<invisible_places::io::Float3> pivotSamples;
    std::shared_ptr<invisible_places::io::LoadedPointCloud> offlinePointCloud;
    // Lazily computed per-field histograms for the Visuals-tab bounds
    // editor. Entries are keyed by field slot plus the payload generation
    // and cloud identity so reloads recompute; failures are cached too so a
    // missing source is not re-probed every frame.
    struct VisualsFieldHistogramEntry {
        std::int32_t fieldSlot = -1;
        std::uint64_t contentGeneration = 0U;
        const void* cloudIdentity = nullptr;
        bool computed = false;
        invisible_places::timing::TimingColouriseHistogram histogram{};
        std::vector<std::uint64_t> displayBins;
    };
    std::vector<VisualsFieldHistogramEntry> visualsFieldHistograms;
    std::vector<std::uint32_t> previewLodSampledIndices;
    std::uint32_t previewLodRequestedDrawCount = 0;
    std::uint32_t previewLodSampledDrawCount = 0;
    PointBudgetState pointBudget{};
    PointCloudStyleState pointStyle{};
    std::vector<SavedPointVisualState> pointVisuals;
    std::string selectedPointVisualName = std::string{kDefaultPointVisualName};
    std::string pointVisualNameBuffer = std::string{kDefaultPointVisualName};
    GaussianSplatStyleState gsplatStyle{};
};

