const invisible_places::water::WaterScenarioDefinition* FindWaterScenarioDefinition(
    const WaterWorkflowState& water,
    std::string_view scenarioId) {
    const auto scenarioIt = std::find_if(
        water.seepageScenarios.begin(),
        water.seepageScenarios.end(),
        [&](const auto& scenario) { return scenario.id == scenarioId; });
    return scenarioIt != water.seepageScenarios.end() ? &*scenarioIt : nullptr;
}

// Saved/edited resolution: live preview prefers the in-progress edited copy
// so scrubbing shows what is being tuned, while fallback snapshots and
// default exports keep reading the saved definition.
const invisible_places::water::WaterScenarioDefinition* ViewedWaterScenarioDefinition(
    const WaterWorkflowState& water,
    std::string_view scenarioId) {
    if (water.editedScenario.has_value() && water.editedScenario->id == scenarioId) {
        return &water.editedScenario.value();
    }
    return FindWaterScenarioDefinition(water, scenarioId);
}

invisible_places::water::WaterScenarioState* EditWaterScenarioStateById(
    WaterWorkflowState* water,
    const std::string& scenarioId) {
    if (water == nullptr || scenarioId.empty()) {
        return nullptr;
    }
    if (water->editedScenario.has_value() && water->editedScenario->id == scenarioId) {
        return &water->editedScenario->state;
    }
    const auto* definition = FindWaterScenarioDefinition(*water, scenarioId);
    if (definition == nullptr) {
        return nullptr;
    }
    // Editing a different scenario replaces the single shadow; the Timings
    // Scenario section warns before that happens.
    water->editedScenario = *definition;
    water->editedScenario->name = definition->name + "_edited";
    return &water->editedScenario->state;
}

std::vector<invisible_places::water::WaterScenarioDefinition> ExportWaterScenarioDefinitions(
    const PreviewRuntimeState& runtimeState) {
    auto scenarios = runtimeState.water.seepageScenarios;
    if (runtimeState.exportUsesEditedScenario &&
        runtimeState.water.editedScenario.has_value()) {
        const auto replaceIt = std::find_if(
            scenarios.begin(),
            scenarios.end(),
            [&](const auto& scenario) {
                return scenario.id == runtimeState.water.editedScenario->id;
            });
        if (replaceIt != scenarios.end()) {
            *replaceIt = runtimeState.water.editedScenario.value();
        }
    }
    return scenarios;
}

std::string WaterScenarioDisplayName(
    std::span<const invisible_places::water::WaterScenarioDefinition> definitions,
    const AnimationPath& animation) {
    if (animation.selectedWaterScenarioId.empty()) {
        return {};
    }
    const auto definitionIt = std::find_if(
        definitions.begin(),
        definitions.end(),
        [&](const auto& definition) {
            return definition.id == animation.selectedWaterScenarioId;
        });
    if (definitionIt != definitions.end() && !definitionIt->name.empty()) {
        return definitionIt->name;
    }
    const auto trackIt = std::find_if(
        animation.waterScenarioTracks.begin(),
        animation.waterScenarioTracks.end(),
        [&](const auto& track) {
            return track.scenarioId == animation.selectedWaterScenarioId;
        });
    if (trackIt != animation.waterScenarioTracks.end()) {
        if (!trackIt->scenarioName.empty()) {
            return trackIt->scenarioName;
        }
        if (!trackIt->fallbackScenario.name.empty()) {
            return trackIt->fallbackScenario.name;
        }
    }
    return animation.selectedWaterScenarioId;
}

std::string AnimationNameWithWaterScenario(
    std::string animationName,
    std::span<const invisible_places::water::WaterScenarioDefinition> /*definitions*/,
    const AnimationPath& /*animation*/) {
    // Legacy scenario selections no longer alter authored Timing Take output
    // names. Keep the compatibility wrapper while old animation data remains
    // parseable and round-trippable.
    return animationName;
}

std::optional<invisible_places::water::WaterScenarioState> ResolveActiveWaterScenarioState(
    const PreviewRuntimeState& runtimeState,
    bool /*useEditedScenario*/ = true) {
    // Legacy scenario definitions and aggregate animation tracks remain
    // parseable, but no longer participate in preview or export. This
    // always-present carrier starts from authored controls; explicit tracks
    // in the active Timing Take are applied later.
    invisible_places::water::WaterScenarioState state;
    state.seepageLevel = 1.0F;
    state.seepageSpread = 0.0F;
    state.rainLevel =
        runtimeState.water.collisionRainSettings.enabled
            ? std::clamp(
                  runtimeState.water.collisionRainSettings.rainLevel,
                  0.0F,
                  1.0F)
            : 0.0F;
    state.flowLevel = 1.0F;
    state.shorelineLevel = 1.0F;
    const auto& mesh = runtimeState.water.dynamicMeshFlowSettings;
    state.meshFlowLevel = std::clamp(mesh.activity, 0.0F, 1.0F);
    state.meshFlowRainGain = std::max(0.0F, mesh.rainGain);
    state.meshFlowPersistenceScale =
        std::max(0.0F, mesh.moisturePersistenceMultiplier);
    state.meshFlowRainRiseSeconds = std::max(0.0F, mesh.rainRiseSeconds);
    state.meshFlowRainRecessionSeconds =
        std::max(0.0F, mesh.rainRecessionSeconds);
    state.seepageRainDelaySeconds = 0.0F;
    state.seepageRainRiseSeconds = 0.0F;
    state.seepageRainRecessionSeconds = 0.0F;
    state.transitionLook.reset();
    state.transitionAmount = 0.0F;
    return state;
}

std::string ActiveWaterTimingSceneGroupName(
    const WaterWorkflowState& water) {
    if (!water.authoritativeWaterSurfaceSceneGroupName.empty()) {
        return water.authoritativeWaterSurfaceSceneGroupName;
    }
    if (!water.activeWaterSurfaceSceneGroupName.empty()) {
        return water.activeWaterSurfaceSceneGroupName;
    }
    return "Default";
}

const invisible_places::timing::TimingTakeSceneState*
FindScenarioFeatureRuns(
    const WaterWorkflowState& water,
    const std::string& takeId) {
    if (takeId.empty()) {
        return nullptr;
    }
    return invisible_places::timing::FindTimingTakeSceneState(
        water.timingTakeSceneStates,
        takeId,
        ActiveWaterTimingSceneGroupName(water));
}

invisible_places::water::WaterFeatureTimeline*
FindMutableWaterFeatureTimeline(
    WaterWorkflowState* water,
    const std::string& takeId,
    const invisible_places::water::WaterKeyedFeatureId& feature) {
    if (water == nullptr || takeId.empty()) {
        return nullptr;
    }
    auto* entry = invisible_places::timing::FindTimingTakeSceneState(
        &water->timingTakeSceneStates,
        takeId,
        ActiveWaterTimingSceneGroupName(*water));
    if (entry == nullptr) {
        return nullptr;
    }
    for (auto& run : entry->waterFeatureTimingRuns) {
        if (auto* timeline =
                invisible_places::water::FindWaterFeatureTimeline(
                    &run,
                    feature);
            timeline != nullptr) {
            return timeline;
        }
    }
    return nullptr;
}

invisible_places::water::WaterKeyedSettingTrack*
FindMutableWaterSettingTrack(
    WaterWorkflowState* water,
    const std::string& scenarioId,
    const invisible_places::water::WaterKeyedFeatureId& feature,
    std::string_view settingId) {
    auto* timeline =
        FindMutableWaterFeatureTimeline(
            water,
            scenarioId,
            feature);
    if (timeline == nullptr) {
        return nullptr;
    }
    const auto setting = std::find_if(
        timeline->settings.begin(),
        timeline->settings.end(),
        [&](const auto& candidate) {
            return candidate.settingId == settingId;
        });
    return setting != timeline->settings.end()
               ? &*setting
               : nullptr;
}

invisible_places::timing::TimingTakeSceneState& EnsureScenarioFeatureRuns(
    WaterWorkflowState* water,
    const std::string& takeId) {
    return *invisible_places::timing::EnsureTimingTakeSceneState(
        &water->timingTakeSceneStates,
        takeId,
        ActiveWaterTimingSceneGroupName(*water));
}

std::string ActiveWaterTimingScenarioId(
    const PreviewRuntimeState& runtimeState) {
    if (runtimeState.animationPanel.currentPath.has_value() &&
        !runtimeState.animationPanel.currentPath->selectedTimingTakeId
             .empty()) {
        const auto requested =
            invisible_places::timing::NormalizeTimingTakeId(
                runtimeState.animationPanel.currentPath
                    ->selectedTimingTakeId);
        if (invisible_places::timing::FindTimingTakeDefinition(
                runtimeState.water.timingTakes,
                requested) != nullptr) {
            return requested;
        }
    }
    const auto selected =
        invisible_places::timing::NormalizeTimingTakeId(
            runtimeState.water.selectedTimingTakeId);
    return invisible_places::timing::FindTimingTakeDefinition(
               runtimeState.water.timingTakes,
               selected) != nullptr
               ? selected
               : std::string{
                     invisible_places::timing::
                         kAuthoredTimingTakeId};
}

struct ResolvedLiveRainProfile {
    std::string takeId;
    invisible_places::timing::TimingTakeDefinition* take = nullptr;
    WaterRainProfile* effective = nullptr;
    WaterRainProfile* base = nullptr;
};

ResolvedLiveRainProfile ResolveLiveRainProfile(
    WaterWorkflowState* water,
    std::string_view requestedTakeId) {
    ResolvedLiveRainProfile result;
    if (water == nullptr) {
        return result;
    }
    result.takeId = invisible_places::timing::NormalizeTimingTakeId(
        requestedTakeId);
    result.take = invisible_places::timing::FindTimingTakeDefinition(
        &water->timingTakes,
        result.takeId);
    if (result.take == nullptr) {
        result.takeId = std::string{
            invisible_places::timing::kAuthoredTimingTakeId};
        result.take = invisible_places::timing::FindTimingTakeDefinition(
            &water->timingTakes,
            result.takeId);
    }
    if (result.take == nullptr) {
        return result;
    }
    result.effective = const_cast<WaterRainProfile*>(
        invisible_places::timing::ResolveTimingTakeRainProfile(
            water->rainProfiles,
            *result.take));
    if (result.effective != nullptr &&
        result.effective->objectOverride) {
        // An owner copy's own stable base identity is authoritative. Falling
        // through to a stale take mirror would make the panel label and
        // bracket one base while exact Save correctly overwrites another.
        const WaterRainProfile* ownerBase = nullptr;
        if (!result.effective->baseProfileId.empty()) {
            ownerBase = invisible_places::water::FindWaterRainProfileById(
                water->rainProfiles,
                result.effective->baseProfileId);
        } else if (!result.effective->baseProfileName.empty()) {
            ownerBase = invisible_places::water::FindWaterRainProfileByName(
                water->rainProfiles,
                result.effective->baseProfileName);
        }
        if (ownerBase != nullptr && !ownerBase->objectOverride) {
            result.base = const_cast<WaterRainProfile*>(ownerBase);
        }
    } else {
        result.base = const_cast<WaterRainProfile*>(
            invisible_places::timing::ResolveTimingTakeRainBaseProfile(
                water->rainProfiles,
                *result.take));
    }
    return result;
}

ResolvedLiveRainProfile ResolveActiveLiveRainProfile(
    PreviewRuntimeState* runtimeState) {
    return runtimeState == nullptr
               ? ResolvedLiveRainProfile{}
               : ResolveLiveRainProfile(
                     &runtimeState->water,
                     ActiveWaterTimingScenarioId(*runtimeState));
}

std::size_t RewriteTimingTakeRainTrackProfileName(
    WaterWorkflowState* water,
    std::string_view takeId,
    std::string_view profileName) {
    return water == nullptr
               ? 0U
               : invisible_places::timing::
                     RewriteTimingTakeRainTrackProfileMetadata(
                         &water->timingTakeSceneStates,
                         takeId,
                         profileName);
}

void BackfillRainTrackProfileMetadata(WaterWorkflowState* water) {
    if (water == nullptr) {
        return;
    }
    for (auto& state : water->timingTakeSceneStates) {
        const auto resolved = ResolveLiveRainProfile(
            water,
            state.takeId);
        if (resolved.effective == nullptr) {
            continue;
        }
        (void)RewriteTimingTakeRainTrackProfileName(
            water,
            state.takeId,
            resolved.effective->name);
    }
    (void)invisible_places::timing::
        RewriteLegacyScenarioRainTrackProfileMetadata(
            &water->featureTimingRunsByScenario,
            water->rainProfiles,
            water->timingTakes);
}

void EnsureWaterRainProfiles(WaterWorkflowState* water) {
    if (water == nullptr) {
        return;
    }
    if (water->timingTakes.empty() ||
        invisible_places::timing::FindTimingTakeDefinition(
            water->timingTakes,
            invisible_places::timing::kAuthoredTimingTakeId) == nullptr) {
        water->timingTakes.insert(
            water->timingTakes.begin(),
            invisible_places::timing::AuthoredTimingTakeDefinition());
    }
    (void)invisible_places::timing::EnsureLegacyWaterRainProfile(
        &water->rainProfiles,
        &water->timingTakes,
        water->collisionRainSettings,
        water->rainVisual);
    BackfillRainTrackProfileMetadata(water);
    const auto resolved = ResolveLiveRainProfile(
        water,
        water->selectedTimingTakeId);
    if (resolved.base != nullptr &&
        water->rainProfileNameBufferBaseId != resolved.base->id) {
        water->rainProfileNameBuffer = resolved.base->name;
        water->rainProfileNameBufferBaseId = resolved.base->id;
    }
}

bool SynchronizeLiveTimingTakeRain(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    bool forceRefresh = false) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    auto& water = runtimeState->water;
    auto resolved = ResolveActiveLiveRainProfile(runtimeState);
    if (resolved.effective == nullptr || resolved.base == nullptr) {
        EnsureWaterRainProfiles(&water);
        resolved = ResolveActiveLiveRainProfile(runtimeState);
    }
    if (resolved.effective == nullptr || resolved.base == nullptr) {
        return false;
    }
    const auto decision = invisible_places::timing::
        ResolveTimingTakeRainLiveSyncDecision(
            water.liveRainTimingTakeId,
            water.liveRainProfileId,
            resolved.takeId,
            resolved.effective->id,
            forceRefresh);
    if (!decision.copyProfile) {
        return false;
    }
    water.collisionRainSettings = resolved.effective->settings;
    water.rainVisual = resolved.effective->visual;
    water.liveRainTimingTakeId = resolved.takeId;
    water.liveRainProfileId = resolved.effective->id;
    if (water.rainProfileNameBufferBaseId != resolved.base->id) {
        water.rainProfileNameBuffer = resolved.base->name;
        water.rainProfileNameBufferBaseId = resolved.base->id;
    }
    water.seepageParamsFingerprints.clear();
    runtimeState->previewRenderStateSignatureValid = false;
    if (decision.resetRuntime) {
        viewport->ResetRainRuntime();
    }
    return true;
}

WaterRainProfile* CommitActiveTimingTakeRainEdit(
    PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return nullptr;
    }
    auto& water = runtimeState->water;
    auto resolved = ResolveActiveLiveRainProfile(runtimeState);
    if (resolved.take == nullptr || resolved.base == nullptr) {
        return nullptr;
    }
    auto* owner = invisible_places::timing::
        UpsertTimingTakeRainOwnerProfile(
            &water.rainProfiles,
            resolved.take,
            water.collisionRainSettings,
            water.rainVisual);
    if (owner == nullptr) {
        return nullptr;
    }
    // The renderer is already displaying these values. Rebinding the same
    // live state from base to its first COW owner must not restart Rain.
    water.liveRainTimingTakeId = resolved.takeId;
    water.liveRainProfileId = owner->id;
    (void)RewriteTimingTakeRainTrackProfileName(
        &water,
        resolved.takeId,
        owner->name);
    runtimeState->previewRenderStateSignatureValid = false;
    return owner;
}

std::vector<invisible_places::water::WaterFeatureTimingRun>
SnapshotActiveWaterFeatureTimingRuns(
    const PreviewRuntimeState& runtimeState) {
    const auto* entry = FindScenarioFeatureRuns(
        runtimeState.water,
        ActiveWaterTimingScenarioId(runtimeState));
    if (entry == nullptr) {
        return {};
    }
    return entry->waterFeatureTimingRuns;
}

// Snapshot for a job exporting a specific animation, which may not be the
// one loaded in the panel: the runs follow that animation's timing take and
// the active authored scene group.
std::vector<invisible_places::water::WaterFeatureTimingRun>
SnapshotWaterFeatureTimingRunsForAnimation(
    const PreviewRuntimeState& runtimeState,
    const std::optional<AnimationPath>& animationPath) {
    const std::string takeId =
        animationPath.has_value() &&
                !animationPath->selectedTimingTakeId.empty()
            ? animationPath->selectedTimingTakeId
            : runtimeState.water.selectedTimingTakeId;
    const auto* entry =
        FindScenarioFeatureRuns(runtimeState.water, takeId);
    if (entry == nullptr) {
        return {};
    }
    return entry->waterFeatureTimingRuns;
}

const std::vector<invisible_places::timing::TimingColouriseEffect>*
ActiveTimingColouriseEffects(
    const PreviewRuntimeState& runtimeState) {
    const auto* state = FindScenarioFeatureRuns(
        runtimeState.water,
        ActiveWaterTimingScenarioId(runtimeState));
    return state != nullptr ? &state->colouriseEffects : nullptr;
}

std::optional<ResolvedTimingTakeExportSnapshot>
ResolveTimingTakeExportSnapshot(
    const PreviewRuntimeState& runtimeState,
    std::string_view selectedTimingTakeId,
    std::string* errorMessage) {
    const auto takeId =
        invisible_places::timing::NormalizeTimingTakeId(
            selectedTimingTakeId);
    const bool authoredTake =
        takeId == invisible_places::timing::kAuthoredTimingTakeId;
    if (!authoredTake &&
        invisible_places::timing::FindTimingTakeDefinition(
            runtimeState.water.timingTakes,
            takeId) == nullptr) {
        if (errorMessage != nullptr) {
            *errorMessage =
                "The active animation selects missing Timing Take '" +
                takeId + "'. Choose an available Timing Take before "
                         "rendering.";
        }
        return std::nullopt;
    }

    const auto sceneGroupName =
        ActiveWaterTimingSceneGroupName(runtimeState.water);
    const bool hasGroupedAuthoredScene = std::any_of(
        runtimeState.sessions.begin(),
        runtimeState.sessions.end(),
        [](const PreviewLayerSession& session) {
            return session.kind == LayerKind::PointCloud &&
                   !session.sceneGroupName.empty() &&
                   !session.waterFlowSourceId.has_value() &&
                   !session.dynamicMeshFlowGpuPreview &&
                   invisible_places::scene::ParseScenePointCloudRole(
                       session.sceneRole)
                       .has_value();
        });
    const bool activeScenePresent = std::any_of(
        runtimeState.sessions.begin(),
        runtimeState.sessions.end(),
        [&](const PreviewLayerSession& session) {
            return session.kind == LayerKind::PointCloud &&
                   session.sceneGroupName == sceneGroupName &&
                   !session.waterFlowSourceId.has_value() &&
                   !session.dynamicMeshFlowGpuPreview &&
                   invisible_places::scene::ParseScenePointCloudRole(
                       session.sceneRole)
                       .has_value();
        });
    if (hasGroupedAuthoredScene && !activeScenePresent) {
        if (errorMessage != nullptr) {
            *errorMessage =
                "The active Timing scene '" + sceneGroupName +
                "' is not available in the loaded project. Select the "
                "animation's scene before rendering.";
        }
        return std::nullopt;
    }

    ResolvedTimingTakeExportSnapshot snapshot;
    snapshot.takeId = takeId;
    snapshot.sceneGroupName = sceneGroupName;
    snapshot.state.takeId = takeId;
    snapshot.state.sceneGroupName = sceneGroupName;
    if (const auto* state =
            invisible_places::timing::FindTimingTakeSceneState(
                runtimeState.water.timingTakeSceneStates,
                takeId,
                sceneGroupName);
        state != nullptr) {
        snapshot.state = *state;
    }
    snapshot.effectiveRainProfile = invisible_places::timing::
        CaptureTimingTakeRainProfileSnapshot(
            runtimeState.water.rainProfiles,
            runtimeState.water.timingTakes,
            takeId);
    if (!snapshot.effectiveRainProfile.has_value()) {
        if (errorMessage != nullptr) {
            *errorMessage =
                "Timing Take '" + takeId +
                "' has no effective Rain profile to freeze for rendering.";
        }
        return std::nullopt;
    }
    if (errorMessage != nullptr) {
        errorMessage->clear();
    }
    return snapshot;
}

std::optional<ResolvedTimingTakeExportSnapshot>
ResolveCurrentTimingTakeExportSnapshot(
    const PreviewRuntimeState& runtimeState,
    const AnimationPath& animationPath,
    std::string* errorMessage) {
    return ResolveTimingTakeExportSnapshot(
        runtimeState,
        animationPath.selectedTimingTakeId,
        errorMessage);
}

bool IsAuthoredTimingColouriseLayer(
    const PreviewLayerSession& session) {
    if (session.kind != LayerKind::PointCloud ||
        session.waterFlowSourceId.has_value() ||
        session.dynamicMeshFlowGpuPreview) {
        return false;
    }
    const auto role =
        invisible_places::scene::ParseScenePointCloudRole(
            session.sceneRole);
    return role.has_value();
}

invisible_places::renderer::pointcloud::ResolvedTimingColouriseStack
ResolveTimingColouriseStack(
    std::span<const invisible_places::timing::TimingColouriseEffect>
        effects,
    std::span<const invisible_places::io::ScalarFieldStats> scalarFields,
    bool hasNormals,
    float normalizedPosition,
    bool cyclic) {
    using invisible_places::renderer::pointcloud::
        ResolvedTimingColouriseEffect;
    using invisible_places::renderer::pointcloud::
        ResolvedTimingColouriseStack;
    using invisible_places::renderer::pointcloud::
        TimingColouriseSource;
    using invisible_places::renderer::pointcloud::
        TimingColouriseOutput;
    using invisible_places::timing::TimingColouriseFieldSource;
    using invisible_places::timing::TimingEffectKind;

    ResolvedTimingColouriseStack result;
    struct SelectedEffect {
        const invisible_places::timing::TimingColouriseEffect* effect =
            nullptr;
        TimingColouriseSource source = TimingColouriseSource::ScalarField;
        std::int32_t scalarFieldSlot = -1;
        bool emitColourise = false;
        bool emitEmissive = false;
    };
    std::array<
        SelectedEffect,
        invisible_places::renderer::pointcloud::
            kTimingColouriseMaxEffects>
        selectedEffects{};
    std::size_t selectedEffectCount = 0U;
    std::size_t selectedSlotCount = 0U;

    // Domain list index zero is the top UI layer. Authored lists may be
    // longer than the renderer's concurrent stack, so retain the topmost
    // resolvable effects first (a feature with both aspects enabled costs
    // one renderer slot per aspect). They are emitted bottom-to-top below
    // because later renderer entries win during composition.
    for (const auto& effect : effects) {
        if (!invisible_places::timing::
                TimingColouriseEffectIsActiveAt(
                    effect,
                    normalizedPosition,
                    cyclic)) {
            continue;
        }

        SelectedEffect selected{.effect = &effect};
        // The emissive aspect is deliberately scalar-only. The timing-model
        // sanitizer already enforces this for authored projects, but keep the
        // renderer boundary defensive for transient UI state and old files.
        selected.emitColourise = effect.colouriseEnabled;
        selected.emitEmissive =
            effect.emissiveEnabled &&
            effect.field.source == TimingColouriseFieldSource::Scalar;
        const std::size_t slotCost =
            (selected.emitColourise ? 1U : 0U) +
            (selected.emitEmissive ? 1U : 0U);
        if (slotCost == 0U) {
            continue;
        }
        if (selectedSlotCount + slotCost > selectedEffects.size()) {
            break;
        }
        switch (effect.field.source) {
            case TimingColouriseFieldSource::Scalar: {
                const auto field = std::find_if(
                    scalarFields.begin(),
                    scalarFields.end(),
                    [&](const auto& candidate) {
                        return candidate.name ==
                               effect.field.scalarFieldName;
                    });
                if (field == scalarFields.end()) {
                    continue;
                }
                selected.source = TimingColouriseSource::ScalarField;
                selected.scalarFieldSlot =
                    static_cast<std::int32_t>(
                        std::distance(scalarFields.begin(), field));
                break;
            }
            case TimingColouriseFieldSource::NormalX:
                if (!hasNormals) {
                    continue;
                }
                selected.source = TimingColouriseSource::NormalX;
                break;
            case TimingColouriseFieldSource::NormalY:
                if (!hasNormals) {
                    continue;
                }
                selected.source = TimingColouriseSource::NormalY;
                break;
            case TimingColouriseFieldSource::NormalZ:
                if (!hasNormals) {
                    continue;
                }
                selected.source = TimingColouriseSource::NormalZ;
                break;
        }
        selectedSlotCount +=
            (selected.emitColourise ? 1U : 0U) +
            (selected.emitEmissive ? 1U : 0U);
        selectedEffects[selectedEffectCount++] = selected;
    }

    for (std::size_t selectedIndex = selectedEffectCount;
         selectedIndex > 0U;
         --selectedIndex) {
        const auto& selected = selectedEffects[selectedIndex - 1U];
        const auto& effect = *selected.effect;
        ResolvedTimingColouriseEffect resolved;
        resolved.enabled = true;
        resolved.source = selected.source;
        resolved.scalarFieldSlot = selected.scalarFieldSlot;
        const auto bounds =
            invisible_places::timing::EvaluateTimingColouriseBounds(
                effect,
                normalizedPosition,
                cyclic);
        resolved.lowerBound = bounds.lower;
        resolved.upperBound = bounds.upper;
        resolved.edgeFadeFraction = bounds.edgeFade;
        // A combined Visual Feature occupies one renderer slot per enabled
        // aspect. Slot order between the pair is irrelevant: colourise
        // entries compose by slot order while emissive entries sum.
        if (selected.emitColourise) {
            auto colouriseResolved = resolved;
            colouriseResolved.output = TimingColouriseOutput::Colourise;
            colouriseResolved.rgbaLut =
                invisible_places::timing::
                    EvaluateTimingColourisePaletteLut(
                        effect,
                        normalizedPosition,
                        cyclic);
            result.effects[result.effectCount++] = colouriseResolved;
        }
        if (selected.emitEmissive) {
            auto emissiveResolved = resolved;
            emissiveResolved.output = TimingColouriseOutput::Emissive;
            emissiveResolved.emissiveLevel =
                invisible_places::timing::EvaluateTimingEmissiveLevel(
                    effect,
                    normalizedPosition,
                    cyclic);
            result.effects[result.effectCount++] = emissiveResolved;
        }
    }
    return result;
}

std::uint32_t EffectiveAnimationDurationFramesForTracks(
    const AnimationPath& path) {
    return std::max<std::uint32_t>(
        path.durationFrames,
        path.keys.size() > 1U
            ? static_cast<std::uint32_t>(path.keys.size() - 1U)
            : 1U);
}

std::uint32_t AuthoredAnimationTrackDurationFrames(
    const AnimationPath& path) {
    if (const auto loop = invisible_places::camera::
            ResolveAnimationTimingLoopWindow(path);
        loop.has_value()) {
        return loop->cycleFrames;
    }
    const std::uint32_t cameraFrames =
        EffectiveAnimationDurationFramesForTracks(path);
    // Compatibility for files written by the initial schema-22 extension.
    // Current extensions physically retime their keys and clear this marker,
    // so ordinary paths always use the full camera duration.
    return path.authoredTrackDurationFrames == 0U
               ? cameraFrames
               : std::clamp(
                     path.authoredTrackDurationFrames,
                     1U,
                     cameraFrames);
}

float AuthoredAnimationTrackDurationSeconds(
    const AnimationPath& path) {
    return static_cast<float>(
               AuthoredAnimationTrackDurationFrames(path)) /
           30.0F;
}

std::vector<float> AuthoredTrackNormalizedToCameraNormalizedPositions(
    const AnimationPath& path,
    float trackNormalizedPosition) {
    if (invisible_places::camera::ResolveAnimationTimingLoopWindow(path)
            .has_value()) {
        return invisible_places::camera::
            AnimationTimingLoopPositionToLocalPositions(
                path,
                trackNormalizedPosition);
    }
    const float cameraFrames = static_cast<float>(
        EffectiveAnimationDurationFramesForTracks(path));
    const float trackFrames = static_cast<float>(
        AuthoredAnimationTrackDurationFrames(path));
    return {std::clamp(
                trackNormalizedPosition,
                0.0F,
                1.0F) *
            trackFrames / cameraFrames};
}

float AuthoredTrackNormalizedToCameraNormalized(
    const AnimationPath& path,
    float trackNormalizedPosition) {
    const auto positions =
        AuthoredTrackNormalizedToCameraNormalizedPositions(
            path,
            trackNormalizedPosition);
    return positions.empty()
               ? std::numeric_limits<float>::quiet_NaN()
               : positions.front();
}

float CurrentAuthoredTrackPosition(
    const PreviewRuntimeState& runtimeState) {
    const float cameraPosition = std::clamp(
        runtimeState.animationPanel.scrubAmount,
        0.0F,
        1.0F);
    if (!runtimeState.animationPanel.currentPath.has_value()) {
        return cameraPosition;
    }
    const auto& path = runtimeState.animationPanel.currentPath.value();
    if (invisible_places::camera::ResolveAnimationTimingLoopWindow(path)
            .has_value()) {
        return invisible_places::camera::
            AnimationLocalToTimingLoopPosition(path, cameraPosition);
    }
    const float cameraFrames = static_cast<float>(
        EffectiveAnimationDurationFramesForTracks(path));
    const float trackFrames = static_cast<float>(
        AuthoredAnimationTrackDurationFrames(path));
    return std::clamp(
        cameraPosition * cameraFrames / trackFrames,
        0.0F,
        1.0F);
}

bool CurrentAnimationTimingIsCyclic(
    const PreviewRuntimeState& runtimeState) {
    return runtimeState.animationPanel.currentPath.has_value() &&
        invisible_places::camera::ResolveAnimationTimingLoopWindow(
            runtimeState.animationPanel.currentPath.value())
            .has_value();
}

void SetCurrentAnimationPositionFromAuthoredTrack(
    PreviewRuntimeState* runtimeState,
    float trackPosition) {
    if (runtimeState == nullptr) {
        return;
    }
    float cameraPosition = std::clamp(trackPosition, 0.0F, 1.0F);
    if (runtimeState->animationPanel.currentPath.has_value()) {
        const auto& path = runtimeState->animationPanel.currentPath.value();
        if (invisible_places::camera::ResolveAnimationTimingLoopWindow(path)
                .has_value()) {
            const auto positions = invisible_places::camera::
                AnimationTimingLoopPositionToLocalPositions(
                    path,
                    cameraPosition);
            if (positions.empty()) {
                return;
            }
            cameraPosition = *std::min_element(
                positions.begin(),
                positions.end(),
                [&](float left, float right) {
                    return std::abs(
                               left - runtimeState->animationPanel.scrubAmount) <
                           std::abs(
                               right - runtimeState->animationPanel.scrubAmount);
                });
        } else {
            cameraPosition = AuthoredTrackNormalizedToCameraNormalized(
                path,
                cameraPosition);
        }
    }
    runtimeState->animationPanel.scrubAmount = cameraPosition;
}

struct WaterFrameState {
    float normalizedTime = 0.0F;
    float sampleTimeSeconds = 0.0F;
    bool timingIsCyclic = false;
    float meshFlowMoisture = 0.0F;
    std::optional<invisible_places::water::WaterScenarioState> rawScenarioState;
    std::optional<invisible_places::water::WaterScenarioState> seepageScenarioState;
    std::vector<invisible_places::water::WaterSeepageNodeAnimationStateEntry> nodeStates;
    // Timings v2: every keyed (feature, setting) sampled at normalizedTime.
    invisible_places::water::WaterFeatureTimingOverlay featureOverlay;
};

std::optional<float> WaterFrameExplicitRainLevel(
    const WaterFrameState& frame) {
    const auto* level = frame.featureOverlay.Find(
        {.kind = invisible_places::water::
             WaterKeyedFeatureKind::Rain},
        "level");
    return level != nullptr
               ? std::optional<float>{*level}
               : std::nullopt;
}

// Applies the Timings v2 keyed-setting overlay onto a resolved water frame:
// global levels override the scenario channels (including the delayed
// seepage rain and mesh-flow moisture, which follow the keyed instantaneous
// rain), and per-node samples become absolute parameter overrides.
template <typename ResolveAuthoredLook>
void ApplyWaterFeatureTimingRunsToFrame(
    std::span<const invisible_places::water::WaterFeatureTimingRun> runs,
    bool onlyShowRunFeatures,
    WaterFrameState* frame,
    ResolveAuthoredLook&& resolveAuthoredLook) {
    if (frame == nullptr) {
        return;
    }
    frame->featureOverlay =
        invisible_places::water::BuildWaterFeatureTimingOverlay(
            runs,
            frame->normalizedTime,
            frame->timingIsCyclic,
            onlyShowRunFeatures);
    const auto& overlay = frame->featureOverlay;
    if (overlay.samples.empty()) {
        return;
    }
    if (frame->rawScenarioState.has_value()) {
        invisible_places::water::ApplyWaterFeatureTimingOverlayToScenario(
            overlay,
            &frame->rawScenarioState.value());
    }
    if (frame->seepageScenarioState.has_value()) {
        invisible_places::water::ApplyWaterFeatureTimingOverlayToScenario(
            overlay,
            &frame->seepageScenarioState.value());
    }
    if (const auto* rain = overlay.Find(
            {.kind = invisible_places::water::WaterKeyedFeatureKind::Rain},
            "level");
        rain != nullptr) {
        frame->meshFlowMoisture = std::clamp(*rain, 0.0F, 1.0F);
    }
    for (const auto& sample : overlay.samples) {
        if (sample.feature.kind !=
            invisible_places::water::WaterKeyedFeatureKind::SeepageNode) {
            continue;
        }
        auto entryIt = std::find_if(
            frame->nodeStates.begin(),
            frame->nodeStates.end(),
            [&](const auto& entry) {
                return entry.nodeId == sample.feature.objectId;
            });
        if (entryIt == frame->nodeStates.end()) {
            frame->nodeStates.push_back({
                .nodeId = sample.feature.objectId,
                .state = {},
            });
            entryIt = std::prev(frame->nodeStates.end());
        }
        const float value = std::max(0.0F, sample.value);
        if (sample.settingId == "strength") {
            entryIt->state.strengthOverride = value;
        } else if (sample.settingId == "prominence") {
            entryIt->state.prominenceOverride = value;
        } else if (sample.settingId == "source_width") {
            entryIt->state.sourceWidthOverride = value;
        } else if (
            sample.settingId.starts_with("look.") ||
            sample.settingId.starts_with("response.")) {
            if (!entryIt->state.lookOverride.has_value()) {
                const auto authoredLook =
                    resolveAuthoredLook(sample.feature.objectId);
                entryIt->state.lookOverride = authoredLook.value_or(
                    invisible_places::water::
                        DefaultWaterSeepageLookSettings());
            }
            (void)invisible_places::water::
                ApplyWaterSeepageLookTimingValue(
                    &entryIt->state.lookOverride.value(),
                    sample.settingId,
                    sample.value);
        }
    }
}

void SuppressUnassignedWaterSeepageNode(
    const invisible_places::water::WaterFeatureTimingOverlay& overlay,
    std::uint32_t nodeId,
    std::vector<invisible_places::water::
                    WaterSeepageNodeAnimationStateEntry>* states) {
    if (states == nullptr ||
        overlay.Allows({
            .kind = invisible_places::water::WaterKeyedFeatureKind::
                SeepageNode,
            .objectId = nodeId})) {
        return;
    }
    auto state = std::find_if(
        states->begin(),
        states->end(),
        [nodeId](const auto& candidate) {
            return candidate.nodeId == nodeId;
        });
    if (state == states->end()) {
        states->push_back({
            .nodeId = nodeId,
            .state = {},
        });
        state = std::prev(states->end());
    }
    state->state.activity = 0.0F;
}

WaterFrameState ResolveWaterFrameStateBase(
    PreviewRuntimeState* runtimeState) {
    WaterFrameState result;
    if (runtimeState == nullptr) {
        return result;
    }
    // This is the keyed-settings position, not the procedural effect clock.
    // Marker-zero/current paths map directly to the camera position; the
    // helper only preserves files written by the initial schema-22 extension
    // until their keys are physically migrated by a later extension.
    result.normalizedTime = CurrentAuthoredTrackPosition(*runtimeState);
    result.rawScenarioState = ResolveActiveWaterScenarioState(*runtimeState);
    result.seepageScenarioState = result.rawScenarioState;
    if (result.rawScenarioState.has_value()) {
        result.meshFlowMoisture =
            std::clamp(result.rawScenarioState->rainLevel, 0.0F, 1.0F);
    }
    if (!runtimeState->animationPanel.currentPath.has_value()) {
        return result;
    }

    const auto& animation = runtimeState->animationPanel.currentPath.value();
    result.timingIsCyclic = invisible_places::camera::
        ResolveAnimationTimingLoopWindow(animation).has_value();
    const float durationSeconds = std::max(
        1.0e-6F,
        AuthoredAnimationTrackDurationSeconds(animation));
    result.sampleTimeSeconds =
        result.normalizedTime * durationSeconds;
    return result;
}

WaterFrameState ResolveWaterFrameState(
    PreviewRuntimeState* runtimeState) {
    auto result = ResolveWaterFrameStateBase(runtimeState);
    if (runtimeState != nullptr) {
        const auto* entry = FindScenarioFeatureRuns(
            runtimeState->water,
            ActiveWaterTimingScenarioId(*runtimeState));
        const std::span<const invisible_places::water::WaterFeatureTimingRun>
            runs =
                entry != nullptr
                    ? std::span{
                          entry->waterFeatureTimingRuns.data(),
                          entry->waterFeatureTimingRuns.size()}
                    : std::span<
                          const invisible_places::water::
                              WaterFeatureTimingRun>{};
        if (entry != nullptr) {
            ApplyWaterFeatureTimingRunsToFrame(
                runs,
                entry->onlyShowWaterFeaturesInRuns,
                &result,
                [&](std::uint32_t nodeId)
                    -> std::optional<WaterSeepageLookSettings> {
                    const auto node = std::find_if(
                        runtimeState->water.seepageNodes.begin(),
                        runtimeState->water.seepageNodes.end(),
                        [nodeId](const WaterSeepageNode& candidate) {
                            return candidate.id == nodeId;
                        });
                    if (node == runtimeState->water.seepageNodes.end()) {
                        return std::nullopt;
                    }
                    return invisible_places::water::
                        ResolveWaterSeepageLook(
                            *node,
                            runtimeState->water.seepageLookProfiles,
                            runtimeState->water.seepageResponseProfiles,
                            runtimeState->water.defaultSeepageLook);
                });
        }
        const float authoredRainLevel =
            runtimeState->water.collisionRainSettings.enabled
                ? std::clamp(
                      runtimeState->water.collisionRainSettings.rainLevel,
                      0.0F,
                      1.0F)
                : 0.0F;
        if (runtimeState->animationPanel.currentPath.has_value()) {
            const float durationSeconds = std::max(
                1.0e-6F,
                AuthoredAnimationTrackDurationSeconds(
                    runtimeState->animationPanel.currentPath.value()));
            const auto meshFingerprint =
                invisible_places::water::
                    WaterMeshFlowRainEnvelopeFingerprint(
                        runtimeState->water.dynamicMeshFlowSettings,
                        runs,
                        authoredRainLevel,
                        durationSeconds);
            auto& meshEnvelope =
                runtimeState->animationPanel.meshFlowRainEnvelopeCache;
            if (meshEnvelope.fingerprint != meshFingerprint) {
                meshEnvelope =
                    invisible_places::water::
                        BuildWaterMeshFlowRainEnvelope(
                            runtimeState->water.dynamicMeshFlowSettings,
                            runs,
                            authoredRainLevel,
                            durationSeconds);
            }
            result.meshFlowMoisture =
                invisible_places::water::
                    EvaluateWaterMeshFlowRainEnvelope(
                        meshEnvelope,
                        result.sampleTimeSeconds);

            constexpr std::size_t kMaximumCachedNodeRainEnvelopes = 128U;
            for (const auto& node : runtimeState->water.seepageNodes) {
                const auto fingerprint =
                    invisible_places::water::
                        WaterSeepageNodeRainEnvelopeFingerprint(
                            node,
                            runs,
                            authoredRainLevel,
                            durationSeconds);
                auto& cache =
                    runtimeState->animationPanel
                        .seepageNodeRainEnvelopeCache;
                auto cached = cache.find(fingerprint);
                if (cached == cache.end()) {
                    while (
                        cache.size() >=
                            kMaximumCachedNodeRainEnvelopes &&
                        !runtimeState->animationPanel
                             .seepageNodeRainEnvelopeCacheOrder
                             .empty()) {
                        cache.erase(
                            runtimeState->animationPanel
                                .seepageNodeRainEnvelopeCacheOrder
                                .front());
                        runtimeState->animationPanel
                            .seepageNodeRainEnvelopeCacheOrder
                            .pop_front();
                    }
                    cached = cache
                                 .emplace(
                                     fingerprint,
                                     invisible_places::water::
                                         BuildWaterSeepageNodeRainEnvelope(
                                             node,
                                             runs,
                                             authoredRainLevel,
                                             durationSeconds))
                                 .first;
                    runtimeState->animationPanel
                        .seepageNodeRainEnvelopeCacheOrder
                        .push_back(fingerprint);
                }
                auto state = std::find_if(
                    result.nodeStates.begin(),
                    result.nodeStates.end(),
                    [&](const auto& candidate) {
                        return candidate.nodeId == node.id;
                    });
                if (state == result.nodeStates.end()) {
                    result.nodeStates.push_back({
                        .nodeId = node.id,
                        .state = {},
                    });
                    state = std::prev(result.nodeStates.end());
                }
                state->state.rainLevelOverride =
                    invisible_places::water::
                        EvaluateWaterSeepageRainEnvelope(
                            cached->second,
                            result.sampleTimeSeconds);
            }
        } else {
            const float immediateRain =
                result.rawScenarioState.has_value()
                    ? std::clamp(
                          result.rawScenarioState->rainLevel,
                          0.0F,
                          1.0F)
                    : authoredRainLevel;
            result.meshFlowMoisture = immediateRain;
            for (const auto& node : runtimeState->water.seepageNodes) {
                result.nodeStates.push_back({
                    .nodeId = node.id,
                    .state = {
                        .rainLevelOverride = immediateRain,
                    },
                });
            }
        }
        for (const auto& node : runtimeState->water.seepageNodes) {
            SuppressUnassignedWaterSeepageNode(
                result.featureOverlay,
                node.id,
                &result.nodeStates);
        }
    }
    return result;
}

struct WaterFlowSourceActivityParameters {
    float maximumFlowStrength = 1.0F;
    float rainResponse = 0.0F;
    bool showTrail = true;
    invisible_places::water::WaterKeyedFeatureKind featureKind =
        invisible_places::water::WaterKeyedFeatureKind::FlowSource;
};

std::optional<WaterFlowSourceActivityParameters> ResolveWaterFlowSourceActivityParameters(
    const WaterWorkflowState& water,
    std::optional<std::uint32_t> sourceId,
    const invisible_places::water::WaterFeatureTimingOverlay* overlay = nullptr) {
    if (!sourceId.has_value()) {
        return std::nullopt;
    }
    const auto applyOverlay = [&](WaterFlowSourceActivityParameters parameters,
                                  invisible_places::water::WaterKeyedFeatureKind kind) {
        if (overlay != nullptr) {
            const invisible_places::water::WaterKeyedFeatureId feature{
                .kind = kind,
                .objectId = sourceId.value(),
            };
            if (!overlay->Allows(feature)) {
                parameters.maximumFlowStrength = 0.0F;
                parameters.rainResponse = 0.0F;
                parameters.showTrail = false;
                return parameters;
            }
            if (const auto* strength = overlay->Find(feature, "strength");
                strength != nullptr) {
                parameters.maximumFlowStrength = std::max(0.0F, *strength);
            }
            if (const auto* response = overlay->Find(feature, "rain_response");
                response != nullptr) {
                parameters.rainResponse = std::max(0.0F, *response);
            }
        }
        return parameters;
    };
    const auto emitterIt = std::find_if(
        water.emitters.begin(),
        water.emitters.end(),
        [&](const WaterEmitter& emitter) { return emitter.id == sourceId.value(); });
    if (emitterIt != water.emitters.end()) {
        return applyOverlay(
            WaterFlowSourceActivityParameters{
                .maximumFlowStrength = emitterIt->maximumFlowStrength,
                .rainResponse = emitterIt->rainResponse,
                .showTrail = emitterIt->showTrail,
                .featureKind = invisible_places::water::
                    WaterKeyedFeatureKind::FlowSource,
            },
            invisible_places::water::WaterKeyedFeatureKind::FlowSource);
    }
    const auto manualIt = std::find_if(
        water.manualFlowPaths.begin(),
        water.manualFlowPaths.end(),
        [&](const WaterManualFlowPathSource& source) { return source.id == sourceId.value(); });
    if (manualIt != water.manualFlowPaths.end()) {
        return applyOverlay(
            WaterFlowSourceActivityParameters{
                .maximumFlowStrength = manualIt->maximumFlowStrength,
                .rainResponse = manualIt->rainResponse,
                .showTrail = manualIt->showTrail,
                .featureKind = invisible_places::water::
                    WaterKeyedFeatureKind::FlowPath,
            },
            invisible_places::water::WaterKeyedFeatureKind::FlowPath);
    }
    return std::nullopt;
}

float ResolveWaterFlowSourceActivity(
    const WaterWorkflowState& water,
    std::optional<std::uint32_t> sourceId,
    const std::optional<invisible_places::water::WaterScenarioState>& scenarioState,
    const invisible_places::water::WaterFeatureTimingOverlay* overlay = nullptr) {
    const auto parameters =
        ResolveWaterFlowSourceActivityParameters(water, sourceId, overlay);
    if (!parameters.has_value()) {
        return 1.0F;
    }
    const auto authoredState =
        scenarioState.value_or(
            invisible_places::water::WaterScenarioState{});
    return invisible_places::water::
        EffectiveAuthoredWaterFlowActivity(
        authoredState.rainLevel,
        parameters->maximumFlowStrength,
        parameters->rainResponse,
        parameters->showTrail,
        water.showFlowTrails);
}

void ApplyWaterFlowSourceActivityToStyle(
    const WaterWorkflowState& water,
    const PreviewLayerSession& session,
    const std::optional<invisible_places::water::WaterScenarioState>& scenarioState,
    PointCloudStyleState* style,
    const invisible_places::water::WaterFeatureTimingOverlay* overlay = nullptr) {
    if (style == nullptr || !session.waterFlowSourceId.has_value()) {
        return;
    }
    style->waterFlowActivity = ResolveWaterFlowSourceActivity(
        water,
        session.waterFlowSourceId,
        scenarioState,
        overlay);
    const auto parameters = ResolveWaterFlowSourceActivityParameters(
        water,
        session.waterFlowSourceId,
        nullptr);
    if (overlay == nullptr || !parameters.has_value() ||
        parameters->featureKind !=
            invisible_places::water::WaterKeyedFeatureKind::FlowPath) {
        return;
    }

    const invisible_places::water::WaterKeyedFeatureId feature{
        .kind = invisible_places::water::WaterKeyedFeatureKind::FlowPath,
        .objectId = session.waterFlowSourceId.value(),
    };
    if (const auto* speed = overlay->Find(feature, "speed");
        speed != nullptr) {
        const float bakedSpeed = std::max(
            1.0e-5F,
            session.waterFlowBakedSpeedMetersPerSecond);
        style->waterFlowSpeedScale =
            std::max(0.0F, *speed) / bakedSpeed;
    }

    const bool hasStyleGeometry =
        style->waterTrailStyleGeometry &&
        style->surfelDiameter.active &&
        style->surfelDiameter.mode == ParameterSourceMode::Constant;
    if (!hasStyleGeometry) {
        return;
    }
    const float authoredWidth = std::max(
        0.0005F,
        style->surfelDiameter.constantValue[0]);
    const float authoredStreak = std::max(
        authoredWidth,
        authoredWidth * std::max(1.0F, style->waterStreakAspect));
    const auto* keyedWidth = overlay->Find(feature, "trail_width");
    const auto* keyedStreak =
        overlay->Find(feature, "trail_streak_length");
    if (keyedWidth == nullptr && keyedStreak == nullptr) {
        return;
    }
    const float width = std::clamp(
        keyedWidth != nullptr ? *keyedWidth : authoredWidth,
        0.0005F,
        1.0F);
    const float streak = std::max(
        width,
        std::clamp(
            keyedStreak != nullptr ? *keyedStreak : authoredStreak,
            0.001F,
            5.0F));
    invisible_places::style::SetScalarConstant(
        &style->surfelDiameter,
        width);
    invisible_places::style::SetScalarConstant(
        &style->pointSize,
        width * 1000.0F);
    style->waterStreakAspect =
        std::clamp(streak / width, 1.0F, 32.0F);
}

// The renderer transports the first Water-owned Shoreline effect through a
// per-frame point-style copy, so the scenario's keyed level scales that copy
// only. Neither the Water profile nor a saved Visual is mutated, and no
// topology rebuild happens when the level changes.
void ApplyWaterShorelineLevelToStyle(
    const std::optional<invisible_places::water::WaterScenarioState>& scenarioState,
    PointCloudStyleState* style) {
    if (style == nullptr || !style->shorelineWaveEnabled ||
        !scenarioState.has_value()) {
        return;
    }
    const float level = std::clamp(scenarioState->shorelineLevel, 0.0F, 1.0F);
    if (level >= 1.0F) {
        return;
    }
    if (level <= 1.0e-5F) {
        style->shorelineWaveEnabled = false;
        return;
    }
    style->shorelineIntensity *= level;
    style->shorelineEmissionAdd *= level;
    style->shorelineOpacityAdd *= level;
    style->shorelinePointSizeAdd *= level;
    style->shorelineColourMix *= level;
    style->shorelineOpacityMultiply = std::lerp(1.0F, style->shorelineOpacityMultiply, level);
    style->shorelinePointSizeMultiply = std::lerp(1.0F, style->shorelinePointSizeMultiply, level);
    auto& foam = style->shorelineHeightFoam;
    foam.intensity *= level;
    foam.emissionAdd *= level;
    foam.opacityAdd *= level;
    foam.pointSizeAdd *= level;
    foam.colourMix *= level;
    foam.opacityMultiply = std::lerp(1.0F, foam.opacityMultiply, level);
    foam.pointSizeMultiply = std::lerp(1.0F, foam.pointSizeMultiply, level);
}

void ApplyWaterShorelineLevelToSettings(
    const std::optional<invisible_places::water::WaterScenarioState>&
        scenarioState,
    PointCloudShorelineWaveSettings* settings) {
    if (settings == nullptr || !settings->enabled) {
        return;
    }
    PointCloudStyleState transport;
    invisible_places::renderer::pointcloud::
        ApplyPointCloudShorelineWaveSettings(
            &transport,
            *settings);
    ApplyWaterShorelineLevelToStyle(
        scenarioState,
        &transport);
    *settings = invisible_places::renderer::pointcloud::
        ExtractPointCloudShorelineWaveSettings(transport);
}

void ClearPointCloudStyleShoreline(PointCloudStyleState* style) {
    if (style == nullptr) {
        return;
    }
    invisible_places::renderer::pointcloud::
        ApplyPointCloudShorelineWaveSettings(
            style,
            PointCloudShorelineWaveSettings{});
}

// Resolves the frame's complete project-owned Shoreline list. Disabled
// effects drop, keyed setting tracks replace authored visual scalars, and the
// global Shoreline level scales every effect uniformly. Authored Water state
// and saved point visuals are never mutated.
std::vector<PointCloudShorelineWaveSettings>
ResolveShorelinesForFrame(
    const std::vector<PointCloudShorelineInstance>& instances,
    const invisible_places::water::WaterFeatureTimingOverlay* overlay,
    const std::optional<invisible_places::water::WaterScenarioState>&
        scenarioState = std::nullopt) {
    std::vector<PointCloudShorelineWaveSettings> resolved;
    for (const auto& instance : instances) {
        if (resolved.size() >=
            invisible_places::renderer::pointcloud::
                kMaxShorelineInstances) {
            break;
        }
        if (!instance.enabled || !instance.settings.enabled) {
            continue;
        }
        const invisible_places::water::WaterKeyedFeatureId feature{
            .kind = invisible_places::water::WaterKeyedFeatureKind::
                ShorelineInstance,
            .objectId = instance.id};
        if (overlay != nullptr && !overlay->Allows(feature)) {
            continue;
        }
        auto settings = instance.settings;
        if (overlay != nullptr) {
            const auto keyed = [&](const char* settingId) {
                return overlay->Find(feature, settingId);
            };
            const auto applyScalarOverrides = [&](auto& bank) {
                if (const auto* value = keyed("intensity")) {
                    bank.intensity = std::max(0.0F, *value);
                }
                if (const auto* value = keyed("emission_add")) {
                    bank.emissionAdd = std::max(0.0F, *value);
                }
                if (const auto* value = keyed("opacity_add")) {
                    bank.opacityAdd = std::clamp(*value, -1.0F, 2.0F);
                }
                if (const auto* value = keyed("point_size_multiply")) {
                    bank.pointSizeMultiply = std::max(0.0F, *value);
                }
                if (const auto* value = keyed("colour_mix")) {
                    bank.colourMix = std::clamp(*value, 0.0F, 1.0F);
                }
            };
            applyScalarOverrides(settings.foamFronts);
            applyScalarOverrides(settings.heightFoam);
            float level = 1.0F;
            if (const auto* value = keyed("level")) {
                level = std::clamp(*value, 0.0F, 1.0F);
            }
            if (level <= 1.0e-5F) {
                continue;
            }
            if (level < 1.0F) {
                const auto applyLevel = [&](auto& bank) {
                    bank.intensity *= level;
                    bank.emissionAdd *= level;
                    bank.opacityAdd *= level;
                    bank.pointSizeAdd *= level;
                    bank.colourMix *= level;
                    bank.opacityMultiply =
                        std::lerp(1.0F, bank.opacityMultiply, level);
                    bank.pointSizeMultiply =
                        std::lerp(1.0F, bank.pointSizeMultiply, level);
                };
                applyLevel(settings.foamFronts);
                applyLevel(settings.heightFoam);
            }
        }
        ApplyWaterShorelineLevelToSettings(
            scenarioState,
            &settings);
        if (!settings.enabled) {
            continue;
        }
        resolved.push_back(std::move(settings));
    }
    return resolved;
}

std::string ActiveWaterScenarioDisplayName(const PreviewRuntimeState& runtimeState) {
    if (runtimeState.animationPanel.currentPath.has_value() &&
        !runtimeState.animationPanel.currentPath->selectedWaterScenarioId.empty()) {
        return WaterScenarioDisplayName(
            runtimeState.water.seepageScenarios,
            runtimeState.animationPanel.currentPath.value());
    }
    if (runtimeState.water.selectedSeepageScenarioId.empty()) {
        return {};
    }
    if (const auto* definition = FindWaterScenarioDefinition(
            runtimeState.water,
            runtimeState.water.selectedSeepageScenarioId);
        definition != nullptr && !definition->name.empty()) {
        return definition->name;
    }
    return runtimeState.water.selectedSeepageScenarioId;
}

std::filesystem::path ResolveDataDirectory(const std::filesystem::path& requested) {
    auto localOrRequested = requested;
    if (localOrRequested.empty()) {
        if (const char* envValue = std::getenv("INVISIBLE_PLACES_DATA_DIR");
            envValue != nullptr) {
            localOrRequested = std::filesystem::path{envValue};
        }
    }
    return invisible_places::app::workspace::ResolveSharedDataDirectory(
        Application::DefaultDataDirectory(),
        localOrRequested);
}

bool SupplementalLocalPointCloudAllowed(
    const invisible_places::io::PointCloudAsset& asset) {
    // OneDrive owns the production Scene3 set. Avoid rediscovering its local
    // compatibility symlinks and deliberately leave the retired 2 mm/3 mm
    // role variants out of the active catalog. Other local fixtures remain.
    if (asset.sceneGroupName == "Scene3") {
        return false;
    }
    const auto filename = asset.filePath.filename().string();
    return filename != "Site3-MESH.ply" &&
           filename != "Site3-MESHSampled-5mm.ply";
}

invisible_places::io::AssetCatalog DiscoverApplicationAssets(
    const std::filesystem::path& primaryDataRoot) {
    auto catalog = invisible_places::io::DiscoverAssets(primaryDataRoot);
    const auto localDataRoot = Application::DefaultDataDirectory();
    const auto displayDensityCacheRoot =
        invisible_places::app::workspace::LocalSavedDirectory(localDataRoot) /
        ".invisible_places" / "cache" / "display_density" / "Scene3";
    invisible_places::io::SceneDisplayDensityCacheActivation
        displayDensityCache;
    if (const char* disabled =
            std::getenv("INVISIBLE_PLACES_DISABLE_DISPLAY_DENSITY_CACHE");
        disabled != nullptr && std::string_view{disabled} == "1") {
        invisible_places::io::ClearSceneDisplayDensityCacheActivation();
        displayDensityCache.state =
            invisible_places::io::SceneDisplayDensityCacheState::Unavailable;
        displayDensityCache.message =
            "Disabled by INVISIBLE_PLACES_DISABLE_DISPLAY_DENSITY_CACHE=1; using shared 5 mm files.";
    } else {
        displayDensityCache =
            invisible_places::io::ActivateScene3DisplayDensityCache(
                displayDensityCacheRoot,
                &catalog);
    }
    if (displayDensityCache.state ==
        invisible_places::io::SceneDisplayDensityCacheState::Rejected) {
        std::cerr << "Scene3 display-density cache rejected: "
                  << displayDensityCache.message << '\n';
    } else {
        std::cout << "Scene3 display-density cache: "
                  << displayDensityCache.message << '\n';
    }
    if (displayDensityCache.Activated()) {
        for (const auto& role : displayDensityCache.roles) {
            std::cout << "  " << role.role << ": "
                      << role.logicalDisplayPath.filename().string()
                      << " -> " << role.cachedDisplayPath.generic_string()
                      << " (" << role.outputPointCount << " points, sha256 "
                      << role.outputSha256.substr(0U, 12U) << "...)\n";
        }
    }
    if (primaryDataRoot.lexically_normal() == localDataRoot.lexically_normal()) {
        return catalog;
    }

    auto supplemental = invisible_places::io::DiscoverAssets(localDataRoot);
    std::erase_if(
        supplemental.pointClouds,
        [](const auto& asset) {
            return !SupplementalLocalPointCloudAllowed(asset);
        });
    catalog.pointClouds.insert(
        catalog.pointClouds.end(),
        std::make_move_iterator(supplemental.pointClouds.begin()),
        std::make_move_iterator(supplemental.pointClouds.end()));
    catalog.gaussianSplats.insert(
        catalog.gaussianSplats.end(),
        std::make_move_iterator(supplemental.gaussianSplats.begin()),
        std::make_move_iterator(supplemental.gaussianSplats.end()));
    catalog.issues.insert(
        catalog.issues.end(),
        std::make_move_iterator(supplemental.issues.begin()),
        std::make_move_iterator(supplemental.issues.end()));
    return catalog;
}

void AcquireExportPowerAssertion(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr || runtimeState->exportPowerAssertion.Active()) {
        return;
    }
    runtimeState->exportPowerAssertion =
        invisible_places::platform::PreventUserIdleSystemSleep("Invisible Places export");
}

std::string FormatPointCount(std::uint64_t value) {
    std::string digits = std::to_string(value);
    for (std::ptrdiff_t index = static_cast<std::ptrdiff_t>(digits.size()) - 3; index > 0; index -= 3) {
        digits.insert(static_cast<std::size_t>(index), ",");
    }
    return digits;
}

std::string FormatFixed(double value, int precision) {
    std::ostringstream output;
    output << std::fixed << std::setprecision(precision) << value;
    return output.str();
}

double PercentileValue(std::vector<double> values, double percentile) {
    if (values.empty()) {
        return 0.0;
    }
    std::sort(values.begin(), values.end());
    const double clamped = std::clamp(percentile, 0.0, 1.0);
    const double scaled = clamped * static_cast<double>(values.size() - 1U);
    const auto low = static_cast<std::size_t>(std::floor(scaled));
    const auto high = static_cast<std::size_t>(std::ceil(scaled));
    if (low == high) {
        return values[low];
    }
    return std::lerp(values[low], values[high], scaled - static_cast<double>(low));
}

std::string NormalizePathKey(const std::filesystem::path& path) {
    return path.lexically_normal().generic_string();
}

bool PathsReferToSameLocation(
    const std::filesystem::path& left,
    const std::filesystem::path& right) {
    if (left.empty() || right.empty()) {
        return false;
    }
    if (NormalizePathKey(left) == NormalizePathKey(right)) {
        return true;
    }
    std::error_code leftError;
    std::error_code rightError;
    const auto absoluteLeft = std::filesystem::absolute(left, leftError);
    const auto absoluteRight = std::filesystem::absolute(right, rightError);
    return !leftError && !rightError &&
           NormalizePathKey(absoluteLeft) == NormalizePathKey(absoluteRight);
}

std::string LowercaseAsciiCopy(std::string value) {
    std::transform(value.begin(), value.end(), value.begin(), [](unsigned char character) {
        return static_cast<char>(std::tolower(character));
    });
    return value;
}

std::filesystem::path DefaultProjectFilePath(const std::filesystem::path& dataRoot) {
    const auto savedDirectory =
        invisible_places::app::workspace::ResolveAuthoredWorkspaceDirectory(
            dataRoot);
    std::error_code error;
    const auto exhibitionFinalProjectPath = savedDirectory / "ExhibitionFinal_project.json";
    if (std::filesystem::is_regular_file(exhibitionFinalProjectPath, error)) {
        return exhibitionFinalProjectPath;
    }
    const auto exhibitionProjectPath = savedDirectory / "exhibitionScene_project.json";
    if (std::filesystem::is_regular_file(exhibitionProjectPath, error)) {
        return exhibitionProjectPath;
    }
    return savedDirectory / "invisible_places_project.json";
}

std::filesystem::path DefaultPointStylePresetPath(const std::filesystem::path& dataRoot) {
    return invisible_places::app::workspace::ResolveAuthoredWorkspaceDirectory(
               dataRoot) /
           "pointcloud_style_preset.json";
}

