void HashCombine(std::uint64_t* seed, std::uint64_t value) {
    if (seed == nullptr) {
        return;
    }
    *seed ^= value + 0x9e3779b97f4a7c15ULL + (*seed << 6U) + (*seed >> 2U);
}

void HashString(std::uint64_t* seed, std::string_view value) {
    std::uint64_t hash = 1469598103934665603ULL;
    for (const char character : value) {
        hash ^= static_cast<unsigned char>(character);
        hash *= 1099511628211ULL;
    }
    HashCombine(seed, hash);
}

void HashBool(std::uint64_t* seed, bool value) {
    HashCombine(seed, value ? 1ULL : 0ULL);
}

void HashFloat(std::uint64_t* seed, float value) {
    HashCombine(seed, static_cast<std::uint64_t>(std::bit_cast<std::uint32_t>(value)));
}

void HashVec3(std::uint64_t* seed, const glm::vec3& value) {
    HashFloat(seed, value.x);
    HashFloat(seed, value.y);
    HashFloat(seed, value.z);
}

void HashVec4(std::uint64_t* seed, const glm::vec4& value) {
    HashFloat(seed, value.x);
    HashFloat(seed, value.y);
    HashFloat(seed, value.z);
    HashFloat(seed, value.w);
}

void HashMat4(std::uint64_t* seed, const glm::mat4& value) {
    for (int column = 0; column < 4; ++column) {
        for (int row = 0; row < 4; ++row) {
            HashFloat(seed, value[column][row]);
        }
    }
}

void HashArray3(std::uint64_t* seed, const std::array<float, 3>& value) {
    HashFloat(seed, value[0]);
    HashFloat(seed, value[1]);
    HashFloat(seed, value[2]);
}

void HashArray4(std::uint64_t* seed, const std::array<float, 4>& value) {
    HashFloat(seed, value[0]);
    HashFloat(seed, value[1]);
    HashFloat(seed, value[2]);
    HashFloat(seed, value[3]);
}

std::uint64_t AnimationPathMotionFingerprint(const AnimationPath& path) {
    std::uint64_t seed = 1469598103934665603ULL;
    HashCombine(&seed, path.durationFrames);
    HashCombine(&seed, path.authoredTrackDurationFrames);
    HashCombine(&seed, path.exportSettings.width);
    HashCombine(&seed, path.exportSettings.height);
    HashBool(&seed, path.depthOfFieldEnabled);
    HashFloat(&seed, path.apertureFStops);
    HashFloat(&seed, path.depthOfFieldMaxBlurPixels);
    HashCombine(&seed, path.keys.size());
    for (const auto& key : path.keys) {
        HashString(&seed, key.id);
        HashString(&seed, key.linkedCameraId);
        HashArray3(&seed, key.cameraPosition);
        HashArray3(&seed, key.focusPoint);
        HashBool(&seed, key.hasOrientation);
        HashArray4(&seed, key.orientation);
        HashBool(&seed, key.hasFocusDistance);
        HashFloat(&seed, key.focusDistance);
        HashBool(&seed, key.hasApertureFStops);
        HashFloat(&seed, key.apertureFStops);
        HashFloat(&seed, key.fovDegrees);
        HashFloat(&seed, key.nearPlane);
        HashFloat(&seed, key.farPlane);
        HashCombine(&seed, key.durationFrames);
        HashFloat(&seed, key.splineParameterWeight);
        HashBool(&seed, key.hasSplineEndpointTangent);
        HashArray3(&seed, key.splineCameraEndpointTangent);
        HashArray3(&seed, key.splineFocusEndpointTangent);
        HashArray4(&seed, key.splineOrientationEndpointTangent);
        for (const float component : key.splineLensEndpointTangent) {
            HashFloat(&seed, component);
        }
    }
    HashCombine(&seed, path.localizedKeyCorrections.size());
    for (const auto& correction : path.localizedKeyCorrections) {
        HashString(&seed, correction.keyId);
        HashArray3(&seed, correction.splineCameraPosition);
        HashArray3(&seed, correction.splineFocusPoint);
        HashBool(&seed, correction.hasCameraCorrectionTangent);
        HashArray3(&seed, correction.cameraCorrectionTangent);
        HashBool(&seed, correction.hasFocusCorrectionTangent);
        HashArray3(&seed, correction.focusCorrectionTangent);
    }
    return seed;
}

const invisible_places::camera::PreparedAnimationPathEvaluationContext& CachedPreparedAnimationPath(
    AnimationPanelState* panel,
    const AnimationPath& path) {
    static thread_local invisible_places::camera::PreparedAnimationPathEvaluationContext fallbackContext;
    const auto fingerprint = AnimationPathMotionFingerprint(path);
    if (panel == nullptr) {
        fallbackContext = invisible_places::camera::PrepareAnimationPathEvaluation(path);
        return fallbackContext;
    }

    if (!panel->preparedPathCache.valid ||
        panel->preparedPathCache.pathFingerprint != fingerprint) {
        panel->preparedPathCache.context =
            invisible_places::camera::PrepareAnimationPathEvaluation(path);
        panel->preparedPathCache.pathFingerprint = fingerprint;
        panel->preparedPathCache.valid = true;
    }
    return panel->preparedPathCache.context;
}

invisible_places::camera::AnimationPathMotionStats CachedAnimationPathMotionStats(
    AnimationPanelState* panel,
    const AnimationPath& path,
    float scrubAmount) {
    const float normalizedScrubAmount = std::clamp(scrubAmount, 0.0F, 1.0F);
    const auto fingerprint = AnimationPathMotionFingerprint(path);
    if (panel != nullptr &&
        panel->motionStatsCache.valid &&
        panel->motionStatsCache.pathFingerprint == fingerprint &&
        std::abs(panel->motionStatsCache.scrubAmount - normalizedScrubAmount) <= 1.0e-6F) {
        return panel->motionStatsCache.stats;
    }

    const auto& preparedPath = CachedPreparedAnimationPath(panel, path);
    auto stats = invisible_places::camera::MeasurePreparedAnimationPathMotion(
        preparedPath,
        normalizedScrubAmount);
    if (panel != nullptr) {
        panel->motionStatsCache = {
            .valid = true,
            .pathFingerprint = fingerprint,
            .scrubAmount = normalizedScrubAmount,
            .stats = stats,
        };
    }
    return stats;
}

const std::vector<invisible_places::camera::AnimationPerceivedFlowSample>&
CachedAnimationPathPerceivedFlow(
    AnimationPanelState* panel,
    const AnimationPath& path) {
    const auto fingerprint = AnimationPathMotionFingerprint(path);
    if (panel != nullptr &&
        panel->perceivedFlowCache.valid &&
        panel->perceivedFlowCache.pathFingerprint == fingerprint) {
        return panel->perceivedFlowCache.samples;
    }
    const auto& preparedPath = CachedPreparedAnimationPath(panel, path);
    auto samples =
        invisible_places::camera::MeasurePreparedAnimationPathPerceivedFlow(
            preparedPath);
    if (panel != nullptr) {
        panel->perceivedFlowCache = {
            .valid = true,
            .pathFingerprint = fingerprint,
            .samples = std::move(samples),
        };
        return panel->perceivedFlowCache.samples;
    }
    thread_local std::vector<
        invisible_places::camera::AnimationPerceivedFlowSample>
        fallbackSamples;
    fallbackSamples = std::move(samples);
    return fallbackSamples;
}

void HashBinding(std::uint64_t* seed, const RenderParameterBinding& binding) {
    HashBool(seed, binding.active);
    HashCombine(seed, static_cast<std::uint64_t>(binding.mode));
    for (const float value : binding.constantValue) {
        HashFloat(seed, value);
    }
    HashCombine(seed, static_cast<std::uint64_t>(binding.fieldMap.fieldSlot));
    HashString(seed, binding.fieldMap.fieldName);
    HashFloat(seed, binding.fieldMap.inputMin);
    HashFloat(seed, binding.fieldMap.inputMax);
    HashFloat(seed, binding.fieldMap.outputMin);
    HashFloat(seed, binding.fieldMap.outputMax);
    HashFloat(seed, binding.fieldMap.gamma);
    HashCombine(seed, binding.fieldMap.flags);
}

void HashHeightFoamShorelineSettings(
    std::uint64_t* seed,
    const invisible_places::renderer::pointcloud::PointCloudHeightFoamShorelineSettings& settings) {
    HashFloat(seed, settings.runupZ);
    HashFloat(seed, settings.breakZ);
    HashFloat(seed, settings.offshoreReachMeters);
    HashFloat(seed, settings.edgeFadeMeters);
    HashFloat(seed, settings.directionX);
    HashFloat(seed, settings.directionY);
    HashFloat(seed, settings.patternScale);
    HashFloat(seed, settings.wavelengthMeters);
    HashFloat(seed, settings.speed);
    HashFloat(seed, settings.warp);
    HashFloat(seed, settings.turbulence);
    HashFloat(seed, settings.density);
    HashFloat(seed, settings.phase);
    HashFloat(seed, settings.intensity);
    HashFloat(seed, settings.offshoreFoamStrength);
    HashFloat(seed, settings.incomingStrength);
    HashFloat(seed, settings.returnStrength);
    HashFloat(seed, settings.emissionAdd);
    HashFloat(seed, settings.opacityAdd);
    HashFloat(seed, settings.opacityMultiply);
    HashFloat(seed, settings.pointSizeAdd);
    HashFloat(seed, settings.pointSizeMultiply);
    HashFloat(seed, settings.colourMix);
    for (const float value : settings.colour) {
        HashFloat(seed, value);
    }
    HashCombine(seed, settings.seed);
}

void HashPointStyle(std::uint64_t* seed, const PointCloudStyleState& style) {
    HashCombine(seed, static_cast<std::uint64_t>(style.geometryMode));
    HashCombine(seed, static_cast<std::uint64_t>(style.screenSpriteSizeMode));
    HashCombine(seed, static_cast<std::uint64_t>(style.falloffProfile));
    HashCombine(seed, static_cast<std::uint64_t>(style.stylisationMode));
    HashCombine(seed, static_cast<std::uint64_t>(style.nprPreset));
    HashCombine(seed, static_cast<std::uint64_t>(style.colorMode));
    HashCombine(seed, static_cast<std::uint64_t>(style.colormap));
    for (const float value : style.solidColor) {
        HashFloat(seed, value);
    }
    for (const float value : style.gradientStartColor) {
        HashFloat(seed, value);
    }
    for (const float value : style.gradientEndColor) {
        HashFloat(seed, value);
    }
    for (const float value : style.colorizeColor) {
        HashFloat(seed, value);
    }
    HashFloat(seed, style.colorizeAmount);
    HashFloat(seed, style.stylisationStrength);
    HashFloat(seed, style.stylisationColorLevels);
    HashFloat(seed, style.stylisationInkStrength);
    HashFloat(seed, style.stylisationPaperGrain);
    HashFloat(seed, style.stylisationPigmentBleed);
    HashFloat(seed, style.brushAspect);
    HashFloat(seed, style.strokeJitter);
    HashFloat(seed, style.hatchStrength);
    HashFloat(seed, style.strokeOpacityVariance);
    HashFloat(seed, style.pigmentVariation);
    HashFloat(seed, style.pigmentAnimationSpeed);
    HashFloat(seed, style.granulationAngleStrength);
    HashFloat(seed, style.roughnessMotionStrength);
    HashFloat(seed, style.roughnessMotionScale);
    HashFloat(seed, style.roughnessMotionSpeed);
    HashFloat(seed, style.roughnessMotionThreshold);
    HashFloat(seed, style.roughnessMotionGroundId);
    HashBool(seed, style.roughnessMotionFullLayer);
    HashBool(seed, style.shorelineWaveEnabled);
    HashCombine(seed, static_cast<std::uint64_t>(style.shorelineWaveAlgorithm));
    HashHeightFoamShorelineSettings(seed, style.shorelineHeightFoam);
    HashFloat(seed, style.shorelineBoundaryZ);
    HashFloat(seed, style.shorelineHeightReachMeters);
    HashFloat(seed, style.shorelineEdgeFadeMeters);
    HashFloat(seed, style.shorelineDirectionX);
    HashFloat(seed, style.shorelineDirectionY);
    HashFloat(seed, style.shorelinePatternScale);
    HashFloat(seed, style.shorelineWavelengthMeters);
    HashFloat(seed, style.shorelineSpeed);
    HashFloat(seed, style.shorelineWarp);
    HashFloat(seed, style.shorelineTurbulence);
    HashFloat(seed, style.shorelineDensity);
    HashFloat(seed, style.shorelineBackgroundWash);
    HashFloat(seed, style.shorelinePhase);
    HashFloat(seed, style.shorelineIntensity);
    HashFloat(seed, style.shorelineEmissionAdd);
    HashFloat(seed, style.shorelineOpacityAdd);
    HashFloat(seed, style.shorelineOpacityMultiply);
    HashFloat(seed, style.shorelinePointSizeAdd);
    HashFloat(seed, style.shorelinePointSizeMultiply);
    HashFloat(seed, style.shorelineColourMix);
    for (const float value : style.shorelineColour) {
        HashFloat(seed, value);
    }
    HashCombine(seed, style.shorelineSeed);
    HashFloat(seed, style.exposure);
    HashFloat(seed, style.innerRadius);
    HashFloat(seed, style.gaussianSharpness);
    HashFloat(seed, style.featherPower);
    HashFloat(seed, style.waterStreakAspect);
    HashFloat(seed, style.waterFlowActivity);
    HashFloat(seed, style.waterFlowSpeedScale);
    HashBool(seed, style.waterTrailStyleGeometry);
    HashBool(seed, style.solidCenters);
    HashBool(seed, style.flowAnimation);
    HashBool(seed, style.waterPathView);
    HashBool(seed, style.waterTrailOverlay);
    HashBinding(seed, style.pointSize);
    HashBinding(seed, style.surfelDiameter);
    HashBinding(seed, style.opacity);
    HashBinding(seed, style.emissiveStrength);
    HashBinding(seed, style.depthFade);
    HashBinding(seed, style.colormapPosition);
}

void HashScalarFields(
    std::uint64_t* seed,
    const std::vector<invisible_places::io::ScalarFieldStats>& scalarFields) {
    HashCombine(seed, scalarFields.size());
    for (const auto& field : scalarFields) {
        HashString(seed, field.name);
        HashFloat(seed, field.minimum);
        HashFloat(seed, field.maximum);
        HashCombine(seed, field.count);
        HashBool(seed, field.valid);
    }
}

void HashTimingColouriseStack(
    std::uint64_t* seed,
    const invisible_places::renderer::pointcloud::
        ResolvedTimingColouriseStack& stack) {
    const std::size_t effectCount = std::min<std::size_t>(
        stack.effectCount,
        stack.effects.size());
    HashCombine(seed, effectCount);
    for (std::size_t effectIndex = 0U;
         effectIndex < effectCount;
         ++effectIndex) {
        const auto& effect = stack.effects[effectIndex];
        HashBool(seed, effect.enabled);
        HashCombine(
            seed,
            static_cast<std::uint64_t>(effect.output));
        HashCombine(
            seed,
            static_cast<std::uint64_t>(effect.source));
        HashCombine(
            seed,
            static_cast<std::uint64_t>(
                static_cast<std::int64_t>(
                    effect.scalarFieldSlot)));
        HashFloat(seed, effect.lowerBound);
        HashFloat(seed, effect.upperBound);
        HashFloat(seed, effect.edgeFadeFraction);
        HashFloat(seed, effect.emissiveLevel);
        for (const auto& sample : effect.rgbaLut) {
            for (const float value : sample) {
                HashFloat(seed, value);
            }
        }
    }
}

void HashGsplatStyle(std::uint64_t* seed, const GaussianSplatStyleState& style) {
    HashBool(seed, style.transformEnabled);
    HashCombine(seed, static_cast<std::uint64_t>(style.colorMode));
    HashCombine(seed, static_cast<std::uint64_t>(style.debugMode));
    HashCombine(seed, static_cast<std::uint64_t>(style.qualityMode));
    HashFloat(seed, style.opacityMultiplier);
    HashFloat(seed, style.scaleMultiplier);
    HashFloat(seed, style.exposure);
    HashFloat(seed, style.saturation);
    for (const float value : style.layerTint) {
        HashFloat(seed, value);
    }
}

void HashRainRuntime(
    std::uint64_t* seed,
    const RainRuntimeSettings& settings,
    const WaterRainVisualSettings& visual) {
    HashBool(seed, settings.enabled);
    HashBool(seed, settings.impactEffectsEnabled);
    HashBool(seed, settings.sandEffectsEnabled);
    HashBool(seed, settings.rockEffectsEnabled);
    HashBool(seed, settings.vegetationEffectsEnabled);
    HashCombine(seed, static_cast<std::uint64_t>(settings.intensityPreset));
    HashString(seed, settings.visualProfileName);
    HashCombine(seed, settings.activeParticleCount);
    HashCombine(seed, settings.seed);
    const std::array runtimeValues{
        settings.rainLevel,
        settings.density,
        settings.fallSpeedMetersPerSecond,
        settings.dropletSizeScale,
        settings.opacityScale,
        settings.emissionScale,
        settings.spawnHeightMeters,
        settings.spawnRadiusMeters,
        settings.cameraDeathDistanceMeters,
        settings.windDirectionX,
        settings.windDirectionY,
        settings.windSpeedMetersPerSecond,
        settings.turbulence,
        settings.gustStrength,
        settings.gustScaleMeters,
        settings.gustSpeedMetersPerSecond,
        settings.weatherFrontStrength,
        settings.weatherFrontScaleMeters,
        settings.weatherFrontSpeedMetersPerSecond,
        settings.sandEffectScale,
        settings.rockEffectScale,
        settings.vegetationEffectScale,
        settings.ringImpact.thicknessScale,
        settings.nearSurface.approachDistanceMeters,
        settings.nearSurface.minimumSpeedFactor,
        settings.nearSurface.squish,
        settings.nearSurface.normalAlignment,
        settings.rockImpact.edgeBreakup,
        settings.rockImpact.spreadSpeed,
        settings.rockImpact.centreFalloff,
        settings.rockImpact.heightBias,
        settings.rockImpact.persistence,
        settings.rockImpact.downhillStretch,
        settings.vegetationImpact.twinkle,
        settings.vegetationImpact.propagationMetersPerSecond,
        settings.vegetationImpact.hopSpacingMeters,
        settings.vegetationImpact.streamWidthMeters,
        settings.vegetationImpact.streamSpread,
        settings.sandImpactBand.minZ,
        settings.sandImpactBand.maxZ,
        settings.sandImpactBand.fadeMeters,
        settings.rockImpactBand.minZ,
        settings.rockImpactBand.maxZ,
        settings.rockImpactBand.fadeMeters,
        settings.vegetationImpactBand.minZ,
        settings.vegetationImpactBand.maxZ,
        settings.vegetationImpactBand.fadeMeters,
    };
    for (const float value : runtimeValues) {
        HashFloat(seed, value);
    }
    for (const float value : visual.colour) {
        HashFloat(seed, value);
    }
    const std::array visualValues{
        visual.widthMeters,
        visual.streakLengthMeters,
        visual.softness,
        visual.opacity,
        visual.emission,
        visual.minimumScreenPixels,
        visual.maximumScreenPixels,
    };
    for (const float value : visualValues) {
        HashFloat(seed, value);
    }
}

