bool IsProjectPointVisualSession(const PreviewLayerSession& session) {
    return session.kind == LayerKind::PointCloud && !IsGeneratedWaterOverlaySession(session);
}

std::string ProjectVisualSceneKey(const PreviewLayerSession& session) {
    if (!session.sceneGroupName.empty()) {
        return session.sceneGroupName;
    }
    if (!session.sourcePath.empty()) {
        return session.sourcePath.stem().string();
    }
    return session.displayName;
}

std::string SceneTemporaryPointVisualName(std::string_view baseName, const PreviewLayerSession& session) {
    const auto sceneKey = ProjectVisualSceneKey(session);
    const auto base = BasePointVisualName(baseName);
    if (sceneKey.empty()) {
        return base;
    }
    return base + "_" + sceneKey;
}

std::string BaseNameFromSceneTemporaryPointVisual(
    std::string_view visualName,
    const PreviewLayerSession& session) {
    auto normalized = NormalizePointVisualName(visualName);
    const auto sceneKey = ProjectVisualSceneKey(session);
    const std::string suffix = sceneKey.empty() ? std::string{} : "_" + sceneKey;
    if (!suffix.empty() &&
        normalized.size() > suffix.size() &&
        normalized.substr(normalized.size() - suffix.size()) == suffix) {
        normalized.resize(normalized.size() - suffix.size());
    }
    return BasePointVisualName(normalized);
}

std::string BaseNameFromProjectPointVisualName(
    const ProjectPointVisualLibraryState& library,
    std::string_view visualName) {
    auto normalized = NormalizePointVisualName(visualName);
    for (const auto& state : library.sceneVisualStates) {
        if (state.sceneGroupName.empty()) {
            continue;
        }
        const std::string suffix = "_" + state.sceneGroupName;
        if (normalized.size() > suffix.size() && EndsWith(normalized, suffix)) {
            normalized.resize(normalized.size() - suffix.size());
            break;
        }
    }
    return BasePointVisualName(normalized);
}

std::optional<std::size_t> FindProjectPointVisualIndex(
    const ProjectPointVisualLibraryState& library,
    std::string_view name) {
    return invisible_places::app::point_visual::FindIndex(library.pointVisuals, name);
}

std::optional<std::size_t> FindScenePointVisualStateIndex(
    const ProjectPointVisualLibraryState& library,
    std::string_view sceneGroupName) {
    const std::string sceneKey{sceneGroupName};
    for (std::size_t index = 0; index < library.sceneVisualStates.size(); ++index) {
        if (library.sceneVisualStates[index].sceneGroupName == sceneKey) {
            return index;
        }
    }
    return std::nullopt;
}

std::optional<std::size_t> FindScenePointVisualStateIndex(
    const ProjectPointVisualLibraryState& library,
    std::string_view sceneGroupName,
    std::string_view visualName) {
    const std::string sceneKey{sceneGroupName};
    const auto normalized = NormalizePointVisualName(visualName);
    for (std::size_t index = 0; index < library.sceneVisualStates.size(); ++index) {
        const auto& state = library.sceneVisualStates[index];
        if (state.sceneGroupName == sceneKey &&
            NormalizePointVisualName(state.visual.name) == normalized) {
            return index;
        }
    }
    return std::nullopt;
}

std::optional<std::size_t> FindScenePointVisualStateByNameIndex(
    const ProjectPointVisualLibraryState& library,
    std::string_view visualName) {
    const auto normalized = NormalizePointVisualName(visualName);
    for (std::size_t index = 0; index < library.sceneVisualStates.size(); ++index) {
        if (NormalizePointVisualName(library.sceneVisualStates[index].visual.name) == normalized) {
            return index;
        }
    }
    return std::nullopt;
}

std::optional<std::size_t> FindScenePointVisualStateForBaseIndex(
    const ProjectPointVisualLibraryState& library,
    std::string_view sceneGroupName,
    std::string_view baseName) {
    const std::string sceneKey{sceneGroupName};
    const auto normalizedBase = BasePointVisualName(baseName);
    for (std::size_t index = 0; index < library.sceneVisualStates.size(); ++index) {
        const auto& state = library.sceneVisualStates[index];
        if (state.sceneGroupName != sceneKey) {
            continue;
        }
        if (BaseNameFromProjectPointVisualName(library, state.visual.name) == normalizedBase) {
            return index;
        }
    }
    return std::nullopt;
}

void EnsureProjectPointVisuals(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }

    auto& library = runtimeState->pointVisualLibrary;
    if (library.pointVisuals.empty()) {
        PointCloudStyleState fallbackStyle{};
        if (const auto sessionIt = std::find_if(
                runtimeState->sessions.begin(),
                runtimeState->sessions.end(),
                [](const PreviewLayerSession& session) {
                    return IsProjectPointVisualSession(session);
                });
            sessionIt != runtimeState->sessions.end()) {
            fallbackStyle = sessionIt->pointStyle;
        }
        library.pointVisuals.push_back({.name = std::string{kDefaultPointVisualName}, .style = fallbackStyle});
    }

    for (auto& visual : library.pointVisuals) {
        visual.name = NormalizePointVisualName(visual.name);
    }
    for (auto& state : library.sceneVisualStates) {
        state.sceneGroupName = TrimText(state.sceneGroupName);
        state.visual.name = NormalizePointVisualName(state.visual.name);
    }
    library.selectedPointVisualName = NormalizePointVisualName(library.selectedPointVisualName);
    if (!FindProjectPointVisualIndex(library, library.selectedPointVisualName).has_value()) {
        library.selectedPointVisualName = library.pointVisuals.front().name;
    }
    if (library.pointVisualNameBuffer.empty()) {
        library.pointVisualNameBuffer = BasePointVisualName(library.selectedPointVisualName);
    }
}

void UpsertProjectPointVisual(
    PreviewRuntimeState* runtimeState,
    std::string_view name,
    const PointCloudStyleState& style) {
    if (runtimeState == nullptr) {
        return;
    }
    invisible_places::app::point_visual::Upsert(
        &runtimeState->pointVisualLibrary.pointVisuals,
        BasePointVisualName(name),
        style);
}

void RemoveScenePointVisualStateForBase(
    PreviewRuntimeState* runtimeState,
    std::string_view sceneGroupName,
    std::string_view baseName) {
    if (runtimeState == nullptr) {
        return;
    }
    const std::string sceneKey{sceneGroupName};
    const auto normalizedBase = BasePointVisualName(baseName);
    auto& states = runtimeState->pointVisualLibrary.sceneVisualStates;
    states.erase(
        std::remove_if(
            states.begin(),
            states.end(),
            [&sceneKey, &normalizedBase](const ScenePointVisualState& state) {
                if (state.sceneGroupName != sceneKey) {
                    return false;
                }
                auto stateBase = NormalizePointVisualName(state.visual.name);
                const std::string suffix = "_" + state.sceneGroupName;
                if (stateBase.size() > suffix.size() && EndsWith(stateBase, suffix)) {
                    stateBase.resize(stateBase.size() - suffix.size());
                }
                return BasePointVisualName(stateBase) == normalizedBase;
            }),
        states.end());
}

void UpsertScenePointVisualState(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& session,
    std::string_view visualName,
    const PointCloudStyleState& style) {
    if (runtimeState == nullptr) {
        return;
    }
    const auto sceneKey = ProjectVisualSceneKey(session);
    if (sceneKey.empty()) {
        return;
    }

    ScenePointVisualState state;
    state.sceneGroupName = sceneKey;
    state.visual.name = NormalizePointVisualName(visualName);
    state.visual.style = style;
    if (const auto index = FindScenePointVisualStateIndex(runtimeState->pointVisualLibrary, sceneKey, state.visual.name);
        index.has_value()) {
        runtimeState->pointVisualLibrary.sceneVisualStates[index.value()] = std::move(state);
    } else {
        runtimeState->pointVisualLibrary.sceneVisualStates.push_back(std::move(state));
    }
}

std::optional<PointCloudStyleState> ProjectPointVisualStyleByName(
    const ProjectPointVisualLibraryState& library,
    std::string_view visualName) {
    const auto normalized = NormalizePointVisualName(visualName);
    if (const auto visualIndex = FindProjectPointVisualIndex(library, normalized); visualIndex.has_value()) {
        return library.pointVisuals[visualIndex.value()].style;
    }
    if (const auto stateIndex = FindScenePointVisualStateByNameIndex(library, normalized); stateIndex.has_value()) {
        return library.sceneVisualStates[stateIndex.value()].visual.style;
    }
    return std::nullopt;
}

std::string JoinShortList(const std::vector<std::string>& values) {
    std::ostringstream output;
    for (std::size_t index = 0; index < values.size(); ++index) {
        if (index > 0) {
            output << ", ";
        }
        output << values[index];
    }
    return output.str();
}

void AppendUniqueText(std::vector<std::string>* values, std::string value) {
    if (values == nullptr || value.empty()) {
        return;
    }
    if (std::find(values->begin(), values->end(), value) == values->end()) {
        values->push_back(std::move(value));
    }
}

void CollectMissingProjectVisualBindingFields(
    const RenderParameterBinding& binding,
    std::string_view label,
    const std::vector<invisible_places::io::ScalarFieldStats>& scalarFields,
    std::vector<std::string>* missingFields) {
    if (!binding.active || binding.mode != ParameterSourceMode::FieldMapped || missingFields == nullptr) {
        return;
    }

    auto resolved = binding;
    invisible_places::style::SyncBindingFieldReference(&resolved, scalarFields);
    if (resolved.fieldMap.fieldSlot < 0) {
        AppendUniqueText(
            missingFields,
            !binding.fieldMap.fieldName.empty()
                ? std::string{label} + " -> " + binding.fieldMap.fieldName
                : std::string{label} + " -> scalar field slot " +
                      std::to_string(binding.fieldMap.fieldSlot));
    }
}

std::vector<std::string> MissingProjectVisualBindingFields(
    const PointCloudStyleState& style,
    const PreviewLayerSession& session) {
    std::vector<std::string> missingFields;
    CollectMissingProjectVisualBindingFields(style.pointSize, "Point Size", session.scalarFields, &missingFields);
    CollectMissingProjectVisualBindingFields(
        style.surfelDiameter,
        "Surfel Diameter",
        session.scalarFields,
        &missingFields);
    CollectMissingProjectVisualBindingFields(style.opacity, "Opacity", session.scalarFields, &missingFields);
    CollectMissingProjectVisualBindingFields(
        style.emissiveStrength,
        "Emission",
        session.scalarFields,
        &missingFields);
    CollectMissingProjectVisualBindingFields(style.depthFade, "Depth Fade", session.scalarFields, &missingFields);
    CollectMissingProjectVisualBindingFields(
        style.colormapPosition,
        "Colormap",
        session.scalarFields,
        &missingFields);
    return missingFields;
}

std::string ProjectVisualWarningLayerLabel(const PreviewLayerSession& session) {
    if (!session.sceneRole.empty()) {
        return session.sceneRole;
    }
    if (!session.displayName.empty()) {
        return session.displayName;
    }
    if (!session.sourcePath.empty()) {
        return session.sourcePath.filename().string();
    }
    return "layer";
}

std::string BuildProjectVisualFieldBindingWarning(
    const PreviewRuntimeState& runtimeState,
    std::string_view sceneKey,
    std::string_view visualName,
    const std::optional<PointCloudStyleState>& style) {
    if (!style.has_value()) {
        return {};
    }

    std::vector<std::string> layerWarnings;
    for (const auto& session : runtimeState.sessions) {
        if (!IsProjectPointVisualSession(session) ||
            ProjectVisualSceneKey(session) != sceneKey ||
            !session.loaded) {
            continue;
        }

        const auto missingFields = MissingProjectVisualBindingFields(style.value(), session);
        if (missingFields.empty()) {
            continue;
        }
        layerWarnings.push_back(
            ProjectVisualWarningLayerLabel(session) + " missing " + JoinShortList(missingFields));
    }

    if (layerWarnings.empty()) {
        return {};
    }

    return "Visual '" + NormalizePointVisualName(visualName) +
           "' has field-mapped controls that are unavailable on " +
           JoinShortList(layerWarnings) +
           "; their authored constant fallbacks are being used.";
}

bool IsProjectVisualFieldBindingWarning(std::string_view message) {
    return message.find("field-mapped controls") != std::string_view::npos &&
           message.find("unavailable") != std::string_view::npos;
}

void UpdateProjectVisualFieldBindingWarning(
    PreviewRuntimeState* runtimeState,
    const std::string& warning) {
    if (runtimeState == nullptr) {
        return;
    }
    if (!warning.empty()) {
        runtimeState->errorMessage = warning;
        runtimeState->statusMessage.clear();
    } else if (IsProjectVisualFieldBindingWarning(runtimeState->errorMessage)) {
        runtimeState->errorMessage.clear();
    }
}

bool ResolveProjectVisualBindingByFieldName(
    RenderParameterBinding* binding,
    const std::vector<invisible_places::io::ScalarFieldStats>& scalarFields) {
    if (binding == nullptr || binding->mode != ParameterSourceMode::FieldMapped) {
        return false;
    }

    invisible_places::style::SyncBindingFieldReference(binding, scalarFields);
    return binding->fieldMap.fieldSlot < 0;
}

bool ResolveProjectVisualStyleBindingsByFieldName(
    PointCloudStyleState* style,
    const PreviewLayerSession& session) {
    if (style == nullptr) {
        return false;
    }

    bool convertedMissingField = false;
    convertedMissingField |= ResolveProjectVisualBindingByFieldName(&style->pointSize, session.scalarFields);
    convertedMissingField |= ResolveProjectVisualBindingByFieldName(&style->surfelDiameter, session.scalarFields);
    convertedMissingField |= ResolveProjectVisualBindingByFieldName(&style->opacity, session.scalarFields);
    convertedMissingField |= ResolveProjectVisualBindingByFieldName(&style->emissiveStrength, session.scalarFields);
    convertedMissingField |= ResolveProjectVisualBindingByFieldName(&style->depthFade, session.scalarFields);
    convertedMissingField |= ResolveProjectVisualBindingByFieldName(&style->colormapPosition, session.scalarFields);
    return convertedMissingField;
}

void CopyProjectVisualsToSessionList(
    PreviewRuntimeState* runtimeState,
    PreviewLayerSession* session,
    std::string_view selectedName,
    const PointCloudStyleState& selectedStyle) {
    if (runtimeState == nullptr || session == nullptr) {
        return;
    }

    session->pointVisuals = runtimeState->pointVisualLibrary.pointVisuals;
    for (const auto& state : runtimeState->pointVisualLibrary.sceneVisualStates) {
        invisible_places::app::point_visual::Upsert(
            &session->pointVisuals,
            state.visual.name,
            state.visual.style);
    }
    invisible_places::app::point_visual::Upsert(&session->pointVisuals, selectedName, selectedStyle);
}

void ApplyProjectPointVisualToSession(PreviewRuntimeState* runtimeState, PreviewLayerSession* session) {
    if (runtimeState == nullptr || session == nullptr || !IsProjectPointVisualSession(*session)) {
        return;
    }

    EnsureProjectPointVisuals(runtimeState);
    auto& library = runtimeState->pointVisualLibrary;
    const auto sceneKey = ProjectVisualSceneKey(*session);
    std::string selectedName = NormalizePointVisualName(session->selectedPointVisualName);
    PointCloudStyleState style = library.pointVisuals.front().style;
    bool hasResolvedStyle = false;

    const bool useSessionSelection =
        !selectedName.empty() &&
        (selectedName != std::string{kDefaultPointVisualName} ||
         library.selectedPointVisualName == std::string{kDefaultPointVisualName} ||
         FindScenePointVisualStateByNameIndex(library, selectedName).has_value());
    if (useSessionSelection) {
        if (const auto visualIndex = FindProjectPointVisualIndex(library, selectedName); visualIndex.has_value()) {
            style = library.pointVisuals[visualIndex.value()].style;
            hasResolvedStyle = true;
        } else if (const auto stateIndex = FindScenePointVisualStateByNameIndex(library, selectedName);
                   stateIndex.has_value()) {
            style = library.sceneVisualStates[stateIndex.value()].visual.style;
            selectedName = library.sceneVisualStates[stateIndex.value()].visual.name;
            hasResolvedStyle = true;
        }
    }

    if (!hasResolvedStyle) {
        selectedName = library.selectedPointVisualName;
    }
    if (!hasResolvedStyle &&
        (FindProjectPointVisualIndex(library, selectedName).has_value() ||
         FindScenePointVisualStateByNameIndex(library, selectedName).has_value())) {
        if (const auto visualIndex = FindProjectPointVisualIndex(library, selectedName); visualIndex.has_value()) {
            style = library.pointVisuals[visualIndex.value()].style;
            hasResolvedStyle = true;
        } else if (const auto stateIndex = FindScenePointVisualStateByNameIndex(library, selectedName);
                   stateIndex.has_value()) {
            style = library.sceneVisualStates[stateIndex.value()].visual.style;
            selectedName = library.sceneVisualStates[stateIndex.value()].visual.name;
            hasResolvedStyle = true;
        }
    }

    if (!hasResolvedStyle) {
        if (const auto visualIndex = FindProjectPointVisualIndex(library, selectedName);
            visualIndex.has_value()) {
            style = library.pointVisuals[visualIndex.value()].style;
            hasResolvedStyle = true;
        }
    }

    const auto selectedBaseName = BaseNameFromProjectPointVisualName(library, selectedName);
    const auto stateIndex = FindScenePointVisualStateForBaseIndex(library, sceneKey, selectedBaseName);
    const bool useSceneOverride = !useSessionSelection && stateIndex.has_value();
    if (useSceneOverride) {
        selectedName = library.sceneVisualStates[stateIndex.value()].visual.name;
        style = library.sceneVisualStates[stateIndex.value()].visual.style;
        hasResolvedStyle = true;
    }

    if (!session->scalarFields.empty()) {
        ResolveProjectVisualStyleBindingsByFieldName(&style, *session);
    }

    session->selectedPointVisualName = NormalizePointVisualName(selectedName);
    session->pointVisualNameBuffer =
        BaseNameFromProjectPointVisualName(library, session->selectedPointVisualName);
    session->pointStyle = style;
    CopyProjectVisualsToSessionList(runtimeState, session, session->selectedPointVisualName, session->pointStyle);
    SanitizePointCloudStyle(session);
}

void ApplyProjectPointVisualsToScene(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sceneSession) {
    if (runtimeState == nullptr) {
        return;
    }

    const auto sceneKey = ProjectVisualSceneKey(sceneSession);
    for (auto& candidate : runtimeState->sessions) {
        if (!IsProjectPointVisualSession(candidate) ||
            ProjectVisualSceneKey(candidate) != sceneKey) {
            continue;
        }
        ApplyProjectPointVisualToSession(runtimeState, &candidate);
    }
}

void ApplyProjectPointVisualsToAllSessions(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    EnsureProjectPointVisuals(runtimeState);
    for (auto& session : runtimeState->sessions) {
        ApplyProjectPointVisualToSession(runtimeState, &session);
    }
}

void RecordCurrentAnimationPointVisualSelection(
    PreviewRuntimeState* runtimeState,
    std::string_view visualName);

std::string SelectProjectPointVisualForScene(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sceneSession,
    std::string_view name,
    bool recordAnimationSelection = true) {
    if (runtimeState == nullptr) {
        return {};
    }

    EnsureProjectPointVisuals(runtimeState);
    const auto normalized = NormalizePointVisualName(name);
    const bool isProjectVisual =
        FindProjectPointVisualIndex(runtimeState->pointVisualLibrary, normalized).has_value();
    const bool isSceneVisual =
        FindScenePointVisualStateByNameIndex(runtimeState->pointVisualLibrary, normalized).has_value();
    if (!isProjectVisual && !isSceneVisual) {
        return {};
    }

    if (isProjectVisual) {
        runtimeState->pointVisualLibrary.selectedPointVisualName = normalized;
    }
    runtimeState->pointVisualLibrary.pointVisualNameBuffer =
        BaseNameFromProjectPointVisualName(runtimeState->pointVisualLibrary, normalized);

    const auto sceneKey = ProjectVisualSceneKey(sceneSession);
    const auto selectedStyle = ProjectPointVisualStyleByName(runtimeState->pointVisualLibrary, normalized);
    for (auto& candidate : runtimeState->sessions) {
        if (!IsProjectPointVisualSession(candidate) ||
            ProjectVisualSceneKey(candidate) != sceneKey) {
            continue;
        }
        candidate.selectedPointVisualName = normalized;
        candidate.pointVisualNameBuffer = runtimeState->pointVisualLibrary.pointVisualNameBuffer;
        ApplyProjectPointVisualToSession(runtimeState, &candidate);
    }
    if (recordAnimationSelection) {
        RecordCurrentAnimationPointVisualSelection(
            runtimeState,
            normalized);
    }
    return BuildProjectVisualFieldBindingWarning(*runtimeState, sceneKey, normalized, selectedStyle);
}

bool IsWaterProjectCustomVisualName(std::string_view name) {
    const auto normalized = NormalizePointVisualName(name);
    return !normalized.empty() &&
           !IsPresetPointVisualName(normalized) &&
           !IsEditedPointVisualName(normalized);
}

std::optional<std::size_t> FindWaterProjectVisualIndex(
    const std::vector<SavedPointVisualState>& visuals,
    std::string_view name) {
    return invisible_places::app::point_visual::FindIndex(visuals, name);
}

void AppendWaterPointVisualIfMissing(
    std::vector<SavedPointVisualState>* visuals,
    std::string_view name,
    const PointCloudStyleState& style) {
    if (visuals == nullptr || !IsWaterProjectCustomVisualName(name)) {
        return;
    }

    const auto normalized = NormalizePointVisualName(name);
    if (FindWaterProjectVisualIndex(*visuals, normalized).has_value()) {
        return;
    }

    visuals->push_back({.name = normalized, .style = MakeWaterTrailExportStyle(style)});
}

void UpsertWaterProjectVisual(
    PreviewRuntimeState* runtimeState,
    std::string_view name,
    const PointCloudStyleState& style) {
    if (runtimeState == nullptr) {
        return;
    }

    const auto normalized = NormalizePointVisualName(name);
    if (!IsWaterProjectCustomVisualName(normalized)) {
        return;
    }
    invisible_places::app::point_visual::Upsert(
        &runtimeState->water.pointVisuals,
        normalized,
        MakeWaterTrailExportStyle(style));
    runtimeState->water.selectedPointVisualName = normalized;
    runtimeState->water.pointVisualNameBuffer = BasePointVisualName(normalized);
}

void ImportLegacyWaterPointVisualStyle(
    PreviewRuntimeState* runtimeState,
    const PointCloudStyleState& style,
    std::string_view customName = "Water Flow") {
    if (runtimeState == nullptr) {
        return;
    }

    const auto normalized = NormalizePointVisualName(customName);
    if (!FindWaterProjectVisualIndex(runtimeState->water.pointVisuals, normalized).has_value()) {
        UpsertWaterProjectVisual(runtimeState, normalized, style);
    }
    if (runtimeState->water.selectedPointVisualName.empty() ||
        runtimeState->water.selectedPointVisualName == "Water Flow_preset") {
        runtimeState->water.selectedPointVisualName = normalized;
        runtimeState->water.pointVisualNameBuffer = BasePointVisualName(normalized);
    }
}

void SyncWaterPointVisualSelectionFromSession(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& session) {
    if (runtimeState == nullptr || !IsGeneratedWaterFlowOverlaySession(session)) {
        return;
    }

    runtimeState->water.selectedPointVisualName = NormalizePointVisualName(session.selectedPointVisualName);
    runtimeState->water.pointVisualNameBuffer = BasePointVisualName(runtimeState->water.selectedPointVisualName);
}

void RemovePointVisual(PreviewLayerSession* session, std::string_view name) {
    if (session == nullptr) {
        return;
    }

    invisible_places::app::point_visual::Remove(&session->pointVisuals, name);
}

void SyncPointVisualNameBuffer(PreviewLayerSession* session) {
    if (session == nullptr) {
        return;
    }
    invisible_places::app::point_visual::SyncNameBuffer(
        &session->pointVisualNameBuffer,
        session->selectedPointVisualName);
}

void EnsurePointVisuals(PreviewLayerSession* session) {
    if (session == nullptr || session->kind != LayerKind::PointCloud) {
        return;
    }

    invisible_places::app::point_visual::Ensure(
        &session->pointVisuals,
        &session->selectedPointVisualName,
        &session->pointVisualNameBuffer,
        session->pointStyle);
}

void SelectPointVisual(PreviewLayerSession* session, std::string_view name) {
    if (session == nullptr) {
        return;
    }

    const bool selected = invisible_places::app::point_visual::Select(
        &session->pointVisuals,
        &session->selectedPointVisualName,
        &session->pointVisualNameBuffer,
        &session->pointStyle,
        name,
        session->pointStyle);
    (void)selected;
}

void MarkPointVisualEdited(PreviewLayerSession* session) {
    if (session == nullptr || session->kind != LayerKind::PointCloud) {
        return;
    }

    EnsurePointVisuals(session);
    const auto selectedName = NormalizePointVisualName(session->selectedPointVisualName);
    if (IsEditedPointVisualName(selectedName)) {
        UpsertPointVisual(session, selectedName, session->pointStyle);
        session->selectedPointVisualName = selectedName;
        return;
    }

    const auto editedName = EditedPointVisualName(selectedName);
    UpsertPointVisual(session, editedName, session->pointStyle);
    session->selectedPointVisualName = editedName;
    SyncPointVisualNameBuffer(session);
}

void MarkPointVisualEdited(PreviewRuntimeState* runtimeState, PreviewLayerSession* session) {
    if (runtimeState == nullptr || session == nullptr || session->kind != LayerKind::PointCloud) {
        return;
    }

    if (!IsProjectPointVisualSession(*session)) {
        MarkPointVisualEdited(session);
        return;
    }

    EnsureProjectPointVisuals(runtimeState);
    auto baseName =
        BaseNameFromProjectPointVisualName(runtimeState->pointVisualLibrary, session->selectedPointVisualName);
    if (!FindProjectPointVisualIndex(runtimeState->pointVisualLibrary, baseName).has_value()) {
        baseName = runtimeState->pointVisualLibrary.selectedPointVisualName;
    }
    const auto tempName = SceneTemporaryPointVisualName(baseName, *session);
    UpsertScenePointVisualState(runtimeState, *session, tempName, session->pointStyle);
    const auto warning = SelectProjectPointVisualForScene(runtimeState, *session, tempName);
    UpdateProjectVisualFieldBindingWarning(runtimeState, warning);
}

void SaveCurrentPointVisual(PreviewRuntimeState* runtimeState, PreviewLayerSession* session) {
    if (runtimeState == nullptr || session == nullptr || session->kind != LayerKind::PointCloud) {
        return;
    }

    if (IsProjectPointVisualSession(*session)) {
        EnsureProjectPointVisuals(runtimeState);
        const auto selectedName = NormalizePointVisualName(session->selectedPointVisualName);
        const auto fallbackName =
            BaseNameFromProjectPointVisualName(runtimeState->pointVisualLibrary, selectedName);
        const auto targetName = BasePointVisualName(
            session->pointVisualNameBuffer.empty()
                ? fallbackName
                : session->pointVisualNameBuffer);
        UpsertProjectPointVisual(runtimeState, targetName, session->pointStyle);
        runtimeState->pointVisualLibrary.selectedPointVisualName = targetName;
        runtimeState->pointVisualLibrary.pointVisualNameBuffer = BasePointVisualName(targetName);
        RemoveScenePointVisualStateForBase(runtimeState, ProjectVisualSceneKey(*session), targetName);
        session->selectedPointVisualName = targetName;
        session->pointVisualNameBuffer = BasePointVisualName(targetName);
        ApplyProjectPointVisualsToAllSessions(runtimeState);
        RecordCurrentAnimationPointVisualSelection(
            runtimeState,
            targetName);
        runtimeState->statusMessage = "Saved project visual " + targetName + ".";
        runtimeState->errorMessage.clear();
        return;
    }

    EnsurePointVisuals(session);
    const auto selectedName = NormalizePointVisualName(session->selectedPointVisualName);
    const auto targetName = BasePointVisualName(
        session->pointVisualNameBuffer.empty()
            ? BasePointVisualName(selectedName)
            : session->pointVisualNameBuffer);
    if (IsGeneratedWaterFlowOverlaySession(*session) &&
        (IsPresetPointVisualName(targetName) || IsEditedPointVisualName(targetName))) {
        runtimeState->errorMessage =
            "Choose a new custom water visual name; preset and edited names cannot be overwritten.";
        runtimeState->statusMessage.clear();
        return;
    }

    UpsertPointVisual(session, targetName, session->pointStyle);
    if (IsGeneratedWaterFlowOverlaySession(*session)) {
        UpsertWaterProjectVisual(runtimeState, targetName, session->pointStyle);
    }
    if (IsEditedPointVisualName(selectedName)) {
        RemovePointVisual(session, selectedName);
        if (BasePointVisualName(selectedName) == std::string{kDefaultPointVisualName} &&
            targetName != std::string{kDefaultPointVisualName} &&
            session->pointVisuals.size() > 1U) {
            RemovePointVisual(session, kDefaultPointVisualName);
        }
    } else if (
        selectedName == std::string{kDefaultPointVisualName} &&
        targetName != selectedName &&
        session->pointVisuals.size() > 1U) {
        RemovePointVisual(session, selectedName);
    }

    session->selectedPointVisualName = targetName;
    SyncPointVisualNameBuffer(session);
    if (IsGeneratedWaterFlowOverlaySession(*session)) {
        runtimeState->water.selectedPointVisualName = targetName;
        runtimeState->water.pointVisualNameBuffer = BasePointVisualName(targetName);
        ApplyWaterPointVisualStyleToGeneratedSessions(runtimeState);
    }
    runtimeState->statusMessage = "Saved visual " + targetName + ".";
    runtimeState->errorMessage.clear();
}

void DeleteCurrentScenePointVisual(PreviewRuntimeState* runtimeState, PreviewLayerSession* session) {
    if (runtimeState == nullptr || session == nullptr || !IsProjectPointVisualSession(*session)) {
        return;
    }

    EnsureProjectPointVisuals(runtimeState);
    const auto selectedStateIndex = FindScenePointVisualStateByNameIndex(
        runtimeState->pointVisualLibrary,
        session->selectedPointVisualName);
    const auto sceneKey = ProjectVisualSceneKey(*session);
    if (!selectedStateIndex.has_value() ||
        runtimeState->pointVisualLibrary.sceneVisualStates[selectedStateIndex.value()].sceneGroupName != sceneKey) {
        runtimeState->errorMessage = "Only the active scene visual can be deleted here.";
        runtimeState->statusMessage.clear();
        return;
    }

    const auto baseName =
        BaseNameFromProjectPointVisualName(runtimeState->pointVisualLibrary, session->selectedPointVisualName);
    const auto deletedName = SceneTemporaryPointVisualName(baseName, *session);
    RemoveScenePointVisualStateForBase(runtimeState, sceneKey, baseName);
    const auto fallbackName = FindProjectPointVisualIndex(runtimeState->pointVisualLibrary, baseName).has_value()
                                  ? baseName
                                  : runtimeState->pointVisualLibrary.selectedPointVisualName;
    const auto warning = SelectProjectPointVisualForScene(runtimeState, *session, fallbackName);
    if (!warning.empty()) {
        UpdateProjectVisualFieldBindingWarning(runtimeState, warning);
        return;
    }
    runtimeState->statusMessage = "Deleted scene visual " + deletedName + ".";
    runtimeState->errorMessage.clear();
}

bool DrawSectionHeader(
    const char* label,
    bool defaultOpen = true,
    bool* headerActive = nullptr,
    bool* headerActiveChanged = nullptr) {
    static std::unordered_map<ImGuiID, bool> collapsedSections;

    const ImGuiStyle& style = ImGui::GetStyle();
    const ImGuiID sectionId = ImGui::GetID(label);
    const auto sectionIt = collapsedSections.try_emplace(sectionId, !defaultOpen).first;
    bool& collapsed = sectionIt->second;
    const bool open = !collapsed;
    const float textHeight = ImGui::GetTextLineHeight();
    const float rowHeight = textHeight + style.FramePadding.y * 2.0F;
    const float toggleWidth = 22.0F;
    const ImVec2 cursor = ImGui::GetCursorScreenPos();
    const ImU32 lineColor = ImGui::GetColorU32(ImGuiCol_Separator);
    const ImU32 textColor = ImGui::GetColorU32(ImGuiCol_Text);

    ImGui::PushID(label);
    ImGui::InvisibleButton("##section_toggle", ImVec2{toggleWidth, rowHeight});
    if (ImGui::IsItemClicked(ImGuiMouseButton_Left)) {
        collapsed = !collapsed;
    }

    ImDrawList* drawList = ImGui::GetWindowDrawList();
    const float lineY = cursor.y + rowHeight * 0.5F;
    const float lineStartX = cursor.x + 3.0F;
    const float lineEndX = cursor.x + toggleWidth - 3.0F;
    drawList->AddLine(ImVec2{lineStartX, lineY}, ImVec2{lineEndX, lineY}, lineColor, 2.0F);
    if (collapsed) {
        const float centerX = cursor.x + toggleWidth * 0.5F;
        drawList->AddLine(
            ImVec2{centerX, cursor.y + 4.0F},
            ImVec2{centerX, cursor.y + rowHeight - 4.0F},
            lineColor,
            2.0F);
    }

    ImGui::SameLine(0.0F, style.ItemSpacing.x);
    ImGui::AlignTextToFramePadding();
    ImGui::TextColored(ImGui::ColorConvertU32ToFloat4(textColor), "%s", label);

    ImVec2 headingEnd = ImGui::GetItemRectMax();
    if (headerActive != nullptr) {
        ImGui::SameLine(0.0F, style.ItemSpacing.x);
        bool active = *headerActive;
        if (ImGui::Checkbox("Active##section_active", &active)) {
            *headerActive = active;
            if (headerActiveChanged != nullptr) {
                *headerActiveChanged = true;
            }
        }
        headingEnd = ImGui::GetItemRectMax();
    }

    const float availableEndX = ImGui::GetWindowPos().x + ImGui::GetWindowContentRegionMax().x;
    const float continuationStartX = headingEnd.x + style.ItemSpacing.x;
    if (availableEndX > continuationStartX) {
        drawList->AddLine(
            ImVec2{continuationStartX, lineY},
            ImVec2{availableEndX, lineY},
            lineColor,
            2.0F);
    }

    ImGui::PopID();
    return open;
}

bool BeginPanelSection(
    const char* label,
    bool defaultOpen = true,
    bool* headerActive = nullptr,
    bool* headerActiveChanged = nullptr) {
    if (headerActiveChanged != nullptr) {
        *headerActiveChanged = false;
    }
    const bool open = DrawSectionHeader(label, defaultOpen, headerActive, headerActiveChanged);
    if (open) {
        ImGui::PushID(label);
        ImGui::Spacing();
    }
    return open;
}

void EndPanelSection() {
    ImGui::Spacing();
    ImGui::PopID();
}

bool DrawRightAlignedCombo(
    const char* label,
    int* currentItem,
    const char* const* items,
    int itemCount,
    float comboWidth = 210.0F) {
    if (currentItem == nullptr || items == nullptr || itemCount <= 0) {
        return false;
    }

    ImGui::PushID(label);
    ImGui::AlignTextToFramePadding();
    ImGui::TextUnformatted(label);
    ImGui::SameLine();
    const float cursorX = ImGui::GetCursorPosX();
    const float rightX = ImGui::GetWindowContentRegionMax().x;
    ImGui::SetCursorPosX(std::max(cursorX, rightX - comboWidth));
    ImGui::SetNextItemWidth(std::min(comboWidth, ImGui::GetContentRegionAvail().x));
    const bool changed = ImGui::Combo("##combo", currentItem, items, itemCount);
    ImGui::PopID();
    return changed;
}

struct RangedFloatControlConfig {
    float visualMin = 0.0F;
    float visualMax = 1.0F;
    const char* format = "%.3f";
    float speed = 0.0F;
    bool showLabel = true;
    bool scaleDragToWidth = false;
    std::optional<float> hardMin = std::nullopt;
    std::optional<float> hardMax = std::nullopt;
    std::optional<float> width = std::nullopt;
};

bool IsValidRangedFloatValue(float value, const RangedFloatControlConfig& config) {
    if (!std::isfinite(value)) {
        return false;
    }
    if (config.hardMin.has_value() && value < config.hardMin.value()) {
        return false;
    }
    if (config.hardMax.has_value() && value > config.hardMax.value()) {
        return false;
    }
    return true;
}

bool TryAssignRangedFloatValue(float* value, float candidate, const RangedFloatControlConfig& config) {
    if (value == nullptr || !IsValidRangedFloatValue(candidate, config)) {
        return false;
    }

    if (*value == candidate) {
        return false;
    }

    *value = candidate;
    return true;
}

std::string FormatRangedFloatLimit(float value, const RangedFloatControlConfig& config) {
    std::array<char, 64> buffer{};
    std::snprintf(buffer.data(), buffer.size(), config.format != nullptr ? config.format : "%.3f", value);
    return buffer.data();
}

std::string RangedFloatValidationMessage(float candidate, const RangedFloatControlConfig& config) {
    if (!std::isfinite(candidate)) {
        return "Enter a finite value.";
    }
    if (config.hardMin.has_value() && candidate < config.hardMin.value()) {
        return "Minimum " + FormatRangedFloatLimit(config.hardMin.value(), config) + ".";
    }
    if (config.hardMax.has_value() && candidate > config.hardMax.value()) {
        return "Maximum " + FormatRangedFloatLimit(config.hardMax.value(), config) + ".";
    }
    return {};
}

bool DrawRangedFloatControl(const char* label, float* value, const RangedFloatControlConfig& config) {
    if (value == nullptr) {
        return false;
    }

    const float visualMin = std::min(config.visualMin, config.visualMax);
    const float visualMax = std::max(config.visualMin, config.visualMax);
    const float visualRange = std::max(visualMax - visualMin, 1.0e-6F);
    static ImGuiID editingControlId = 0;
    static ImGuiID focusEditingControlId = 0;
    static ImGuiID activeDragId = 0;
    static ImGuiID invalidInputControlId = 0;
    static std::string invalidInputMessage;
    static float activeDragStartValue = 0.0F;
    static ImVec2 activeDragStartMouse{};
    bool changed = false;

    ImGui::PushID(label);
    const ImGuiID controlId = ImGui::GetID("##range");
    if (config.showLabel) {
        ImGui::AlignTextToFramePadding();
        ImGui::TextUnformatted(label);
        ImGui::SameLine();
    }

    const ImGuiStyle& style = ImGui::GetStyle();
    const float barWidth = std::max(
        110.0F,
        config.width.value_or(ImGui::GetContentRegionAvail().x));
    const float frameHeight = ImGui::GetFrameHeight();
    const float dragSpeed =
        config.speed > 0.0F
            ? config.speed
            : visualRange /
                  (config.scaleDragToWidth
                       ? std::max(1.0F, barWidth)
                       : 200.0F);

    if (editingControlId == controlId) {
        float inputValue = *value;
        ImGui::SetNextItemWidth(barWidth);
        if (focusEditingControlId == controlId) {
            ImGui::SetKeyboardFocusHere();
            focusEditingControlId = 0;
        }
        if (ImGui::InputFloat("##value", &inputValue, 0.0F, 0.0F, config.format)) {
            if (TryAssignRangedFloatValue(value, inputValue, config)) {
                changed = true;
                if (invalidInputControlId == controlId) {
                    invalidInputControlId = 0;
                    invalidInputMessage.clear();
                }
            } else if (!IsValidRangedFloatValue(inputValue, config)) {
                invalidInputControlId = controlId;
                invalidInputMessage = RangedFloatValidationMessage(inputValue, config);
            }
        }
        if (invalidInputControlId == controlId && !invalidInputMessage.empty()) {
            ImGui::PushStyleColor(ImGuiCol_Text, ImGui::GetColorU32(ImGuiCol_TextDisabled));
            ImGui::TextWrapped("%s", invalidInputMessage.c_str());
            ImGui::PopStyleColor();
        }
        if (ImGui::IsItemDeactivated()) {
            editingControlId = 0;
            if (invalidInputControlId == controlId) {
                invalidInputControlId = 0;
                invalidInputMessage.clear();
            }
        }
        ImGui::PopID();
        return changed;
    }

    const ImVec2 barMin = ImGui::GetCursorScreenPos();
    const ImVec2 barMax{barMin.x + barWidth, barMin.y + frameHeight};
    ImGui::InvisibleButton("##range", ImVec2{barWidth, frameHeight});
    if (ImGui::IsItemHovered() && ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left)) {
        editingControlId = controlId;
        focusEditingControlId = controlId;
    }
    if (ImGui::IsItemActivated()) {
        activeDragId = controlId;
        activeDragStartValue = std::clamp(*value, visualMin, visualMax);
        activeDragStartMouse = ImGui::GetIO().MousePos;
    }
    if (activeDragId == controlId && ImGui::IsItemActive()) {
        const float deltaX = ImGui::GetIO().MousePos.x - activeDragStartMouse.x;
        if (std::abs(deltaX) > 0.0F) {
            const float candidate = std::clamp(activeDragStartValue + deltaX * dragSpeed, visualMin, visualMax);
            changed |= TryAssignRangedFloatValue(value, candidate, config);
        }
    }
    if (activeDragId == controlId && !ImGui::IsMouseDown(ImGuiMouseButton_Left)) {
        activeDragId = 0;
    }

    const float fillT = std::clamp((*value - visualMin) / visualRange, 0.0F, 1.0F);
    ImDrawList* drawList = ImGui::GetWindowDrawList();
    const ImU32 frameColor = ImGui::GetColorU32(ImGuiCol_FrameBg);
    const ImU32 fillColor = ImGui::GetColorU32(ImGuiCol_SliderGrabActive);
    const ImU32 borderColor = ImGui::GetColorU32(ImGuiCol_Border);
    const ImU32 textColor = ImGui::GetColorU32(ImGuiCol_Text);
    drawList->AddRectFilled(barMin, barMax, frameColor, style.FrameRounding);
    drawList->AddRectFilled(
        barMin,
        ImVec2{barMin.x + barWidth * fillT, barMax.y},
        fillColor,
        style.FrameRounding);
    drawList->AddRect(barMin, barMax, borderColor, style.FrameRounding);

    char valueText[64]{};
    std::snprintf(valueText, sizeof(valueText), config.format, *value);
    const ImVec2 textSize = ImGui::CalcTextSize(valueText);
    drawList->AddText(
        ImVec2{barMin.x + (barWidth - textSize.x) * 0.5F, barMin.y + (frameHeight - textSize.y) * 0.5F},
        textColor,
        valueText);

    ImGui::PopID();
    return changed;
}

bool IsNormalisedWaterSliderRange(float minimumValue, float maximumValue) {
    constexpr float kRangeTolerance = 1.0e-6F;
    return std::abs(minimumValue) <= kRangeTolerance &&
           std::abs(maximumValue - 1.0F) <= kRangeTolerance;
}

std::optional<std::size_t> WaterSliderFloatingConversion(
    std::string_view format) {
    std::size_t searchFrom = 0U;
    while (searchFrom < format.size()) {
        const auto percent = format.find('%', searchFrom);
        if (percent == std::string_view::npos || percent + 1U >= format.size()) {
            return std::nullopt;
        }
        if (format[percent + 1U] == '%') {
            searchFrom = percent + 2U;
            continue;
        }
        const auto conversion =
            format.find_first_of("aAeEfFgG", percent + 1U);
        if (conversion == std::string_view::npos) {
            return std::nullopt;
        }
        return conversion;
    }
    return std::nullopt;
}

std::string WaterSliderDisplayFormat(
    float minimumValue,
    float maximumValue,
    const char* requestedFormat,
    bool requireNumericFormat) {
    std::string format = requestedFormat != nullptr
                             ? std::string{requestedFormat}
                             : std::string{"%.3f"};
    auto conversion = WaterSliderFloatingConversion(format);
    if (!conversion.has_value()) {
        return requireNumericFormat ? std::string{"%.3f"} : format;
    }
    if (!IsNormalisedWaterSliderRange(minimumValue, maximumValue)) {
        return format;
    }

    const auto percent = format.rfind('%', conversion.value());
    const auto decimal = format.find('.', percent + 1U);
    if (decimal != std::string::npos && decimal < conversion.value()) {
        auto precisionEnd = decimal + 1U;
        while (precisionEnd < conversion.value() &&
               std::isdigit(
                   static_cast<unsigned char>(format[precisionEnd])) != 0) {
            ++precisionEnd;
        }
        format.replace(decimal + 1U, precisionEnd - decimal - 1U, "3");
    } else {
        format.insert(conversion.value(), ".3");
    }
    return format;
}

// SliderScalar supports Ctrl-click text entry, but unlike DragScalar it does
// not opt into text entry on double-click. Requesting ImGui's own preferred
// input activation preserves the native slider and InputScalar behaviours.
bool ActivateWaterSliderTextInputOnDoubleClick(const char* label) {
    if (label == nullptr ||
        !ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left) ||
        !ImGui::IsWindowHovered(ImGuiHoveredFlags_ChildWindows)) {
        return false;
    }
    const ImVec2 frameMinimum = ImGui::GetCursorScreenPos();
    const ImVec2 frameMaximum{
        frameMinimum.x + ImGui::CalcItemWidth(),
        frameMinimum.y + ImGui::GetFrameHeight()};
    if (!ImGui::IsMouseHoveringRect(frameMinimum, frameMaximum)) {
        return false;
    }

    ImGuiContext& context = *GImGui;
    context.NavActivateId = ImGui::GetID(label);
    context.NavActivateFlags = ImGuiActivateFlags_PreferInput;
    return true;
}

bool DrawWaterSliderFloat(
    const char* label,
    float* value,
    float minimumValue,
    float maximumValue,
    const char* format = "%.3f",
    ImGuiSliderFlags flags = ImGuiSliderFlags_None) {
    const ImGuiID id = ImGui::GetID(label);
    const bool textInputRequested =
        ActivateWaterSliderTextInputOnDoubleClick(label);
    const bool textInputActive =
        textInputRequested || ImGui::TempInputIsActive(id);
    const auto displayFormat = WaterSliderDisplayFormat(
        minimumValue,
        maximumValue,
        format,
        textInputActive);
    if (IsNormalisedWaterSliderRange(minimumValue, maximumValue)) {
        flags |= ImGuiSliderFlags_NoRoundToFormat;
    }
    return ImGui::SliderFloat(
        label,
        value,
        minimumValue,
        maximumValue,
        displayFormat.c_str(),
        flags);
}

bool DrawWaterSliderInt(
    const char* label,
    int* value,
    int minimumValue,
    int maximumValue,
    const char* format = "%d",
    ImGuiSliderFlags flags = ImGuiSliderFlags_None) {
    const ImGuiID id = ImGui::GetID(label);
    const bool textInputRequested =
        ActivateWaterSliderTextInputOnDoubleClick(label);
    const bool textInputActive =
        textInputRequested || ImGui::TempInputIsActive(id);
    const char* displayFormat =
        textInputActive &&
                (format == nullptr || std::string_view{format}.find('%') ==
                                          std::string_view::npos)
            ? "%d"
            : format;
    return ImGui::SliderInt(
        label,
        value,
        minimumValue,
        maximumValue,
        displayFormat,
        flags);
}

