std::uint32_t NextWaterEmitterId(const PreviewRuntimeState& runtimeState) {
    std::uint32_t nextId = std::max<std::uint32_t>(1U, runtimeState.water.nextEmitterId);
    for (const auto& emitter : runtimeState.water.emitters) {
        nextId = std::max<std::uint32_t>(nextId, emitter.id + 1U);
    }
    for (const auto& path : runtimeState.water.manualFlowPaths) {
        nextId = std::max<std::uint32_t>(nextId, path.id + 1U);
    }
    return nextId;
}

std::uint32_t NextWaterSeepageNodeId(const PreviewRuntimeState& runtimeState) {
    std::uint32_t nextId = std::max<std::uint32_t>(1U, runtimeState.water.nextSeepageNodeId);
    for (const auto& node : runtimeState.water.seepageNodes) {
        nextId = std::max<std::uint32_t>(nextId, node.id + 1U);
    }
    return nextId;
}

WaterSeepageNode* SelectedWaterSeepageNode(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr ||
        !runtimeState->water.selectedSeepageNodeIndex.has_value() ||
        runtimeState->water.selectedSeepageNodeIndex.value() >= runtimeState->water.seepageNodes.size()) {
        return nullptr;
    }
    return &runtimeState->water.seepageNodes[runtimeState->water.selectedSeepageNodeIndex.value()];
}

const WaterSeepageNode* SelectedWaterSeepageNode(const PreviewRuntimeState& runtimeState) {
    if (!runtimeState.water.selectedSeepageNodeIndex.has_value() ||
        runtimeState.water.selectedSeepageNodeIndex.value() >= runtimeState.water.seepageNodes.size()) {
        return nullptr;
    }
    return &runtimeState.water.seepageNodes[runtimeState.water.selectedSeepageNodeIndex.value()];
}

void ClearWaterSeepageSelection(WaterWorkflowState* water) {
    water->selectedSeepageNodeIndex.reset();
    water->selectedSeepageNodeIndices.clear();
}

void SetWaterSeepageSingleSelection(WaterWorkflowState* water, std::size_t index) {
    water->selectedSeepageNodeIndex = index;
    water->selectedSeepageNodeIndices.clear();
    water->selectedSeepageNodeIndices.insert(index);
}

// Shared list/viewport click semantics for the Seepage node selection.
// Plain click single-selects; Ctrl toggles membership (promoting another
// member to primary when the primary itself is removed, and falling back to
// a single selection of the clicked index when the set would become empty);
// Shift selects the contiguous range between the primary and the clicked
// index without changing the primary.
void ApplyWaterSeepageSelectionClick(
    WaterWorkflowState* water,
    std::size_t index,
    bool ctrlHeld,
    bool shiftHeld) {
    auto& members = water->selectedSeepageNodeIndices;
    if (ctrlHeld) {
        if (members.erase(index) > 0U) {
            if (members.empty()) {
                SetWaterSeepageSingleSelection(water, index);
            } else if (water->selectedSeepageNodeIndex == index) {
                water->selectedSeepageNodeIndex = *members.begin();
            }
        } else {
            members.insert(index);
            water->selectedSeepageNodeIndex = index;
        }
        return;
    }
    if (shiftHeld && water->selectedSeepageNodeIndex.has_value() &&
        water->selectedSeepageNodeIndex.value() < water->seepageNodes.size()) {
        const std::size_t primary = water->selectedSeepageNodeIndex.value();
        members.clear();
        for (std::size_t member = std::min(primary, index);
             member <= std::max(primary, index);
             ++member) {
            members.insert(member);
        }
        return;
    }
    SetWaterSeepageSingleSelection(water, index);
}

std::string NormalizeWaterShorelineProfileName(std::string_view name) {
    return TrimText(name);
}

std::uint32_t NextAvailableShorelineInstanceId(
    const std::vector<
        invisible_places::renderer::pointcloud::PointCloudShorelineInstance>&
        instances) {
    std::uint32_t next = 1U;
    for (const auto& instance : instances) {
        next = std::max(next, instance.id + 1U);
    }
    return next;
}

std::optional<std::size_t> FindWaterShorelineProfileIndex(
    const WaterWorkflowState& water,
    std::string_view name) {
    const auto normalized = NormalizeWaterShorelineProfileName(name);
    for (std::size_t index = 0; index < water.shorelineProfiles.size(); ++index) {
        if (NormalizeWaterShorelineProfileName(
                water.shorelineProfiles[index].name) == normalized) {
            return index;
        }
    }
    return std::nullopt;
}

std::optional<std::size_t> FindWaterShorelineObjectProfileIndex(
    const WaterWorkflowState& water,
    std::uint32_t instanceId,
    std::string_view baseProfileName) {
    const auto base = NormalizeWaterShorelineProfileName(baseProfileName);
    for (std::size_t index = 0U; index < water.shorelineProfiles.size(); ++index) {
        const auto& profile = water.shorelineProfiles[index];
        if (profile.objectOverride &&
            profile.shorelineInstanceId == instanceId &&
            NormalizeWaterShorelineProfileName(profile.baseProfileName) == base) {
            return index;
        }
    }
    return std::nullopt;
}

std::string UniqueWaterShorelineProfileName(
    const WaterWorkflowState& water,
    std::string_view preferredName) {
    const std::string preferred =
        NormalizeWaterShorelineProfileName(preferredName).empty()
            ? std::string{"Shoreline Profile"}
            : NormalizeWaterShorelineProfileName(preferredName);
    if (!FindWaterShorelineProfileIndex(water, preferred).has_value()) {
        return preferred;
    }
    for (std::uint32_t suffix = 2U; suffix < 10000U; ++suffix) {
        const auto candidate = preferred + " " + std::to_string(suffix);
        if (!FindWaterShorelineProfileIndex(water, candidate).has_value()) {
            return candidate;
        }
    }
    return preferred + " Copy";
}

void NormalizeWaterShorelineState(
    WaterWorkflowState* water,
    const std::optional<PointCloudShorelineWaveSettings>& legacyPrimary =
        std::nullopt) {
    if (water == nullptr) {
        return;
    }

    // Default and code-owned point-visual presets were artifacts of the old
    // ownership model. Capture a usable legacy value before removing those
    // names; no new project or standalone Water save emits them.
    const std::string legacySelection =
        NormalizeWaterShorelineProfileName(
            water->selectedShorelineProfileName);
    std::erase_if(
        water->shorelineProfiles,
        [](const PointCloudShorelineWaveProfile& profile) {
            const auto name =
                NormalizeWaterShorelineProfileName(profile.name);
            return name.empty() || name == "Default" ||
                   name.ends_with("_preset");
        });

    if (legacyPrimary.has_value() && legacyPrimary->enabled &&
        water->shorelineInstances.size() <
            invisible_places::renderer::pointcloud::
                kMaxShorelineInstances) {
        std::string baseName = legacySelection;
        if (baseName.empty() || baseName == "Default" ||
            baseName.ends_with("_preset") ||
            baseName.ends_with("_edited")) {
            baseName = "Shoreline";
        }
        if (const auto editedSuffix = baseName.rfind("_edited");
            editedSuffix != std::string::npos &&
            editedSuffix + 7U == baseName.size()) {
            baseName.resize(editedSuffix);
        }
        if (FindWaterShorelineProfileIndex(*water, baseName).has_value()) {
            baseName = UniqueWaterShorelineProfileName(*water, baseName);
        }
        water->shorelineProfiles.push_back({
            .name = baseName,
            .settings = legacyPrimary.value(),
        });
        PointCloudShorelineInstance primary;
        primary.id = NextAvailableShorelineInstanceId(
            water->shorelineInstances);
        primary.name = "Shoreline";
        primary.enabled = true;
        primary.profileName = baseName;
        primary.baseProfileName = baseName;
        primary.settings = legacyPrimary.value();
        water->shorelineInstances.insert(
            water->shorelineInstances.begin(),
            std::move(primary));
    }

    for (auto& instance : water->shorelineInstances) {
        instance.name = TrimText(instance.name);
        if (instance.name.empty()) {
            instance.name =
                "Shoreline " + std::to_string(instance.id);
        }
        instance.profileName =
            NormalizeWaterShorelineProfileName(instance.profileName);
        instance.baseProfileName =
            NormalizeWaterShorelineProfileName(instance.baseProfileName);
        std::optional<std::size_t> assignedProfileIndex;
        // Object-copy names are human-readable and can theoretically collide
        // with another base name. Metadata is authoritative for an applied
        // object copy; selecting the base remains unambiguous because then
        // profileName and baseProfileName are equal.
        if (!instance.profileName.empty() &&
            instance.profileName != instance.baseProfileName) {
            if (const auto objectProfile =
                    FindWaterShorelineObjectProfileIndex(
                        *water,
                        instance.id,
                        instance.baseProfileName);
                objectProfile.has_value() &&
                NormalizeWaterShorelineProfileName(
                    water->shorelineProfiles[objectProfile.value()].name) ==
                    instance.profileName) {
                assignedProfileIndex = objectProfile;
            }
        }
        if (!assignedProfileIndex.has_value() &&
            !instance.profileName.empty()) {
            const auto namedProfile = FindWaterShorelineProfileIndex(
                *water,
                instance.profileName);
            if (namedProfile.has_value()) {
                const auto& candidate =
                    water->shorelineProfiles[namedProfile.value()];
                if (!candidate.objectOverride ||
                    candidate.shorelineInstanceId == instance.id) {
                    assignedProfileIndex = namedProfile;
                }
            }
        }
        if (!assignedProfileIndex.has_value()) {
            const auto profileName = UniqueWaterShorelineProfileName(
                *water,
                instance.name + " Profile");
            water->shorelineProfiles.push_back({
                .name = profileName,
                .settings = instance.settings,
            });
            instance.profileName = profileName;
            instance.baseProfileName = profileName;
        } else {
            const auto& profile =
                water->shorelineProfiles[assignedProfileIndex.value()];
            instance.settings = profile.settings;
            if (instance.baseProfileName.empty()) {
                instance.baseProfileName =
                    profile.objectOverride
                        ? NormalizeWaterShorelineProfileName(
                              profile.baseProfileName)
                        : instance.profileName;
            }
        }
    }
    if (water->shorelineInstances.size() >
        invisible_places::renderer::pointcloud::
            kMaxShorelineInstances) {
        water->shorelineInstances.resize(
            invisible_places::renderer::pointcloud::
                kMaxShorelineInstances);
    }
    water->nextShorelineInstanceId = std::max(
        water->nextShorelineInstanceId,
        NextAvailableShorelineInstanceId(
            water->shorelineInstances));
    water->selectedShorelineProfileName.clear();
}

void ClearWaterShorelineFromSavedVisuals(
    PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    for (auto& visual :
         runtimeState->pointVisualLibrary.pointVisuals) {
        ClearPointCloudStyleShoreline(&visual.style);
    }
    for (auto& state :
         runtimeState->pointVisualLibrary.sceneVisualStates) {
        ClearPointCloudStyleShoreline(&state.visual.style);
    }
    for (auto& session : runtimeState->sessions) {
        ClearPointCloudStyleShoreline(&session.pointStyle);
        for (auto& visual : session.pointVisuals) {
            ClearPointCloudStyleShoreline(&visual.style);
        }
    }
}

template <typename ProfileState>
invisible_places::water::WaterObjectProfileEditDescriptor
DescribeWaterObjectProfileEditIn(
    const std::vector<ProfileState>& profiles,
    std::string_view assignedProfileName,
    std::uint32_t selectedOwnerObjectId) {
    const auto normalizedAssigned = [&]() {
        const auto trimmed = TrimText(assignedProfileName);
        return trimmed.empty() ? std::string{"Default"} : trimmed;
    }();
    const auto copy = std::find_if(
        profiles.begin(),
        profiles.end(),
        [&](const ProfileState& profile) {
            return profile.objectOverride &&
                   TrimText(profile.name) == normalizedAssigned;
        });
    std::optional<invisible_places::water::WaterObjectProfileIdentity>
        identity;
    if (copy != profiles.end()) {
        identity = {
            .name = copy->name,
            .ownerObjectId = copy->ownerObjectId,
            .baseProfileName = copy->baseProfileName,
        };
    }
    return invisible_places::water::DescribeWaterObjectProfileEdit(
        normalizedAssigned,
        selectedOwnerObjectId,
        identity);
}

template <typename ProfileState>
invisible_places::water::WaterObjectProfileEditDescriptor
DescribeWaterSeepageProfileEdit(
    const std::vector<ProfileState>& profiles,
    std::string_view assignedProfileName,
    std::uint32_t selectedOwnerObjectId) {
    return DescribeWaterObjectProfileEditIn(
        profiles,
        assignedProfileName,
        selectedOwnerObjectId);
}

// Keeps all three profile name fields following the primary selection's
// metadata-aware saved base after any selection change.
void SyncWaterSeepageNameBuffersFromPrimary(WaterWorkflowState* water) {
    if (!water->selectedSeepageNodeIndex.has_value() ||
        water->selectedSeepageNodeIndex.value() >= water->seepageNodes.size()) {
        return;
    }
    const auto& node = water->seepageNodes[water->selectedSeepageNodeIndex.value()];
    const auto nodeSettings = DescribeWaterSeepageProfileEdit(
        water->seepageNodeSettingsProfiles,
        node.settingsProfileName,
        node.id);
    const auto look = DescribeWaterSeepageProfileEdit(
        water->seepageLookProfiles,
        node.lookProfileName,
        node.id);
    const auto response = DescribeWaterSeepageProfileEdit(
        water->seepageResponseProfiles,
        node.responseProfileName,
        node.id);
    water->seepageNodeSettingsNameBuffer =
        nodeSettings.suggestedSaveProfileName;
    water->seepageLookNameBuffer = look.suggestedSaveProfileName;
    water->seepageResponseNameBuffer =
        response.suggestedSaveProfileName;
}

std::string NormalizedWaterSeepageProfileName(std::string_view name) {
    const auto trimmed = TrimText(name);
    return trimmed.empty() ? std::string{"Default"} : trimmed;
}

std::optional<std::size_t> FindWaterSeepageLookProfileIndex(
    const WaterWorkflowState& water,
    std::string_view name) {
    const auto normalized = NormalizedWaterSeepageProfileName(name);
    for (std::size_t index = 0; index < water.seepageLookProfiles.size(); ++index) {
        if (NormalizedWaterSeepageProfileName(water.seepageLookProfiles[index].name) ==
            normalized) {
            return index;
        }
    }
    return std::nullopt;
}

std::optional<std::size_t> FindWaterSeepageNodeSettingsProfileIndex(
    const WaterWorkflowState& water,
    std::string_view name) {
    const auto normalized = NormalizedWaterSeepageProfileName(name);
    for (std::size_t index = 0;
         index < water.seepageNodeSettingsProfiles.size();
         ++index) {
        if (NormalizedWaterSeepageProfileName(
                water.seepageNodeSettingsProfiles[index].name) == normalized) {
            return index;
        }
    }
    return std::nullopt;
}

WaterSeepageNodeSettings WaterSeepageNodeSettingsByName(
    const WaterWorkflowState& water,
    std::string_view name) {
    const auto index = FindWaterSeepageNodeSettingsProfileIndex(water, name);
    return index.has_value()
               ? water.seepageNodeSettingsProfiles[index.value()].settings
               : water.defaultSeepageNodeSettings;
}

std::optional<std::size_t> FindWaterSeepageResponseProfileIndex(
    const WaterWorkflowState& water,
    std::string_view name) {
    const auto normalized = NormalizedWaterSeepageProfileName(name);
    for (std::size_t index = 0; index < water.seepageResponseProfiles.size(); ++index) {
        if (NormalizedWaterSeepageProfileName(water.seepageResponseProfiles[index].name) ==
            normalized) {
            return index;
        }
    }
    return std::nullopt;
}

WaterSeepageLookSettings ViewedWaterSeepageLook(
    const WaterWorkflowState& water,
    const WaterSeepageNode& node) {
    return invisible_places::water::ResolveWaterSeepageLook(
        node,
        water.seepageLookProfiles,
        water.seepageResponseProfiles,
        water.defaultSeepageLook);
}

// "_preset" entries are regenerated from code on load and never persisted.
std::vector<WaterSeepageLookProfile> WithoutPresetSeepageLookProfiles(
    const std::vector<WaterSeepageLookProfile>& profiles) {
    std::vector<WaterSeepageLookProfile> filtered;
    filtered.reserve(profiles.size());
    for (const auto& profile : profiles) {
        if (!invisible_places::app::point_visual::IsPresetName(profile.name)) {
            filtered.push_back(profile);
        }
    }
    return filtered;
}

std::vector<WaterSeepageNodeSettingsProfile>
WithoutPresetSeepageNodeSettingsProfiles(
    const std::vector<WaterSeepageNodeSettingsProfile>& profiles) {
    std::vector<WaterSeepageNodeSettingsProfile> filtered;
    filtered.reserve(profiles.size());
    for (const auto& profile : profiles) {
        if (!invisible_places::app::point_visual::IsPresetName(profile.name)) {
            filtered.push_back(profile);
        }
    }
    return filtered;
}

std::vector<invisible_places::water::WaterSeepageResponseProfile>
WithoutPresetSeepageResponseProfiles(
    const std::vector<invisible_places::water::WaterSeepageResponseProfile>& profiles) {
    std::vector<invisible_places::water::WaterSeepageResponseProfile> filtered;
    filtered.reserve(profiles.size());
    for (const auto& profile : profiles) {
        if (!invisible_places::app::point_visual::IsPresetName(profile.name)) {
            filtered.push_back(profile);
        }
    }
    return filtered;
}

// Seed the read-only "_preset" entries. They are regenerated from code on
// every load so stored copies are never trusted, and saves refuse to land on
// them.
void SeedWaterSeepageProfilePresets(WaterWorkflowState* water) {
    using invisible_places::water::WaterSeepageLookSettings;
    using invisible_places::water::WaterSeepageResponseProfile;
    const auto upsertLook = [&](std::string_view name, WaterSeepagePattern pattern) {
        WaterSeepageLookSettings settings =
            invisible_places::water::DefaultWaterSeepageLookSettings();
        settings.pattern = pattern;
        const auto existing = FindWaterSeepageLookProfileIndex(*water, name);
        if (existing.has_value()) {
            water->seepageLookProfiles[existing.value()].settings = settings;
        } else {
            water->seepageLookProfiles.push_back(
                {.name = std::string{name}, .settings = settings});
        }
    };
    upsertLook("Wet Rock_preset", WaterSeepagePattern::WetRockSheen);
    upsertLook("Chaotic Bloom_preset", WaterSeepagePattern::ChaoticBloom);
    upsertLook("Wetting Trickle_preset", WaterSeepagePattern::WettingTrickle);
    upsertLook("Contour Pulses_preset", WaterSeepagePattern::ContourPulses);

    const auto upsertResponse = [&](std::string_view name, float intensityScale) {
        WaterSeepageResponseProfile profile;
        profile.name = std::string{name};
        profile.response =
            invisible_places::water::DefaultWaterSeepageLookSettings().response;
        profile.blendMode =
            invisible_places::water::DefaultWaterSeepageLookSettings().blendMode;
        profile.response.intensity *= intensityScale;
        profile.response.emissionAdd *= intensityScale;
        profile.response.colouriseAmount = std::min(
            1.0F,
            profile.response.colouriseAmount * intensityScale);
        const auto existing = FindWaterSeepageResponseProfileIndex(*water, name);
        if (existing.has_value()) {
            water->seepageResponseProfiles[existing.value()] = profile;
        } else {
            water->seepageResponseProfiles.push_back(profile);
        }
    };
    upsertResponse("Subtle_preset", 0.5F);
    upsertResponse("Standard_preset", 1.0F);
    upsertResponse("Strong_preset", 1.8F);
}

// Project/source documents predating Node Settings profiles already carry
// every authored scalar on each node. Preserve that exact state by assigning
// the shared Default only when it matches, otherwise materialize one
// node-owned copy. New documents carry settings_profile_name and bypass this.
void MigrateLegacyWaterSeepageNodeSettings(WaterWorkflowState* water) {
    if (water == nullptr) {
        return;
    }
    for (auto& node : water->seepageNodes) {
        if (!TrimText(node.settingsProfileName).empty()) {
            continue;
        }
        const auto settings =
            invisible_places::water::ExtractWaterSeepageNodeSettings(node);
        if (settings == water->defaultSeepageNodeSettings) {
            node.settingsProfileName = "Default";
            continue;
        }
        const std::string displayName = TrimText(node.name).empty()
                                            ? "Seepage " +
                                                  std::to_string(node.id)
                                            : TrimText(node.name);
        const std::string preferredName = "Default_" + displayName;
        std::string profileName = preferredName;
        for (std::uint32_t suffix = 2U;
             FindWaterSeepageNodeSettingsProfileIndex(*water, profileName)
                 .has_value();
             ++suffix) {
            profileName = preferredName + " " + std::to_string(suffix);
        }
        water->seepageNodeSettingsProfiles.push_back({
            .name = profileName,
            .settings = settings,
            .objectOverride = true,
            .ownerObjectId = node.id,
            .baseProfileName = "Default",
        });
        node.settingsProfileName = profileName;
    }
}

// Older documents stored per-node look copies (lookOverride /
// tempLookOverride) and no response profiles. Materialize overrides as named
// profile pairs, derive response profiles from legacy look profiles, and
// point nodes at them so a migrated project renders exactly as it saved.
// `documentHadResponseProfiles` distinguishes pre-split documents (derive
// pairings) from current ones (leave the libraries alone).
void MigrateLegacyWaterSeepageLooks(
    WaterWorkflowState* water,
    bool documentHadResponseProfiles) {
    using invisible_places::water::WaterSeepageLookSettings;
    using invisible_places::water::WaterSeepageResponseProfile;
    const auto upsertPair = [&](std::string_view name,
                                const WaterSeepageLookSettings& settings) {
        const auto lookIndex = FindWaterSeepageLookProfileIndex(*water, name);
        if (lookIndex.has_value()) {
            water->seepageLookProfiles[lookIndex.value()].settings = settings;
        } else {
            water->seepageLookProfiles.push_back(
                {.name = std::string{name}, .settings = settings});
        }
        const WaterSeepageResponseProfile responseProfile{
            .name = std::string{name},
            .response = settings.response,
            .blendMode = settings.blendMode,
        };
        const auto responseIndex = FindWaterSeepageResponseProfileIndex(*water, name);
        if (responseIndex.has_value()) {
            water->seepageResponseProfiles[responseIndex.value()] = responseProfile;
        } else {
            water->seepageResponseProfiles.push_back(responseProfile);
        }
    };

    // Old saves could carry user profiles whose names collide with the
    // reserved "_preset" namespace; rename them (and their node references)
    // before seeding would clobber them and the save filter would drop them.
    for (auto& profile : water->seepageLookProfiles) {
        if (!invisible_places::app::point_visual::IsPresetName(profile.name)) {
            continue;
        }
        std::string renamed =
            invisible_places::app::point_visual::BaseName(profile.name) + " legacy";
        while (FindWaterSeepageLookProfileIndex(*water, renamed).has_value()) {
            renamed += " 2";
        }
        for (auto& node : water->seepageNodes) {
            if (NormalizedWaterSeepageProfileName(node.lookProfileName) ==
                NormalizedWaterSeepageProfileName(profile.name)) {
                node.lookProfileName = renamed;
            }
        }
        profile.name = renamed;
    }

    // Pre-split look profiles carried their response inline; give each a
    // same-named response profile so old name references keep their pairing.
    // Documents that already store response profiles are left untouched so
    // reloading never grows phantom entries.
    if (!documentHadResponseProfiles) {
        for (const auto& profile : water->seepageLookProfiles) {
            if (invisible_places::app::point_visual::IsPresetName(profile.name) ||
                invisible_places::app::point_visual::IsEditedName(profile.name) ||
                FindWaterSeepageResponseProfileIndex(*water, profile.name)
                    .has_value()) {
                continue;
            }
            water->seepageResponseProfiles.push_back({
                .name = profile.name,
                .response = profile.settings.response,
                .blendMode = profile.settings.blendMode,
            });
        }
    }

    for (auto& node : water->seepageNodes) {
        if (node.lookOverride.has_value()) {
            const auto name = invisible_places::water::WaterSeepageLocalLookName(
                node.lookProfileName,
                node.id);
            upsertPair(name, node.lookOverride.value());
            node.lookProfileName = name;
            node.responseProfileName = name;
        }
        if (node.tempLookOverride.has_value()) {
            // The name must stay node-unique: multiple legacy nodes could
            // share one profile name while carrying different unsaved edits.
            const auto editedName = invisible_places::app::point_visual::EditedName(
                invisible_places::water::WaterSeepageLocalLookName(
                    invisible_places::app::point_visual::BaseName(
                        node.lookProfileName),
                    node.id));
            upsertPair(editedName, node.tempLookOverride.value());
            node.lookProfileName = editedName;
            node.responseProfileName = editedName;
        }
        node.lookOverride.reset();
        node.tempLookOverride.reset();
        // Nodes from documents that predate response profiles pair with the
        // response derived from their look profile when one exists.
        if (TrimText(node.responseProfileName).empty()) {
            node.responseProfileName =
                FindWaterSeepageResponseProfileIndex(*water, node.lookProfileName)
                        .has_value()
                    ? node.lookProfileName
                    : std::string{"Default"};
        }
    }
}

bool HasPreviewableWaterEmitters(const WaterWorkflowState& water) {
    return std::any_of(
        water.emitters.begin(),
        water.emitters.end(),
        [](const WaterEmitter& emitter) { return emitter.status != WaterEmitterStatus::Disabled; });
}

AnimationPath* CurrentAnimationPath(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr || !runtimeState->animationPanel.currentPath.has_value()) {
        return nullptr;
    }
    auto& panel = runtimeState->animationPanel;
    if (panel.currentFilePath.empty()) {
        panel.currentPathUsesEdited = true;
        panel.dirty = true;
        return &panel.currentPath.value();
    }
    const auto registryIndex = FindAnimationRegistryIndex(
        panel,
        std::filesystem::path{panel.currentFilePath});
    return registryIndex.has_value()
               ? MutableRegistryAnimationPath(
                     runtimeState,
                     registryIndex.value())
               : &panel.currentPath.value();
}

const AnimationPath* CurrentAnimationPath(const PreviewRuntimeState& runtimeState) {
    return runtimeState.animationPanel.currentPath.has_value()
               ? &runtimeState.animationPanel.currentPath.value()
               : nullptr;
}

WaterEmitter* SelectedWaterEmitter(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr ||
        !runtimeState->water.selectedEmitterIndex.has_value() ||
        runtimeState->water.selectedEmitterIndex.value() >= runtimeState->water.emitters.size()) {
        return nullptr;
    }
    return &runtimeState->water.emitters[runtimeState->water.selectedEmitterIndex.value()];
}

const WaterEmitter* SelectedWaterEmitter(const PreviewRuntimeState& runtimeState) {
    if (!runtimeState.water.selectedEmitterIndex.has_value() ||
        runtimeState.water.selectedEmitterIndex.value() >= runtimeState.water.emitters.size()) {
        return nullptr;
    }
    return &runtimeState.water.emitters[runtimeState.water.selectedEmitterIndex.value()];
}

void MarkWaterPathDirty(PreviewRuntimeState* runtimeState, std::optional<std::uint32_t> emitterId = std::nullopt) {
    if (runtimeState == nullptr) {
        return;
    }
    runtimeState->water.pathDirty = true;
    runtimeState->water.pathCacheStale = true;
    runtimeState->water.selectedPathBranchId.reset();
    runtimeState->water.hoveredPathBranchId.reset();
    if (emitterId.has_value()) {
        runtimeState->water.dirtyEmitterIds.insert(emitterId.value());
    } else {
        runtimeState->water.dirtyEmitterIds.clear();
        for (const auto& emitter : runtimeState->water.emitters) {
            runtimeState->water.dirtyEmitterIds.insert(emitter.id);
        }
    }
}

void QueueWaterPreview(PreviewRuntimeState* runtimeState) {
    if (runtimeState != nullptr) {
        MarkWaterPathDirty(runtimeState);
        runtimeState->statusMessage = "Water path bake required.";
        runtimeState->errorMessage.clear();
    }
}

const WaterSourceSettings& ActiveDefaultWaterSourceSettings(const PreviewRuntimeState& runtimeState) {
    return runtimeState.water.tempDefaultSourceSettings.has_value()
               ? runtimeState.water.tempDefaultSourceSettings.value()
               : runtimeState.water.defaultSourceSettings;
}

std::string WaterCustomSettingsName(std::uint32_t emitterId, bool edited = false) {
    std::ostringstream label;
    label << "Custom " << std::setw(2) << std::setfill('0') << emitterId;
    if (edited) {
        label << "_edited";
    }
    return label.str();
}

const WaterEmitter* WaterEmitterById(
    const std::vector<WaterEmitter>& emitters,
    std::uint32_t emitterId) {
    const auto emitterIt = std::find_if(
        emitters.begin(),
        emitters.end(),
        [emitterId](const WaterEmitter& emitter) { return emitter.id == emitterId; });
    return emitterIt == emitters.end() ? nullptr : &*emitterIt;
}

bool WaterEmitterHasSavedCustomSettings(
    const std::vector<WaterEmitter>& emitters,
    std::uint32_t emitterId) {
    const auto* emitter = WaterEmitterById(emitters, emitterId);
    return emitter != nullptr && emitter->sourceSettings.has_value();
}

std::string WaterSourceSettingsAssignmentLabel(
    const WaterEmitter& emitter,
    const std::vector<WaterEmitter>& emitters) {
    if (emitter.tempSourceSettings.has_value()) {
        return WaterCustomSettingsName(emitter.id, true);
    }
    if (emitter.sourceSettingsAssignment == WaterSourceSettingsAssignment::Custom &&
        emitter.sourceSettings.has_value()) {
        return WaterCustomSettingsName(emitter.id);
    }
    if (emitter.sourceSettingsAssignment == WaterSourceSettingsAssignment::LinkedEmitter &&
        emitter.linkedSourceSettingsEmitterId.has_value() &&
        WaterEmitterHasSavedCustomSettings(emitters, emitter.linkedSourceSettingsEmitterId.value())) {
        return WaterCustomSettingsName(emitter.linkedSourceSettingsEmitterId.value());
    }
    return "Default";
}

bool ValidateWaterSourceSettingLinks(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return false;
    }
    bool changed = false;
    for (auto& emitter : runtimeState->water.emitters) {
        if (emitter.sourceSettingsAssignment != WaterSourceSettingsAssignment::LinkedEmitter) {
            emitter.linkedSourceSettingsEmitterId.reset();
            continue;
        }
        const bool validLink =
            emitter.linkedSourceSettingsEmitterId.has_value() &&
            emitter.linkedSourceSettingsEmitterId.value() != emitter.id &&
            WaterEmitterHasSavedCustomSettings(
                runtimeState->water.emitters,
                emitter.linkedSourceSettingsEmitterId.value());
        if (!validLink) {
            emitter.sourceSettingsAssignment = WaterSourceSettingsAssignment::Default;
            emitter.linkedSourceSettingsEmitterId.reset();
            emitter.tempSourceSettings.reset();
            changed = true;
        }
    }
    if (changed) {
        MarkWaterPathDirty(runtimeState);
        runtimeState->statusMessage = "Some linked water source settings were missing and fell back to Default.";
        runtimeState->errorMessage.clear();
    }
    return changed;
}

const WaterSourceSettings& ViewedWaterSourceSettings(const PreviewRuntimeState& runtimeState) {
    if (const auto* selectedEmitter = SelectedWaterEmitter(runtimeState); selectedEmitter != nullptr) {
        return invisible_places::water::ResolveWaterSourceSettings(
            *selectedEmitter,
            runtimeState.water.emitters,
            ActiveDefaultWaterSourceSettings(runtimeState));
    }
    return ActiveDefaultWaterSourceSettings(runtimeState);
}

bool WaterSourceRefreshInputsEqual(
    const WaterSourceSettings& left,
    const WaterSourceSettings& right) {
    return left.path.smoothing == right.path.smoothing &&
           left.trailShape.particleJitter == right.trailShape.particleJitter &&
           left.trailShape.splineAnchorSpacing == right.trailShape.splineAnchorSpacing &&
           left.trailShape.trailLaneCount == right.trailShape.trailLaneCount &&
           left.trailShape.trailLooseness == right.trailShape.trailLooseness &&
           left.trailShape.trailSmoothness == right.trailShape.trailSmoothness;
}

void ApplyWaterSourceSettingsTransition(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const WaterSourceSettings& before,
    const WaterSourceSettings& after,
    std::optional<std::uint32_t> emitterId = std::nullopt) {
    if (runtimeState == nullptr) {
        return;
    }
    if (!invisible_places::water::WaterSourceBakeInputsEqual(before, after)) {
        MarkWaterPathDirty(runtimeState, emitterId);
        return;
    }
    if (!WaterSourceRefreshInputsEqual(before, after) && viewport != nullptr) {
        if (runtimeState->water.pathCacheLoaded &&
            !runtimeState->water.pathCache.branches.empty()) {
            runtimeState->water.pathAnchors =
                WaterPathAnchorsFromCacheWithProfileSettings(*runtimeState);
        }
        QueueWaterFlowTrailRefresh(
            runtimeState,
            WaterOverlayRefreshPersistence::InMemoryOnly,
            std::chrono::milliseconds{0},
            emitterId);
    }
}

WaterSourceSettings* EnsureEditableWaterSourceSettings(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return nullptr;
    }
    if (auto* emitter = SelectedWaterEmitter(runtimeState); emitter != nullptr) {
        if (!emitter->tempSourceSettings.has_value()) {
            emitter->tempSourceSettings = ViewedWaterSourceSettings(*runtimeState);
        }
        emitter->sourceSettingsAssignment = WaterSourceSettingsAssignment::Custom;
        emitter->linkedSourceSettingsEmitterId.reset();
        return &emitter->tempSourceSettings.value();
    }
    if (!runtimeState->water.tempDefaultSourceSettings.has_value()) {
        runtimeState->water.tempDefaultSourceSettings = ViewedWaterSourceSettings(*runtimeState);
    }
    return &runtimeState->water.tempDefaultSourceSettings.value();
}

void SaveEditableWaterSourceSettings(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr) {
        return;
    }
    if (auto* emitter = SelectedWaterEmitter(runtimeState); emitter != nullptr) {
        if (!emitter->tempSourceSettings.has_value()) {
            runtimeState->statusMessage = "No source temp water settings to save.";
            runtimeState->errorMessage.clear();
            return;
        }
        const auto before = invisible_places::water::ResolveWaterSourceSettings(
            *emitter,
            runtimeState->water.emitters,
            ActiveDefaultWaterSourceSettings(*runtimeState));
        emitter->sourceSettings = emitter->tempSourceSettings.value();
        emitter->tempSourceSettings.reset();
        emitter->sourceSettingsAssignment = WaterSourceSettingsAssignment::Custom;
        emitter->linkedSourceSettingsEmitterId.reset();
        const auto after = invisible_places::water::ResolveWaterSourceSettings(
            *emitter,
            runtimeState->water.emitters,
            ActiveDefaultWaterSourceSettings(*runtimeState));
        ApplyWaterSourceSettingsTransition(runtimeState, viewport, before, after, emitter->id);
        runtimeState->statusMessage =
            "Saved water source settings as " + WaterCustomSettingsName(emitter->id) + ".";
        runtimeState->errorMessage.clear();
        return;
    }
    if (!runtimeState->water.tempDefaultSourceSettings.has_value()) {
        runtimeState->statusMessage = "No default source temp settings to save.";
        runtimeState->errorMessage.clear();
        return;
    }
    const auto before = ActiveDefaultWaterSourceSettings(*runtimeState);
    runtimeState->water.defaultSourceSettings = runtimeState->water.tempDefaultSourceSettings.value();
    runtimeState->water.tempDefaultSourceSettings.reset();
    const auto after = ActiveDefaultWaterSourceSettings(*runtimeState);
    ApplyWaterSourceSettingsTransition(runtimeState, viewport, before, after);
    runtimeState->statusMessage = "Saved edited water source defaults.";
    runtimeState->errorMessage.clear();
}

void DiscardEditableWaterSourceSettings(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr) {
        return;
    }
    if (auto* emitter = SelectedWaterEmitter(runtimeState); emitter != nullptr) {
        const auto before = invisible_places::water::ResolveWaterSourceSettings(
            *emitter,
            runtimeState->water.emitters,
            ActiveDefaultWaterSourceSettings(*runtimeState));
        emitter->tempSourceSettings.reset();
        emitter->linkedSourceSettingsEmitterId.reset();
        emitter->sourceSettingsAssignment = emitter->sourceSettings.has_value()
                                                ? WaterSourceSettingsAssignment::Custom
                                                : WaterSourceSettingsAssignment::Default;
        const auto after = invisible_places::water::ResolveWaterSourceSettings(
            *emitter,
            runtimeState->water.emitters,
            ActiveDefaultWaterSourceSettings(*runtimeState));
        ApplyWaterSourceSettingsTransition(runtimeState, viewport, before, after, emitter->id);
        runtimeState->statusMessage = "Discarded edited water source settings.";
        runtimeState->errorMessage.clear();
        return;
    }
    const auto before = ActiveDefaultWaterSourceSettings(*runtimeState);
    runtimeState->water.tempDefaultSourceSettings.reset();
    const auto after = ActiveDefaultWaterSourceSettings(*runtimeState);
    ApplyWaterSourceSettingsTransition(runtimeState, viewport, before, after);
    runtimeState->statusMessage = "Discarded edited water source defaults.";
    runtimeState->errorMessage.clear();
}

enum class WaterTrailPlaybackQuickPreset {
    FineWhiteThreads,
    LongWhiteVeil,
    SoftDistantDrift
};

constexpr std::string_view kDefaultWaterTrailProfileName = "Default";
constexpr std::string_view kAnimationWaterTrailProfileName = "Animation";

const char* WaterTrailPlaybackQuickPresetName(WaterTrailPlaybackQuickPreset preset) {
    switch (preset) {
        case WaterTrailPlaybackQuickPreset::FineWhiteThreads:
            return "Fine White Threads";
        case WaterTrailPlaybackQuickPreset::LongWhiteVeil:
            return "Long White Veil";
        case WaterTrailPlaybackQuickPreset::SoftDistantDrift:
            return "Soft Distant Drift";
    }
    return "Water Trail";
}

WaterAnimationTrailSettings MakeWaterTrailPlaybackQuickPreset(WaterTrailPlaybackQuickPreset preset) {
    WaterAnimationTrailSettings settings = invisible_places::water::DefaultWaterAnimationTrailSettings();
    switch (preset) {
        case WaterTrailPlaybackQuickPreset::FineWhiteThreads:
            settings.particleDensity = 2.4F;
            settings.particleSpeed = 1.15F;
            settings.colorVariation = 0.18F;
            settings.trailLengthMeters = 0.95F;
            settings.trailSampleSpacingMeters = 0.018F;
            break;
        case WaterTrailPlaybackQuickPreset::LongWhiteVeil:
            settings.particleDensity = 1.25F;
            settings.particleSpeed = 0.82F;
            settings.colorVariation = 0.12F;
            settings.trailLengthMeters = 2.20F;
            settings.trailSampleSpacingMeters = 0.035F;
            break;
        case WaterTrailPlaybackQuickPreset::SoftDistantDrift:
            settings.particleDensity = 0.58F;
            settings.particleSpeed = 0.48F;
            settings.colorVariation = 0.28F;
            settings.trailLengthMeters = 3.80F;
            settings.trailSampleSpacingMeters = 0.085F;
            break;
    }
    return settings;
}

std::string NormalizeWaterAnimationTrailProfileName(std::string_view name) {
    const auto trimmed = TrimText(name);
    return trimmed.empty() ? std::string{kDefaultWaterTrailProfileName} : trimmed;
}

bool IsEditedWaterAnimationTrailProfileName(std::string_view name) {
    return EndsWith(name, kEditedPointVisualSuffix);
}

std::string BaseWaterAnimationTrailProfileName(std::string_view name) {
    if (!IsEditedWaterAnimationTrailProfileName(name)) {
        return NormalizeWaterAnimationTrailProfileName(name);
    }
    return NormalizeWaterAnimationTrailProfileName(name.substr(0, name.size() - kEditedPointVisualSuffix.size()));
}

std::string EditedWaterAnimationTrailProfileName(std::string_view baseName) {
    return BaseWaterAnimationTrailProfileName(baseName) + std::string{kEditedPointVisualSuffix};
}

bool IsProtectedWaterAnimationTrailProfileName(std::string_view name) {
    const auto normalized = NormalizeWaterAnimationTrailProfileName(name);
    return normalized == kDefaultWaterTrailProfileName ||
           normalized == WaterTrailPlaybackQuickPresetName(WaterTrailPlaybackQuickPreset::FineWhiteThreads) ||
           normalized == WaterTrailPlaybackQuickPresetName(WaterTrailPlaybackQuickPreset::LongWhiteVeil) ||
           normalized == WaterTrailPlaybackQuickPresetName(WaterTrailPlaybackQuickPreset::SoftDistantDrift);
}

std::optional<WaterAnimationTrailSettings> BuiltInWaterAnimationTrailProfileSettings(
    const PreviewRuntimeState& runtimeState,
    std::string_view name) {
    const auto normalized = NormalizeWaterAnimationTrailProfileName(name);
    if (normalized == kDefaultWaterTrailProfileName) {
        return runtimeState.water.defaultAnimationTrailSettings;
    }
    if (normalized == WaterTrailPlaybackQuickPresetName(WaterTrailPlaybackQuickPreset::FineWhiteThreads)) {
        return MakeWaterTrailPlaybackQuickPreset(WaterTrailPlaybackQuickPreset::FineWhiteThreads);
    }
    if (normalized == WaterTrailPlaybackQuickPresetName(WaterTrailPlaybackQuickPreset::LongWhiteVeil)) {
        return MakeWaterTrailPlaybackQuickPreset(WaterTrailPlaybackQuickPreset::LongWhiteVeil);
    }
    if (normalized == WaterTrailPlaybackQuickPresetName(WaterTrailPlaybackQuickPreset::SoftDistantDrift)) {
        return MakeWaterTrailPlaybackQuickPreset(WaterTrailPlaybackQuickPreset::SoftDistantDrift);
    }
    return std::nullopt;
}

std::optional<std::size_t> FindWaterAnimationTrailProfileIndex(
    const WaterWorkflowState& water,
    std::string_view name) {
    const auto normalized = NormalizeWaterAnimationTrailProfileName(name);
    for (std::size_t index = 0; index < water.animationTrailProfiles.size(); ++index) {
        if (NormalizeWaterAnimationTrailProfileName(water.animationTrailProfiles[index].name) == normalized) {
            return index;
        }
    }
    return std::nullopt;
}

std::optional<WaterAnimationTrailSettings> CustomWaterAnimationTrailProfileSettings(
    const WaterWorkflowState& water,
    std::string_view name) {
    const auto index = FindWaterAnimationTrailProfileIndex(water, name);
    return index.has_value() ? std::optional<WaterAnimationTrailSettings>{water.animationTrailProfiles[index.value()].settings}
                             : std::nullopt;
}

void UpsertWaterAnimationTrailProfile(
    WaterWorkflowState* water,
    std::string_view name,
    const WaterAnimationTrailSettings& settings) {
    if (water == nullptr) {
        return;
    }
    const auto normalized = NormalizeWaterAnimationTrailProfileName(name);
    if (const auto index = FindWaterAnimationTrailProfileIndex(*water, normalized); index.has_value()) {
        water->animationTrailProfiles[index.value()].name = normalized;
        water->animationTrailProfiles[index.value()].settings = settings;
        return;
    }
    water->animationTrailProfiles.push_back({.name = normalized, .settings = settings});
}

void EnsureWaterAnimationTrailProfiles(WaterWorkflowState* water) {
    if (water == nullptr) {
        return;
    }

    std::vector<SavedWaterAnimationTrailProfileState> profiles;
    profiles.reserve(water->animationTrailProfiles.size());
    for (const auto& profile : water->animationTrailProfiles) {
        const auto normalized = NormalizeWaterAnimationTrailProfileName(profile.name);
        const auto duplicate = std::any_of(
            profiles.begin(),
            profiles.end(),
            [&normalized](const SavedWaterAnimationTrailProfileState& existing) {
                return NormalizeWaterAnimationTrailProfileName(existing.name) == normalized;
            });
        if (IsProtectedWaterAnimationTrailProfileName(normalized) ||
            IsEditedWaterAnimationTrailProfileName(normalized) ||
            duplicate) {
            continue;
        }
        profiles.push_back({.name = normalized, .settings = profile.settings});
    }
    water->animationTrailProfiles = std::move(profiles);
    water->selectedAnimationTrailProfileName =
        NormalizeWaterAnimationTrailProfileName(water->selectedAnimationTrailProfileName);
    if (water->animationTrailProfileNameBuffer.empty()) {
        water->animationTrailProfileNameBuffer =
            BaseWaterAnimationTrailProfileName(water->selectedAnimationTrailProfileName);
    }
}

std::optional<WaterAnimationTrailSettings> WaterAnimationTrailProfileSettingsByName(
    const PreviewRuntimeState& runtimeState,
    std::string_view name) {
    const auto normalized = NormalizeWaterAnimationTrailProfileName(name);
    if (runtimeState.water.editedAnimationTrailProfileSettings.has_value() &&
        normalized == runtimeState.water.selectedAnimationTrailProfileName) {
        return runtimeState.water.editedAnimationTrailProfileSettings.value();
    }
    if (const auto builtIn = BuiltInWaterAnimationTrailProfileSettings(runtimeState, normalized); builtIn.has_value()) {
        return builtIn.value();
    }
    return CustomWaterAnimationTrailProfileSettings(runtimeState.water, normalized);
}

bool WaterAnimationTrailSettingsApproximatelyEqual(
    const WaterAnimationTrailSettings& left,
    const WaterAnimationTrailSettings& right) {
    constexpr float epsilon = 1.0e-4F;
    return std::abs(left.particleDensity - right.particleDensity) <= epsilon &&
           std::abs(left.particleSpeed - right.particleSpeed) <= epsilon &&
           std::abs(left.colorVariation - right.colorVariation) <= epsilon &&
           std::abs(left.trailLengthMeters - right.trailLengthMeters) <= epsilon &&
           std::abs(left.trailSampleSpacingMeters - right.trailSampleSpacingMeters) <= epsilon;
}

std::optional<std::string> FindWaterAnimationTrailProfileNameForSettings(
    const PreviewRuntimeState& runtimeState,
    const WaterAnimationTrailSettings& settings) {
    constexpr WaterTrailPlaybackQuickPreset presets[] = {
        WaterTrailPlaybackQuickPreset::FineWhiteThreads,
        WaterTrailPlaybackQuickPreset::LongWhiteVeil,
        WaterTrailPlaybackQuickPreset::SoftDistantDrift,
    };
    if (WaterAnimationTrailSettingsApproximatelyEqual(
            runtimeState.water.defaultAnimationTrailSettings,
            settings)) {
        return std::string{kDefaultWaterTrailProfileName};
    }
    for (const auto preset : presets) {
        const auto presetSettings = MakeWaterTrailPlaybackQuickPreset(preset);
        if (WaterAnimationTrailSettingsApproximatelyEqual(presetSettings, settings)) {
            return std::string{WaterTrailPlaybackQuickPresetName(preset)};
        }
    }
    for (const auto& profile : runtimeState.water.animationTrailProfiles) {
        if (WaterAnimationTrailSettingsApproximatelyEqual(profile.settings, settings)) {
            return NormalizeWaterAnimationTrailProfileName(profile.name);
        }
    }
    return std::nullopt;
}

const WaterAnimationTrailSettings& ViewedWaterAnimationTrailSettings(const PreviewRuntimeState& runtimeState) {
    if (runtimeState.water.editedAnimationTrailProfileSettings.has_value()) {
        return runtimeState.water.editedAnimationTrailProfileSettings.value();
    }
    if (const auto profileSettings =
            WaterAnimationTrailProfileSettingsByName(runtimeState, runtimeState.water.selectedAnimationTrailProfileName);
        profileSettings.has_value()) {
        static thread_local WaterAnimationTrailSettings cachedSettings;
        cachedSettings = profileSettings.value();
        return cachedSettings;
    }
    if (const auto* animationPath = CurrentAnimationPath(runtimeState); animationPath != nullptr) {
        if (animationPath->tempWaterAnimationTrailSettings.has_value()) {
            return animationPath->tempWaterAnimationTrailSettings.value();
        }
        if (animationPath->waterAnimationTrailSettings.has_value()) {
            return animationPath->waterAnimationTrailSettings.value();
        }
    }
    if (runtimeState.water.tempDefaultAnimationTrailSettings.has_value()) {
        return runtimeState.water.tempDefaultAnimationTrailSettings.value();
    }
    return runtimeState.water.defaultAnimationTrailSettings;
}

void SelectWaterAnimationTrailProfile(PreviewRuntimeState* runtimeState, std::string_view name) {
    if (runtimeState == nullptr) {
        return;
    }
    const auto normalized = NormalizeWaterAnimationTrailProfileName(name);
    runtimeState->water.selectedAnimationTrailProfileName = normalized;
    runtimeState->water.animationTrailProfileNameBuffer = BaseWaterAnimationTrailProfileName(normalized);
    runtimeState->water.editedAnimationTrailProfileSettings.reset();
    if (auto* animationPath = CurrentAnimationPath(runtimeState); animationPath != nullptr) {
        animationPath->tempWaterAnimationTrailSettings.reset();
        runtimeState->animationPanel.dirty = true;
    }
    runtimeState->statusMessage = "Selected water trail profile " + normalized + ".";
    runtimeState->errorMessage.clear();
}

WaterAnimationTrailSettings* EnsureEditableWaterAnimationTrailSettings(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return nullptr;
    }
    if (!runtimeState->water.editedAnimationTrailProfileSettings.has_value()) {
        runtimeState->water.editedAnimationTrailProfileSettings = ViewedWaterAnimationTrailSettings(*runtimeState);
        runtimeState->water.selectedAnimationTrailProfileName =
            EditedWaterAnimationTrailProfileName(runtimeState->water.selectedAnimationTrailProfileName);
        runtimeState->water.animationTrailProfileNameBuffer =
            BaseWaterAnimationTrailProfileName(runtimeState->water.selectedAnimationTrailProfileName);
    }
    if (auto* animationPath = CurrentAnimationPath(runtimeState); animationPath != nullptr) {
        animationPath->tempWaterAnimationTrailSettings = runtimeState->water.editedAnimationTrailProfileSettings.value();
        runtimeState->animationPanel.dirty = true;
    } else {
        runtimeState->water.tempDefaultAnimationTrailSettings =
            runtimeState->water.editedAnimationTrailProfileSettings.value();
    }
    return &runtimeState->water.editedAnimationTrailProfileSettings.value();
}

void SaveCurrentWaterAnimationTrailProfile(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    const auto targetName = NormalizeWaterAnimationTrailProfileName(
        runtimeState->water.animationTrailProfileNameBuffer.empty()
            ? BaseWaterAnimationTrailProfileName(runtimeState->water.selectedAnimationTrailProfileName)
            : runtimeState->water.animationTrailProfileNameBuffer);
    if (IsProtectedWaterAnimationTrailProfileName(targetName) ||
        IsEditedWaterAnimationTrailProfileName(targetName)) {
        runtimeState->errorMessage =
            "Choose a new custom trail profile name; built-in and edited names cannot be overwritten.";
        runtimeState->statusMessage.clear();
        return;
    }

    const auto settings = ViewedWaterAnimationTrailSettings(*runtimeState);
    UpsertWaterAnimationTrailProfile(&runtimeState->water, targetName, settings);
    runtimeState->water.selectedAnimationTrailProfileName = targetName;
    runtimeState->water.animationTrailProfileNameBuffer = targetName;
    runtimeState->water.editedAnimationTrailProfileSettings.reset();
    runtimeState->water.tempDefaultAnimationTrailSettings.reset();
    if (auto* animationPath = CurrentAnimationPath(runtimeState); animationPath != nullptr) {
        animationPath->waterAnimationTrailSettings = settings;
        animationPath->tempWaterAnimationTrailSettings.reset();
        runtimeState->animationPanel.dirty = true;
    }
    runtimeState->statusMessage = "Saved water trail profile " + targetName + ".";
    runtimeState->errorMessage.clear();
}

void DiscardEditableWaterAnimationTrailSettings(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    if (!runtimeState->water.editedAnimationTrailProfileSettings.has_value()) {
        runtimeState->statusMessage = "No edited water trail profile to discard.";
        runtimeState->errorMessage.clear();
        return;
    }
    runtimeState->water.selectedAnimationTrailProfileName =
        BaseWaterAnimationTrailProfileName(runtimeState->water.selectedAnimationTrailProfileName);
    runtimeState->water.animationTrailProfileNameBuffer =
        runtimeState->water.selectedAnimationTrailProfileName;
    runtimeState->water.editedAnimationTrailProfileSettings.reset();
    runtimeState->water.tempDefaultAnimationTrailSettings.reset();
    if (auto* animationPath = CurrentAnimationPath(runtimeState); animationPath != nullptr) {
        animationPath->tempWaterAnimationTrailSettings.reset();
        runtimeState->animationPanel.dirty = true;
    }
    runtimeState->statusMessage = "Discarded edited water trail profile.";
    runtimeState->errorMessage.clear();
}

void SyncWaterAnimationTrailProfileFromCurrentAnimation(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    EnsureWaterAnimationTrailProfiles(&runtimeState->water);
    const auto* animationPath = CurrentAnimationPath(*runtimeState);
    if (animationPath == nullptr) {
        if (runtimeState->water.tempDefaultAnimationTrailSettings.has_value()) {
            runtimeState->water.editedAnimationTrailProfileSettings =
                runtimeState->water.tempDefaultAnimationTrailSettings.value();
            runtimeState->water.selectedAnimationTrailProfileName =
                EditedWaterAnimationTrailProfileName(kDefaultWaterTrailProfileName);
        } else {
            runtimeState->water.editedAnimationTrailProfileSettings.reset();
            runtimeState->water.selectedAnimationTrailProfileName = std::string{kDefaultWaterTrailProfileName};
        }
        runtimeState->water.animationTrailProfileNameBuffer =
            BaseWaterAnimationTrailProfileName(runtimeState->water.selectedAnimationTrailProfileName);
        return;
    }

    const auto settings = animationPath->tempWaterAnimationTrailSettings
                              .value_or(animationPath->waterAnimationTrailSettings
                                            .value_or(runtimeState->water.defaultAnimationTrailSettings));
    if (const auto match = FindWaterAnimationTrailProfileNameForSettings(*runtimeState, settings);
        match.has_value()) {
        runtimeState->water.selectedAnimationTrailProfileName = match.value();
        runtimeState->water.editedAnimationTrailProfileSettings.reset();
    } else {
        runtimeState->water.selectedAnimationTrailProfileName =
            EditedWaterAnimationTrailProfileName(kAnimationWaterTrailProfileName);
        runtimeState->water.editedAnimationTrailProfileSettings = settings;
    }
    runtimeState->water.animationTrailProfileNameBuffer =
        BaseWaterAnimationTrailProfileName(runtimeState->water.selectedAnimationTrailProfileName);
}

PointCloudStyleState ViewedWaterPointVisualStyle(const PreviewRuntimeState& runtimeState) {
    const auto selectedName = NormalizePointVisualName(runtimeState.water.selectedPointVisualName);
    if (const auto protectedStyle = MakeProtectedWaterPointVisualStyle(runtimeState, selectedName);
        protectedStyle.has_value()) {
        return MakeWaterTrailExportStyle(protectedStyle.value());
    }

    if (const auto customIndex = FindWaterProjectVisualIndex(runtimeState.water.pointVisuals, selectedName);
        customIndex.has_value()) {
        return MakeWaterTrailExportStyle(runtimeState.water.pointVisuals[customIndex.value()].style);
    }

    if (runtimeState.water.tempDefaultPointVisualStyle.has_value()) {
        return MakeWaterTrailExportStyle(runtimeState.water.tempDefaultPointVisualStyle.value());
    }
    return MakeWaterTrailExportStyle(runtimeState.water.defaultPointVisualStyle);
}

PointCloudStyleState MakeWaterTrailExportStyle(PointCloudStyleState style) {
    style.flowAnimation = true;
    style.waterPathView = false;
    style.waterTrailOverlay = true;
    style.geometryMode = PointCloudGeometryMode::CameraFacingWorldSprites;
    style.stylisationMode = PointCloudStylisationMode::Off;
    style.roughnessMotionStrength = 0.0F;
    style.depthFade.active = false;
    return style;
}

PointCloudStyleState MakeWaterTrailSessionStyle(
    PointCloudStyleState style,
    const WaterTrailGeometrySettings& geometry) {
    style = MakeWaterTrailExportStyle(style);
    const float width = std::max(0.0005F, geometry.widthMeters);
    const float streakLength = std::max(width, geometry.streakLengthMeters);
    invisible_places::style::SetScalarConstant(&style.surfelDiameter, width);
    invisible_places::style::SetScalarConstant(&style.pointSize, width * 1000.0F);
    style.waterStreakAspect = std::clamp(streakLength / width, 1.0F, 32.0F);
    style.waterTrailStyleGeometry = true;
    return style;
}

void SaveWaterPointVisualStyle(PreviewRuntimeState* runtimeState, const PointCloudStyleState& style) {
    if (runtimeState == nullptr) {
        return;
    }
    auto savedStyle = MakeWaterTrailExportStyle(style);
    std::string targetName = NormalizePointVisualName(runtimeState->water.selectedPointVisualName);
    if (targetName.empty() || IsPresetPointVisualName(targetName) || IsEditedPointVisualName(targetName)) {
        targetName = BasePointVisualName(targetName.empty() ? "Water Flow_preset" : targetName);
    }
    UpsertWaterProjectVisual(runtimeState, targetName, savedStyle);
    runtimeState->water.tempDefaultPointVisualStyle.reset();
    ApplyWaterPointVisualStyleToGeneratedSessions(runtimeState);
}

void ApplyWaterPointVisualStyleToGeneratedSessions(PreviewRuntimeState* runtimeState);

void UnloadCurrentAnimationForWaterEditing(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    SyncCurrentAnimationToRegistry(runtimeState);
    runtimeState->animationPlayback.active = false;
    runtimeState->cameraPlayback.active = false;
    runtimeState->animationPanel.currentPath.reset();
    runtimeState->animationPanel.currentFilePath.clear();
    runtimeState->animationPanel.currentPathUsesEdited = false;
    runtimeState->animationPanel.selectedFileUsesEdited = false;
    runtimeState->animationPanel.draftAnimationName.clear();
    runtimeState->animationPanel.selectedKeyIndex.reset();
    runtimeState->animationPanel.scrubAmount = 0.0F;
    runtimeState->animationPanel.timelineViewRange = {};
    runtimeState->animationPanel.timelineViewDrag.reset();
    runtimeState->animationPanel.dirty = false;
    runtimeState->animationPanel.requestedMatchingFrameGhostCapture.reset();
    runtimeState->animationPanel.requestedMatchingFrameGhostClear =
        runtimeState->animationPanel.matchingFrameGhost.uploaded;
    runtimeState->animationPanel.matchingFrameGhost.visible = false;
    SyncWaterAnimationTrailProfileFromCurrentAnimation(runtimeState);
    runtimeState->water.pathAnchors = {};
    runtimeState->water.pathDirty = true;
    ApplyWaterPointVisualStyleToGeneratedSessions(runtimeState);
    runtimeState->statusMessage = "Unloaded animation; editing project water defaults.";
    runtimeState->errorMessage.clear();
}

std::optional<std::size_t> ResolveWaterSupportSessionIndex(const PreviewRuntimeState& runtimeState) {
    const auto canonicalSupportIndex = [&](std::size_t index) -> std::optional<std::size_t> {
        if (index >= runtimeState.sessions.size()) {
            return std::nullopt;
        }
        const auto& session = runtimeState.sessions[index];
        if (!IsSceneGroupedPointCloud(session)) {
            return IsVisibleLoadedWaterSupportSession(session)
                       ? std::optional<std::size_t>{index}
                       : std::nullopt;
        }
        const auto* scene = FindScenePointCloudRuntime(runtimeState, session);
        if (scene == nullptr || !SceneAnalysisSourcesReady(runtimeState, *scene)) {
            return std::nullopt;
        }
        const auto rockIndex = scene->analysisSessionIndices[
            invisible_places::scene::ScenePointCloudRoleIndex(
                invisible_places::scene::ScenePointCloudRole::Rock)];
        return rockIndex.has_value() &&
                       IsVisibleLoadedWaterSupportSession(runtimeState.sessions[rockIndex.value()])
                   ? rockIndex
                   : std::nullopt;
    };

    if (runtimeState.selectedSessionIndex.has_value()) {
        const auto selectedIndex = runtimeState.selectedSessionIndex.value();
        if (selectedIndex < runtimeState.sessions.size() &&
            IsSceneGroupedPointCloud(runtimeState.sessions[selectedIndex])) {
            // A selected scene owns the analysis context. Never fall through to
            // another scene merely because this scene is still loading.
            return canonicalSupportIndex(selectedIndex);
        }
        const auto resolved = canonicalSupportIndex(runtimeState.selectedSessionIndex.value());
        if (resolved.has_value()) {
            return resolved;
        }
    }

    if (runtimeState.water.activeSupportSessionIndex.has_value()) {
        const auto resolved = canonicalSupportIndex(runtimeState.water.activeSupportSessionIndex.value());
        if (resolved.has_value()) {
            return resolved;
        }
    }

    for (std::size_t index = 0; index < runtimeState.sessions.size(); ++index) {
        const auto resolved = canonicalSupportIndex(index);
        if (resolved.has_value()) {
            return resolved;
        }
    }

    return std::nullopt;
}

std::optional<std::size_t> ResolveWaterRuntimeSessionIndex(const PreviewRuntimeState& runtimeState) {
    if (const auto canonical = ResolveWaterSupportSessionIndex(runtimeState); canonical.has_value()) {
        return canonical;
    }

    const auto committedSceneSupport =
        [&](const ScenePointCloudRuntime& scene) -> std::optional<std::size_t> {
        const auto usable = [&](const std::optional<std::size_t>& index) {
            if (!index.has_value() || index.value() >= runtimeState.sessions.size()) {
                return false;
            }
            const auto& session = runtimeState.sessions[index.value()];
            return IsCommittedDisplayPointCloudReady(runtimeState, session) &&
                   session.offlinePointCloud != nullptr &&
                   !IsGeneratedWaterOverlaySession(session);
        };
        const auto rockRoleIndex = invisible_places::scene::ScenePointCloudRoleIndex(
            invisible_places::scene::ScenePointCloudRole::Rock);
        if (usable(scene.committedDisplaySessionIndices[rockRoleIndex])) {
            return scene.committedDisplaySessionIndices[rockRoleIndex];
        }
        for (const auto index : scene.committedDisplaySessionIndices) {
            if (usable(index)) {
                return index;
            }
        }
        return std::nullopt;
    };
    const auto resolveCandidate = [&](std::size_t index) -> std::optional<std::size_t> {
        if (index >= runtimeState.sessions.size()) {
            return std::nullopt;
        }
        const auto& session = runtimeState.sessions[index];
        if (const auto* scene = FindScenePointCloudRuntime(runtimeState, session); scene != nullptr) {
            return committedSceneSupport(*scene);
        }
        return session.kind == LayerKind::PointCloud && session.loaded && session.visible &&
                       session.offlinePointCloud != nullptr &&
                       !IsGeneratedWaterOverlaySession(session)
                   ? std::optional<std::size_t>{index}
                   : std::nullopt;
    };

    if (runtimeState.selectedSessionIndex.has_value()) {
        const auto selectedIndex = runtimeState.selectedSessionIndex.value();
        const auto resolved = resolveCandidate(selectedIndex);
        if (resolved.has_value()) {
            return resolved;
        }
        if (selectedIndex < runtimeState.sessions.size() &&
            IsSceneGroupedPointCloud(runtimeState.sessions[selectedIndex])) {
            return std::nullopt;
        }
    }
    if (runtimeState.water.activeSupportSessionIndex.has_value()) {
        if (const auto resolved = resolveCandidate(
                runtimeState.water.activeSupportSessionIndex.value());
            resolved.has_value()) {
            return resolved;
        }
    }
    for (std::size_t index = 0U; index < runtimeState.sessions.size(); ++index) {
        if (const auto resolved = resolveCandidate(index); resolved.has_value()) {
            return resolved;
        }
    }
    return std::nullopt;
}

bool IsDynamicMeshSurfacePathCandidate(const std::filesystem::path& path) {
    if (LowercaseAsciiCopy(path.extension().string()) != ".ply") {
        return false;
    }
    return LowercaseAsciiCopy(path.stem().string()).find("mesh") != std::string::npos;
}

std::optional<std::filesystem::path> FindDynamicMeshSurfaceInDirectory(const std::filesystem::path& directory) {
    if (directory.empty() || !std::filesystem::exists(directory) || !std::filesystem::is_directory(directory)) {
        return std::nullopt;
    }

    struct Candidate {
        std::filesystem::path path;
        int score = 0;
    };
    std::vector<Candidate> candidates;
    for (const auto& entry : std::filesystem::directory_iterator{
             directory,
             std::filesystem::directory_options::skip_permission_denied}) {
        if (!entry.is_regular_file() || !IsDynamicMeshSurfacePathCandidate(entry.path())) {
            continue;
        }
        const auto header = invisible_places::io::ParsePlyHeader(entry.path());
        if (!header.success || header.header.faceCount == 0U) {
            continue;
        }

        const auto stem = LowercaseAsciiCopy(entry.path().stem().string());
        int score = 1000;
        if (stem == "mesh" || stem.ends_with("-mesh") || stem.ends_with("_mesh")) {
            score += 120;
        }
        if (stem.find("-mesh") != std::string::npos || stem.find("_mesh") != std::string::npos) {
            score += 60;
        }
        if (stem.find("sample") == std::string::npos) {
            score += 10;
        }
        candidates.push_back({.path = entry.path(), .score = score});
    }
    if (candidates.empty()) {
        return std::nullopt;
    }
    std::sort(candidates.begin(), candidates.end(), [](const Candidate& left, const Candidate& right) {
        if (left.score != right.score) {
            return left.score > right.score;
        }
        return NormalizePathKey(left.path) < NormalizePathKey(right.path);
    });
    return candidates.front().path;
}

std::optional<std::size_t> ResolveDynamicMeshSceneAnchorSessionIndex(const PreviewRuntimeState& runtimeState) {
    auto usableSession = [&](std::size_t index) -> std::optional<std::size_t> {
        if (index >= runtimeState.sessions.size()) {
            return std::nullopt;
        }
        const auto& session = runtimeState.sessions[index];
        if (session.kind != LayerKind::PointCloud || IsGeneratedWaterOverlaySession(session)) {
            return std::nullopt;
        }
        return index;
    };

    if (runtimeState.selectedSessionIndex.has_value()) {
        if (const auto selected = usableSession(runtimeState.selectedSessionIndex.value()); selected.has_value()) {
            return selected;
        }
    }
    if (runtimeState.water.activeSupportSessionIndex.has_value()) {
        if (const auto active = usableSession(runtimeState.water.activeSupportSessionIndex.value()); active.has_value()) {
            return active;
        }
    }
    if (const auto support = ResolveWaterSupportSessionIndex(runtimeState); support.has_value()) {
        if (const auto resolved = usableSession(support.value()); resolved.has_value()) {
            return resolved;
        }
    }
    for (std::size_t index = 0; index < runtimeState.sessions.size(); ++index) {
        if (const auto resolved = usableSession(index); resolved.has_value()) {
            return resolved;
        }
    }
    return std::nullopt;
}

std::optional<std::filesystem::path> ResolveDynamicMeshSceneSurfacePath(const PreviewRuntimeState& runtimeState) {
    if (const auto anchorIndex = ResolveDynamicMeshSceneAnchorSessionIndex(runtimeState);
        anchorIndex.has_value() && anchorIndex.value() < runtimeState.sessions.size()) {
        const auto& anchor = runtimeState.sessions[anchorIndex.value()];
        if (IsDynamicMeshSurfacePathCandidate(anchor.sourcePath) && std::filesystem::exists(anchor.sourcePath)) {
            const auto header = invisible_places::io::ParsePlyHeader(anchor.sourcePath);
            if (header.success && header.header.faceCount > 0U) {
                return anchor.sourcePath;
            }
        }
        if (auto mesh = FindDynamicMeshSurfaceInDirectory(anchor.sourcePath.parent_path()); mesh.has_value()) {
            return mesh;
        }
    }

    for (const auto& session : runtimeState.sessions) {
        if (session.kind != LayerKind::PointCloud ||
            IsGeneratedWaterOverlaySession(session) ||
            !IsDynamicMeshSurfacePathCandidate(session.sourcePath) ||
            !std::filesystem::exists(session.sourcePath)) {
            continue;
        }
        const auto header = invisible_places::io::ParsePlyHeader(session.sourcePath);
        if (header.success && header.header.faceCount > 0U) {
            return session.sourcePath;
        }
    }
    return std::nullopt;
}

std::string WaterSupportDisplayName(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession) {
    if (!IsSceneGroupedPointCloud(sourceSession)) {
        return sourceSession.displayName.empty() ? sourceSession.sourcePath.filename().string() : sourceSession.displayName;
    }

    std::vector<std::string> roles;
    for (const auto& session : runtimeState.sessions) {
        if (!IsVisibleLoadedWaterSupportSession(session) ||
            !SessionsShareSceneFolder(session, sourceSession)) {
            continue;
        }
        if (std::find(roles.begin(), roles.end(), session.sceneRole) == roles.end()) {
            roles.push_back(session.sceneRole);
        }
    }

    std::ostringstream label;
    label << sourceSession.sceneGroupName;
    if (!roles.empty()) {
        label << " (";
        for (std::size_t index = 0; index < roles.size(); ++index) {
            if (index > 0U) {
                label << ", ";
            }
            label << roles[index];
        }
        label << ")";
    }
    return label.str();
}

constexpr std::int32_t kWaterTrailFieldTrailRole = 0;
constexpr std::int32_t kWaterTrailFieldPointAge = 14;
constexpr std::int32_t kWaterTrailFieldTrailAge = 15;
constexpr std::int32_t kWaterTrailFieldTrailSpeed = 16;
constexpr std::int32_t kWaterTrailFieldTrailWidth = 17;
constexpr std::int32_t kWaterTrailFieldTrailStreakLength = 18;
constexpr std::int32_t kWaterTrailFieldTrailConfidence = 19;
constexpr std::int32_t kWaterTrailFieldWetness = 20;

void ConfigureWaterFieldBinding(
    RenderParameterBinding* binding,
    std::int32_t fieldSlot,
    const std::string& fieldName,
    float outputMin,
    float outputMax) {
    if (binding == nullptr) {
        return;
    }

    binding->active = true;
    binding->mode = ParameterSourceMode::FieldMapped;
    binding->fieldMap.fieldSlot = fieldSlot;
    binding->fieldMap.fieldName = fieldName;
    binding->fieldMap.inputMin = 0.0F;
    binding->fieldMap.inputMax = 1.0F;
    binding->fieldMap.outputMin = outputMin;
    binding->fieldMap.outputMax = outputMax;
    binding->fieldMap.gamma = 1.0F;
    binding->fieldMap.flags =
        invisible_places::style::FieldMapFlagClamp |
        invisible_places::style::FieldMapFlagUseLayerStats;
}

const char* WaterOverlayViewModeName(WaterOverlayViewMode mode) {
    switch (mode) {
        case WaterOverlayViewMode::Trail:
            return "Trail View";
        case WaterOverlayViewMode::Path:
            return "Path View";
    }
    return "Trail View";
}

const char* WaterPathDebugOverlayModeName(WaterPathDebugOverlayMode mode) {
    switch (mode) {
        case WaterPathDebugOverlayMode::PathsAndLaneRoutes:
            return "Paths + Lane Routes";
        case WaterPathDebugOverlayMode::PathsOnly:
            return "Paths Only";
        case WaterPathDebugOverlayMode::LaneRoutesOnly:
            return "Lane Routes Only";
    }
    return "Paths + Lane Routes";
}

PointCloudStyleState MakeWaterOverlayStyle(WaterOverlayViewMode viewMode) {
    PointCloudStyleState style;
    style.geometryMode = PointCloudGeometryMode::ScreenSprites;
    style.falloffProfile = PointCloudFalloffProfile::Gaussian;
    style.colorMode = PointCloudColorMode::SourceRgb;
    style.solidColor = {0.04F, 0.74F, 1.0F, 1.0F};
    style.colorizeColor = {0.05F, 0.82F, 1.0F};
    style.colorizeAmount = 0.0F;
    style.exposure = 1.8F;
    style.gaussianSharpness = 1.65F;
    style.solidCenters = true;
    style.flowAnimation = true;
    style.waterTrailOverlay = true;
    style.waterPathView = viewMode == WaterOverlayViewMode::Path;
    style.geometryMode = PointCloudGeometryMode::WorldSurfels;
    style.waterStreakAspect = 7.5F;
    invisible_places::style::SetScalarConstant(
        &style.pointSize,
        style.waterPathView ? 12.0F : 14.0F);
    ConfigureWaterFieldBinding(
        &style.opacity,
        kWaterTrailFieldTrailConfidence,
        "trail_confidence",
        0.0F,
        style.waterPathView ? 1.0F : 0.24F);
    invisible_places::style::SetFieldMapFlag(
        &style.opacity.fieldMap,
        invisible_places::style::FieldMapFlagUseLayerStats,
        false);
    ConfigureWaterFieldBinding(
        &style.emissiveStrength,
        kWaterTrailFieldWetness,
        "wetness",
        style.waterPathView ? 0.65F : 0.0F,
        style.waterPathView ? 1.40F : 0.35F);
    invisible_places::style::SetFieldMapFlag(
        &style.emissiveStrength.fieldMap,
        invisible_places::style::FieldMapFlagUseLayerStats,
        false);
    invisible_places::style::SetScalarConstant(&style.depthFade, 0.0F);
    invisible_places::style::SetScalarConstant(&style.colormapPosition, 0.5F);
    invisible_places::style::SetScalarConstant(&style.surfelDiameter, 0.012F);
    return style;
}

PointCloudStyleState MakeDynamicMeshFlowTrailStyle(
    const WaterDynamicMeshFlowSettings& rawSettings) {
    const auto settings =
        invisible_places::water::SanitizeWaterDynamicMeshFlowSettings(
            rawSettings);
    PointCloudStyleState style;
    style.geometryMode = PointCloudGeometryMode::CameraFacingWorldSprites;
    style.falloffProfile = PointCloudFalloffProfile::Gaussian;
    style.colorMode = PointCloudColorMode::SolidColor;
    style.solidColor = {0.72F, 0.88F, 0.96F, 1.0F};
    style.colorizeColor = {0.58F, 0.82F, 0.94F};
    style.colorizeAmount = 0.0F;
    style.exposure = settings.trailExposure;
    style.gaussianSharpness = 1.15F;
    style.innerRadius = 0.0F;
    style.solidCenters = false;
    style.flowAnimation = true;
    style.waterTrailOverlay = true;
    style.waterPathView = false;
    // Geometry comes from each Ground route's immutable scalar fields. This
    // keeps live appearance edits uniform-only and prevents an ordinary Flow
    // profile from stretching the subtle Mesh filaments into bright needles.
    style.waterTrailStyleGeometry = false;
    ConfigureWaterFieldBinding(
        &style.opacity,
        kWaterTrailFieldWetness,
        "wetness",
        settings.trailOpacityDry,
        settings.trailOpacityWet);
    invisible_places::style::SetFieldMapFlag(
        &style.opacity.fieldMap,
        invisible_places::style::FieldMapFlagUseLayerStats,
        false);
    ConfigureWaterFieldBinding(
        &style.emissiveStrength,
        kWaterTrailFieldWetness,
        "wetness",
        settings.trailEmissionDry,
        settings.trailEmissionWet);
    invisible_places::style::SetFieldMapFlag(
        &style.emissiveStrength.fieldMap,
        invisible_places::style::FieldMapFlagUseLayerStats,
        false);
    invisible_places::style::SetScalarConstant(
        &style.surfelDiameter,
        settings.trailWidthMeters);
    invisible_places::style::SetScalarConstant(&style.depthFade, 0.0F);
    return MakeWaterTrailExportStyle(style);
}

PointCloudStyleState MakeWaterOverlayStyle(
    const WaterParticleVisualSettings& legacyVisualSettings,
    WaterOverlayViewMode viewMode) {
    auto style = MakeWaterOverlayStyle(viewMode);
    if (!style.waterPathView) {
        invisible_places::style::SetScalarConstant(
            &style.pointSize,
            std::clamp(legacyVisualSettings.particleSizePixels, 1.0F, 96.0F));
        style.opacity.fieldMap.outputMax =
            std::clamp(legacyVisualSettings.particleOpacity, 0.0F, 1.0F);
        style.emissiveStrength.fieldMap.outputMax =
            std::clamp(legacyVisualSettings.glow, 0.0F, 4.0F);
    }
    return style;
}

PointCloudStyleState MakeWaterOverlayStyle(const WaterParticleVisualSettings& visualSettings) {
    return MakeWaterOverlayStyle(visualSettings, WaterOverlayViewMode::Trail);
}

PointCloudStyleState MakeDefaultWaterPointVisualStyle() {
    return MakeWaterOverlayStyle(WaterOverlayViewMode::Trail);
}

enum class WaterOverlayVisualPreset {
    WhiteNeedleGlow,
    WhiteGoldSurfels,
    SoftMistLines,
    BlueSilverThreads
};

const char* WaterOverlayVisualPresetName(WaterOverlayVisualPreset preset) {
    switch (preset) {
        case WaterOverlayVisualPreset::WhiteNeedleGlow:
            return "White Needle Glow_preset";
        case WaterOverlayVisualPreset::WhiteGoldSurfels:
            return "White Gold Surfels_preset";
        case WaterOverlayVisualPreset::SoftMistLines:
            return "Soft Mist Lines_preset";
        case WaterOverlayVisualPreset::BlueSilverThreads:
            return "Blue Silver Threads_preset";
    }
    return "Water Visual_preset";
}

PointCloudStyleState MakeWaterOverlayVisualPreset(WaterOverlayVisualPreset preset) {
    auto style = MakeWaterOverlayStyle(WaterOverlayViewMode::Trail);
    style.flowAnimation = true;
    style.waterTrailOverlay = true;
    style.waterPathView = false;
    style.colorMode = PointCloudColorMode::SolidColor;
    style.falloffProfile = PointCloudFalloffProfile::Gaussian;
    style.solidCenters = false;
    style.waterStreakAspect = 1.0F;
    ConfigureWaterFieldBinding(&style.opacity, kWaterTrailFieldPointAge, "point_age", 0.28F, 0.035F);
    invisible_places::style::SetFieldMapFlag(
        &style.opacity.fieldMap,
        invisible_places::style::FieldMapFlagUseLayerStats,
        false);
    ConfigureWaterFieldBinding(&style.emissiveStrength, kWaterTrailFieldWetness, "wetness", 0.55F, 1.65F);
    invisible_places::style::SetFieldMapFlag(
        &style.emissiveStrength.fieldMap,
        invisible_places::style::FieldMapFlagUseLayerStats,
        false);

    switch (preset) {
        case WaterOverlayVisualPreset::WhiteNeedleGlow:
            style.geometryMode = PointCloudGeometryMode::ScreenSprites;
            style.solidColor = {0.96F, 0.98F, 1.0F, 1.0F};
            style.colorizeColor = {0.92F, 0.98F, 1.0F};
            style.exposure = 2.15F;
            style.gaussianSharpness = 2.35F;
            invisible_places::style::SetScalarConstant(&style.pointSize, 5.5F);
            style.opacity.fieldMap.outputMin = 0.32F;
            style.opacity.fieldMap.outputMax = 0.045F;
            style.emissiveStrength.fieldMap.outputMin = 0.85F;
            style.emissiveStrength.fieldMap.outputMax = 2.20F;
            break;
        case WaterOverlayVisualPreset::WhiteGoldSurfels:
            style.geometryMode = PointCloudGeometryMode::WorldSurfels;
            style.solidColor = {1.0F, 0.91F, 0.62F, 1.0F};
            style.colorizeColor = {1.0F, 0.82F, 0.34F};
            style.exposure = 2.35F;
            style.gaussianSharpness = 2.0F;
            style.waterStreakAspect = 9.0F;
            invisible_places::style::SetScalarConstant(&style.surfelDiameter, 0.012F);
            style.opacity.fieldMap.outputMin = 0.38F;
            style.opacity.fieldMap.outputMax = 0.028F;
            style.emissiveStrength.fieldMap.outputMin = 1.10F;
            style.emissiveStrength.fieldMap.outputMax = 2.75F;
            break;
        case WaterOverlayVisualPreset::SoftMistLines:
            style.geometryMode = PointCloudGeometryMode::CameraFacingWorldSprites;
            style.solidColor = {0.82F, 0.91F, 1.0F, 1.0F};
            style.colorizeColor = {0.74F, 0.88F, 1.0F};
            style.exposure = 1.45F;
            style.gaussianSharpness = 0.72F;
            style.waterStreakAspect = 4.0F;
            invisible_places::style::SetScalarConstant(&style.surfelDiameter, 0.040F);
            style.opacity.fieldMap.outputMin = 0.11F;
            style.opacity.fieldMap.outputMax = 0.010F;
            style.emissiveStrength.fieldMap.outputMin = 0.18F;
            style.emissiveStrength.fieldMap.outputMax = 0.62F;
            break;
        case WaterOverlayVisualPreset::BlueSilverThreads:
            style.geometryMode = PointCloudGeometryMode::ScreenSprites;
            style.colorMode = PointCloudColorMode::SourceRgb;
            style.solidColor = {0.78F, 0.92F, 1.0F, 1.0F};
            style.colorizeColor = {0.70F, 0.88F, 1.0F};
            style.exposure = 1.85F;
            style.gaussianSharpness = 1.75F;
            invisible_places::style::SetScalarConstant(&style.pointSize, 8.0F);
            style.opacity.fieldMap.outputMin = 0.24F;
            style.opacity.fieldMap.outputMax = 0.030F;
            style.emissiveStrength.fieldMap.outputMin = 0.55F;
            style.emissiveStrength.fieldMap.outputMax = 1.45F;
            break;
    }
    return MakeWaterTrailExportStyle(style);
}

bool IsProtectedWaterPointVisualName(std::string_view name) {
    const auto normalized = NormalizePointVisualName(name);
    return normalized == "Water Flow_preset" ||
           normalized == WaterOverlayVisualPresetName(WaterOverlayVisualPreset::WhiteNeedleGlow) ||
           normalized == WaterOverlayVisualPresetName(WaterOverlayVisualPreset::WhiteGoldSurfels) ||
           normalized == WaterOverlayVisualPresetName(WaterOverlayVisualPreset::SoftMistLines) ||
           normalized == WaterOverlayVisualPresetName(WaterOverlayVisualPreset::BlueSilverThreads);
}

std::optional<PointCloudStyleState> MakeProtectedWaterPointVisualStyle(
    const PreviewRuntimeState& runtimeState,
    std::string_view name) {
    const auto normalized = NormalizePointVisualName(name);
    if (normalized == "Water Flow_preset") {
        return MakeWaterTrailExportStyle(runtimeState.water.defaultPointVisualStyle);
    }
    if (normalized == WaterOverlayVisualPresetName(WaterOverlayVisualPreset::WhiteNeedleGlow)) {
        return MakeWaterOverlayVisualPreset(WaterOverlayVisualPreset::WhiteNeedleGlow);
    }
    if (normalized == WaterOverlayVisualPresetName(WaterOverlayVisualPreset::WhiteGoldSurfels)) {
        return MakeWaterOverlayVisualPreset(WaterOverlayVisualPreset::WhiteGoldSurfels);
    }
    if (normalized == WaterOverlayVisualPresetName(WaterOverlayVisualPreset::SoftMistLines)) {
        return MakeWaterOverlayVisualPreset(WaterOverlayVisualPreset::SoftMistLines);
    }
    if (normalized == WaterOverlayVisualPresetName(WaterOverlayVisualPreset::BlueSilverThreads)) {
        return MakeWaterOverlayVisualPreset(WaterOverlayVisualPreset::BlueSilverThreads);
    }
    return std::nullopt;
}

void SeedWaterFlowBuiltInVisuals(PreviewRuntimeState* runtimeState, PreviewLayerSession* session) {
    if (runtimeState == nullptr || session == nullptr || session->kind != LayerKind::PointCloud) {
        return;
    }

    constexpr std::string_view protectedNames[] = {
        "Water Flow_preset",
        "White Needle Glow_preset",
        "White Gold Surfels_preset",
        "Soft Mist Lines_preset",
        "Blue Silver Threads_preset",
    };
    std::vector<SavedPointVisualState> seeded;
    seeded.reserve(std::size(protectedNames) + runtimeState->water.pointVisuals.size() + session->pointVisuals.size());
    for (const auto protectedName : protectedNames) {
        if (const auto style = MakeProtectedWaterPointVisualStyle(*runtimeState, protectedName);
            style.has_value()) {
            seeded.push_back({.name = std::string{protectedName}, .style = style.value()});
        }
    }

    auto appendCustomVisual = [&](std::string_view name, const PointCloudStyleState& style) {
        const auto normalized = NormalizePointVisualName(name);
        if (!IsWaterProjectCustomVisualName(normalized)) {
            return;
        }
        if (std::any_of(
                seeded.begin(),
                seeded.end(),
                [&normalized](const SavedPointVisualState& existing) {
                    return NormalizePointVisualName(existing.name) == normalized;
                })) {
            return;
        }
        seeded.push_back({.name = normalized, .style = MakeWaterTrailExportStyle(style)});
    };

    for (const auto& visual : runtimeState->water.pointVisuals) {
        appendCustomVisual(visual.name, visual.style);
    }

    for (const auto& visual : session->pointVisuals) {
        const auto normalized = NormalizePointVisualName(visual.name);
        const auto legacyPresetName = NormalizeWaterPointVisualName(normalized);
        if (legacyPresetName != normalized) {
            const auto protectedStyle = MakeProtectedWaterPointVisualStyle(*runtimeState, legacyPresetName);
            if (!protectedStyle.has_value() ||
                PointStylesEqualForSelection(visual.style, protectedStyle.value())) {
                continue;
            }
        }
        if (!IsWaterProjectCustomVisualName(normalized)) {
            continue;
        }
        appendCustomVisual(normalized, visual.style);
        AppendWaterPointVisualIfMissing(&runtimeState->water.pointVisuals, normalized, visual.style);
    }
    session->pointVisuals = std::move(seeded);
    const auto projectSelectedName =
        runtimeState->water.selectedPointVisualName.empty()
            ? std::string{"Water Flow_preset"}
            : NormalizePointVisualName(runtimeState->water.selectedPointVisualName);
    if (FindPointVisualIndex(*session, projectSelectedName).has_value()) {
        session->selectedPointVisualName = projectSelectedName;
    } else {
        const auto rawSelectedName = NormalizePointVisualName(session->selectedPointVisualName);
        const auto legacySelectedName = NormalizeWaterPointVisualName(rawSelectedName);
        session->selectedPointVisualName =
            legacySelectedName != rawSelectedName &&
                    FindPointVisualIndex(*session, rawSelectedName).has_value()
                ? rawSelectedName
                : legacySelectedName;
    }
    if (!FindPointVisualIndex(*session, session->selectedPointVisualName).has_value()) {
        session->selectedPointVisualName =
            FindPointVisualIndex(*session, projectSelectedName).has_value()
                ? projectSelectedName
                : std::string{"Water Flow_preset"};
    }
    const std::string selectedVisualName = session->selectedPointVisualName;
    SelectPointVisual(session, selectedVisualName);
    runtimeState->water.selectedPointVisualName = session->selectedPointVisualName;
    runtimeState->water.pointVisualNameBuffer = BasePointVisualName(session->selectedPointVisualName);
    session->pointStyle.flowAnimation = true;
    session->pointStyle.waterTrailOverlay = true;
    session->pointStyle.waterPathView = runtimeState->water.overlayViewMode == WaterOverlayViewMode::Path;
}

void ApplyWaterOverlayVisualPreset(PreviewRuntimeState* runtimeState, PreviewLayerSession* session, WaterOverlayVisualPreset preset) {
    if (runtimeState == nullptr || session == nullptr || session->kind != LayerKind::PointCloud) {
        return;
    }

    const std::string presetName = WaterOverlayVisualPresetName(preset);
    const auto style = MakeWaterOverlayVisualPreset(preset);
    EnsurePointVisuals(session);
    UpsertPointVisual(session, presetName, style);
    session->selectedPointVisualName = presetName;
    session->pointVisualNameBuffer = BasePointVisualName(presetName);
    session->pointStyle = style;
    runtimeState->water.selectedPointVisualName = presetName;
    runtimeState->water.pointVisualNameBuffer = BasePointVisualName(presetName);
    runtimeState->statusMessage = "Selected water visual " + presetName + ".";
    runtimeState->errorMessage.clear();
}

PointCloudStyleState MakeWaterOverlayDisplayStyle(const PreviewRuntimeState& runtimeState) {
    auto style = ViewedWaterPointVisualStyle(runtimeState);
    style.flowAnimation = true;
    style.waterTrailOverlay = true;
    style.waterPathView = runtimeState.water.overlayViewMode == WaterOverlayViewMode::Path;
    return style;
}

void ApplyWaterOverlayDisplayStyle(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    for (auto& session : runtimeState->sessions) {
        if (!IsGeneratedWaterFlowOverlaySession(session)) {
            continue;
        }
        session.pointStyle = MakeWaterTrailExportStyle(session.pointStyle);
        if (!IsGeneratedWaterFlowTrailOverlayStem(session.sourcePath.stem().string())) {
            session.pointStyle.waterPathView = runtimeState->water.overlayViewMode == WaterOverlayViewMode::Path;
        }
    }
}

void SetWaterPathDiagnosticColorMode(
    PreviewRuntimeState* runtimeState,
    WaterPathDiagnosticColorMode mode) {
    if (runtimeState == nullptr || runtimeState->water.pathDiagnosticColorMode == mode) {
        return;
    }

    auto& water = runtimeState->water;
    const auto before = water.pathDiagnosticRebuildCounters;
    const auto start = std::chrono::steady_clock::now();
    water.pathDiagnosticColorMode = mode;
    const auto after = water.pathDiagnosticRebuildCounters;
    water.pathDiagnosticModeChangeStats = RecordWaterPathDiagnosticModeChange(
        water.pathDiagnosticModeChangeStats,
        before,
        after,
        std::chrono::steady_clock::now() - start);
    runtimeState->statusMessage =
        std::string{"Path View colours set to "} + WaterPathDiagnosticColorModeLabel(mode) + ".";
    runtimeState->errorMessage.clear();
}

void ApplyWaterPointVisualStyleToGeneratedSessions(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    for (auto& session : runtimeState->sessions) {
        if (!IsGeneratedWaterFlowOverlaySession(session)) {
            continue;
        }
        if (IsGeneratedWaterFlowTrailOverlayStem(session.sourcePath.stem().string())) {
            continue;
        }
        SeedWaterFlowBuiltInVisuals(runtimeState, &session);
    }
}

constexpr std::string_view kWaterProfileGlobalName = "Global";
constexpr std::string_view kWaterProfileDefaultName = "Default";

std::string NormalizeWaterProfileName(std::string_view name, std::string_view fallback = kWaterProfileDefaultName) {
    const auto trimmed = TrimText(name);
    return trimmed.empty() ? std::string{fallback} : trimmed;
}

bool IsGlobalWaterProfileName(std::string_view name) {
    return NormalizeWaterProfileName(name, kWaterProfileGlobalName) == kWaterProfileGlobalName;
}

bool IsEditedWaterProfileName(std::string_view name) {
    const auto normalized = NormalizeWaterProfileName(name);
    return EndsWith(normalized, kEditedPointVisualSuffix) ||
           EndsWith(normalized, kLegacyEditedPointVisualSuffix);
}

std::string UneditedWaterProfileName(std::string_view name) {
    auto normalized = NormalizeWaterProfileName(name);
    const auto suffix = EndsWith(normalized, kEditedPointVisualSuffix)
                            ? kEditedPointVisualSuffix
                            : (EndsWith(
                                   normalized,
                                   kLegacyEditedPointVisualSuffix)
                                   ? kLegacyEditedPointVisualSuffix
                                   : std::string_view{});
    if (!suffix.empty()) {
        normalized.erase(normalized.size() - suffix.size());
    }
    return NormalizeWaterProfileName(normalized);
}

std::string BaseWaterProfileName(std::string_view name) {
    auto normalized = UneditedWaterProfileName(name);
    if (EndsWith(normalized, kPresetPointVisualSuffix)) {
        normalized.erase(normalized.size() - kPresetPointVisualSuffix.size());
    }
    return NormalizeWaterProfileName(normalized);
}

std::string EditedWaterProfileName(std::string_view name) {
    return UneditedWaterProfileName(name) + std::string{kEditedPointVisualSuffix};
}

std::optional<std::size_t> FindWaterPathProfileIndex(
    const WaterWorkflowState& water,
    std::string_view name) {
    const auto normalized = NormalizeWaterProfileName(name);
    for (std::size_t index = 0; index < water.pathProfiles.size(); ++index) {
        if (NormalizeWaterProfileName(water.pathProfiles[index].name) == normalized) {
            return index;
        }
    }
    return std::nullopt;
}

std::optional<std::size_t> FindWaterLaneProfileIndex(
    const WaterWorkflowState& water,
    std::string_view name) {
    const auto normalized = NormalizeWaterProfileName(name);
    for (std::size_t index = 0; index < water.laneProfiles.size(); ++index) {
        if (NormalizeWaterProfileName(water.laneProfiles[index].name) == normalized) {
            return index;
        }
    }
    return std::nullopt;
}

std::optional<std::size_t> FindWaterTrailProfileIndex(
    const WaterWorkflowState& water,
    std::string_view name) {
    const auto normalized = NormalizeWaterProfileName(name);
    for (std::size_t index = 0; index < water.trailProfiles.size(); ++index) {
        if (NormalizeWaterProfileName(water.trailProfiles[index].name) == normalized) {
            return index;
        }
    }
    return std::nullopt;
}

using WaterProfileKind =
    invisible_places::water::WaterFlowProfileKind;

// ---------------------------------------------------------------------------
// Object-specific Flow profile copies. Editing Path/Lanes/Trail settings with
// a Flow source selected saves into a copy named "<base>_<source name>" owned
// by that source; other sources may reference the copy but never rewrite it —
// their own edits fork into their own copy of the same base.
// ---------------------------------------------------------------------------

std::string WaterFlowSourceDisplayName(std::string_view name, std::uint32_t sourceId) {
    const auto trimmed = TrimText(name);
    return trimmed.empty() ? "Source " + std::to_string(sourceId) : std::string{trimmed};
}

// baseProfileName stays resolvable (it may name a "_preset" built-in); only
// the human-facing copy name drops decorations: "Mid_preset" + "Spring" →
// "Mid_Spring".
std::string WaterFlowObjectProfileName(
    std::string_view baseProfileName,
    std::string_view objectName) {
    const auto base = BaseWaterProfileName(baseProfileName);
    const auto object = TrimText(objectName);
    return base + "_" + (object.empty() ? std::string{"Source"} : std::string{object});
}

template <typename ProfileState>
std::optional<std::size_t> FindWaterFlowObjectProfileIndexIn(
    const std::vector<ProfileState>& profiles,
    std::uint32_t ownerObjectId,
    std::string_view baseProfileName) {
    const auto base = NormalizeWaterProfileName(baseProfileName);
    for (std::size_t index = 0; index < profiles.size(); ++index) {
        const auto& profile = profiles[index];
        if (profile.objectOverride &&
            profile.ownerObjectId == ownerObjectId &&
            NormalizeWaterProfileName(profile.baseProfileName) == base) {
            return index;
        }
    }
    return std::nullopt;
}

template <typename ProfileState>
const ProfileState* FindWaterFlowObjectProfileByName(
    const std::vector<ProfileState>& profiles,
    std::string_view name) {
    const auto normalized = NormalizeWaterProfileName(name, kWaterProfileGlobalName);
    for (const auto& profile : profiles) {
        if (profile.objectOverride &&
            NormalizeWaterProfileName(profile.name) == normalized) {
            return &profile;
        }
    }
    return nullptr;
}

// Copy names are human-readable and can collide with a base profile or a
// same-named source's copy; the (owner, base) metadata stays authoritative,
// so a numeric suffix only keeps by-name references unambiguous.
template <typename ProfileState>
std::string UniqueWaterFlowObjectProfileName(
    const std::vector<ProfileState>& profiles,
    std::string_view preferredName,
    const ProfileState* exclude) {
    std::vector<std::string> reserved{
        std::string{kWaterProfileDefaultName},
        std::string{kWaterProfileGlobalName},
    };
    reserved.reserve(profiles.size() + reserved.size());
    for (const auto& profile : profiles) {
        if (&profile != exclude) {
            reserved.push_back(NormalizeWaterProfileName(profile.name));
        }
    }
    return invisible_places::water::AllocateUniqueWaterObjectProfileName(
        NormalizeWaterProfileName(preferredName),
        reserved);
}

// The base a selected source's edit derives from: a Global assignment follows
// the globally selected profile, another object's copy contributes its own
// base, and anything else (saved profile, preset, Default) is its own base.
// The result stays resolvable — "_preset" built-in names are kept, only an
// "_edited" suffix is dropped.
template <typename ProfileState>
std::string WaterFlowObjectEditBaseName(
    const std::vector<ProfileState>& profiles,
    std::string_view assignedProfileName,
    std::string_view selectedProfileName) {
    const auto assigned = NormalizeWaterProfileName(assignedProfileName, kWaterProfileGlobalName);
    if (IsGlobalWaterProfileName(assigned)) {
        return UneditedWaterProfileName(selectedProfileName);
    }
    for (const auto& profile : profiles) {
        if (profile.objectOverride &&
            NormalizeWaterProfileName(profile.name) == assigned) {
            return NormalizeWaterProfileName(profile.baseProfileName);
        }
    }
    return UneditedWaterProfileName(assigned);
}

// Upserts the owner's copy of the derived base and points the assignment at
// it. Returns the copy name that received the edit.
template <typename ProfileState, typename ApplySettings>
std::string CommitWaterFlowObjectProfileEdit(
    std::vector<ProfileState>* profiles,
    std::string* assignedProfileName,
    std::string_view selectedProfileName,
    std::uint32_t ownerObjectId,
    std::string_view ownerName,
    ApplySettings&& applySettings) {
    const auto baseName = WaterFlowObjectEditBaseName(
        *profiles,
        *assignedProfileName,
        selectedProfileName);
    const auto existing = FindWaterFlowObjectProfileIndexIn(
        *profiles,
        ownerObjectId,
        baseName);
    ProfileState* profile = nullptr;
    if (existing.has_value()) {
        profile = &(*profiles)[existing.value()];
    } else {
        profiles->push_back({});
        profile = &profiles->back();
        profile->objectOverride = true;
        profile->ownerObjectId = ownerObjectId;
        profile->baseProfileName = baseName;
        profile->name = UniqueWaterFlowObjectProfileName(
            *profiles,
            WaterFlowObjectProfileName(baseName, ownerName),
            profile);
    }
    applySettings(profile);
    *assignedProfileName = profile->name;
    return profile->name;
}

struct WaterFlowProfileReferenceRewrite {
    invisible_places::water::WaterFlowProfileAssignmentRewrite path;
    invisible_places::water::WaterFlowProfileAssignmentRewrite lane;
    invisible_places::water::WaterFlowProfileAssignmentRewrite trail;
    invisible_places::timing::TimingWaterProfileReferenceRewriteCounts timing;
    std::size_t keyedProfileBaseMirrors = 0U;
    bool dynamicMeshEditedShadowCleared = false;

    [[nodiscard]] bool flowSourceRuntimeChanged() const {
        return !lane.pointSourceIds.empty() ||
               !lane.manualPathSourceIds.empty() ||
               !trail.pointSourceIds.empty() ||
               !trail.manualPathSourceIds.empty();
    }

    [[nodiscard]] bool dynamicMeshRuntimeChanged() const {
        return trail.dynamicMeshTrailChanged ||
               dynamicMeshEditedShadowCleared;
    }
};

void MergeWaterFlowProfileAssignmentRewrite(
    invisible_places::water::WaterFlowProfileAssignmentRewrite* target,
    invisible_places::water::WaterFlowProfileAssignmentRewrite source) {
    if (target == nullptr) {
        return;
    }
    const auto appendUnique = [](std::vector<std::uint32_t>* destination,
                                 std::span<const std::uint32_t> values) {
        for (const auto value : values) {
            if (std::find(destination->begin(), destination->end(), value) ==
                destination->end()) {
                destination->push_back(value);
            }
        }
    };
    appendUnique(&target->pointSourceIds, source.pointSourceIds);
    appendUnique(&target->manualPathSourceIds, source.manualPathSourceIds);
    target->dynamicMeshTrailChanged |= source.dynamicMeshTrailChanged;
    target->dynamicMeshEditedTrailProfileMatched |=
        source.dynamicMeshEditedTrailProfileMatched;
}

void MergeWaterFlowProfileReferenceRewrite(
    WaterFlowProfileReferenceRewrite* target,
    WaterFlowProfileReferenceRewrite source) {
    if (target == nullptr) {
        return;
    }
    MergeWaterFlowProfileAssignmentRewrite(
        &target->path,
        std::move(source.path));
    MergeWaterFlowProfileAssignmentRewrite(
        &target->lane,
        std::move(source.lane));
    MergeWaterFlowProfileAssignmentRewrite(
        &target->trail,
        std::move(source.trail));
    target->timing.legacyScenarioTracks +=
        source.timing.legacyScenarioTracks;
    target->timing.timingTakeTracks +=
        source.timing.timingTakeTracks;
    target->timing.keyedPackageTracks +=
        source.timing.keyedPackageTracks;
    target->keyedProfileBaseMirrors +=
        source.keyedProfileBaseMirrors;
    target->dynamicMeshEditedShadowCleared |=
        source.dynamicMeshEditedShadowCleared;
}

// Rewrites every exact by-name reference for one Flow profile kind. Lane is
// the only kind whose name is also persisted on manual Flow Path tracks and
// keyed-package base mirrors.
WaterFlowProfileReferenceRewrite ReplaceWaterFlowProfileReferences(
    WaterWorkflowState* water,
    WaterProfileKind kind,
    std::string_view previousName,
    std::string_view nextName) {
    WaterFlowProfileReferenceRewrite rewrite;
    if (water == nullptr || TrimText(previousName).empty() ||
        TrimText(nextName).empty()) {
        return rewrite;
    }
    const auto previous = NormalizeWaterProfileName(previousName);
    const auto next = NormalizeWaterProfileName(nextName);
    const std::string_view dynamicMeshEditedTrailName =
        water->editedDynamicMeshTrailProfile.has_value()
            ? std::string_view{
                  water->editedDynamicMeshTrailProfile->name}
            : std::string_view{};
    auto assignments = invisible_places::water::
        ReplaceWaterFlowProfileAssignments(
            water->emitters,
            water->manualFlowPaths,
            &water->dynamicMeshFlowSettings,
            kind,
            previous,
            next,
            dynamicMeshEditedTrailName);
    auto* assignmentResult =
        kind == WaterProfileKind::Path
            ? &rewrite.path
        : kind == WaterProfileKind::Lane
            ? &rewrite.lane
            : &rewrite.trail;
    *assignmentResult = std::move(assignments);

    if (kind == WaterProfileKind::Lane) {
        rewrite.timing = invisible_places::timing::
            ReplaceTimingWaterProfileReferences(
                water->featureTimingRunsByScenario,
                water->timingTakeSceneStates,
                water->keyedSettingsProfiles,
                "flow_path",
                previous,
                next);
        rewrite.keyedProfileBaseMirrors = invisible_places::water::
            ReplaceWaterKeyedSettingsProfileBaseReferences(
                water->keyedSettingsProfiles,
                invisible_places::water::WaterKeyedFeatureKind::FlowPath,
                previous,
                next);
    }

    if (rewrite.trail.dynamicMeshTrailChanged) {
        water->dynamicMeshTrailProfileNameBuffer =
            BaseWaterProfileName(next);
        if (rewrite.trail.dynamicMeshEditedTrailProfileMatched) {
            water->editedDynamicMeshTrailProfile.reset();
            rewrite.dynamicMeshEditedShadowCleared = true;
        }
    }
    return rewrite;
}

// Renaming a source renames its copies so the "<base>_<source name>"
// convention keeps holding; every by-name reference follows the rename.
WaterFlowProfileReferenceRewrite RenameWaterFlowSourceObjectProfiles(
    WaterWorkflowState* water,
    std::uint32_t ownerObjectId,
    std::string_view ownerName) {
    WaterFlowProfileReferenceRewrite rewrite;
    const auto renameIn = [&](auto* profiles, WaterProfileKind kind) {
        for (auto& profile : *profiles) {
            if (!profile.objectOverride || profile.ownerObjectId != ownerObjectId) {
                continue;
            }
            const auto renamed = UniqueWaterFlowObjectProfileName(
                *profiles,
                WaterFlowObjectProfileName(profile.baseProfileName, ownerName),
                &profile);
            if (renamed == NormalizeWaterProfileName(profile.name)) {
                continue;
            }
            const auto previous = profile.name;
            profile.name = renamed;
            MergeWaterFlowProfileReferenceRewrite(
                &rewrite,
                ReplaceWaterFlowProfileReferences(
                    water,
                    kind,
                    previous,
                    renamed));
        }
    };
    renameIn(&water->pathProfiles, WaterProfileKind::Path);
    renameIn(&water->laneProfiles, WaterProfileKind::Lane);
    renameIn(&water->trailProfiles, WaterProfileKind::Trail);
    return rewrite;
}

// Deleting a source removes its copies; sources referencing a removed copy
// fall back to the copy's base so their look changes predictably instead of
// dangling on a missing name.
WaterFlowProfileReferenceRewrite RemoveWaterFlowSourceObjectProfiles(
    WaterWorkflowState* water,
    std::uint32_t ownerObjectId) {
    WaterFlowProfileReferenceRewrite rewrite;
    const auto removeIn = [&](auto* profiles, WaterProfileKind kind) {
        for (std::size_t index = profiles->size(); index > 0U; --index) {
            auto& profile = (*profiles)[index - 1U];
            if (!profile.objectOverride || profile.ownerObjectId != ownerObjectId) {
                continue;
            }
            const auto removedName = profile.name;
            const auto baseName = NormalizeWaterProfileName(profile.baseProfileName);
            MergeWaterFlowProfileReferenceRewrite(
                &rewrite,
                ReplaceWaterFlowProfileReferences(
                    water,
                    kind,
                    removedName,
                    baseName));
            profiles->erase(profiles->begin() + static_cast<std::ptrdiff_t>(index - 1U));
        }
    };
    removeIn(&water->pathProfiles, WaterProfileKind::Path);
    removeIn(&water->laneProfiles, WaterProfileKind::Lane);
    removeIn(&water->trailProfiles, WaterProfileKind::Trail);
    return rewrite;
}

// ---------------------------------------------------------------------------
// Seepage object-copy helpers: the same per-object fork model over the
// node-referenced settings/look/response libraries. Renames and removals also
// follow keyed profile tracks, which reference these profiles by (group, name).
// ---------------------------------------------------------------------------

void ReplaceWaterSeepageProfileReferences(
    WaterWorkflowState* water,
    bool responseHalf,
    std::string_view previousName,
    std::string_view nextName) {
    const auto previous = NormalizedWaterSeepageProfileName(previousName);
    (void)invisible_places::water::
        ReplaceWaterSeepageNodeProfileReferences(
            water->seepageNodes,
            responseHalf
                ? invisible_places::water::WaterSeepageProfileHalf::Response
                : invisible_places::water::WaterSeepageProfileHalf::Look,
            previous,
            nextName);
    const std::string_view group =
        responseHalf ? "seepage_response" : "seepage_look";
    (void)invisible_places::timing::ReplaceTimingWaterProfileReferences(
        water->featureTimingRunsByScenario,
        water->timingTakeSceneStates,
        water->keyedSettingsProfiles,
        group,
        previous,
        nextName);
}

std::size_t RemoveWaterFeatureTimingReferences(
    WaterWorkflowState* water,
    const invisible_places::water::WaterKeyedFeatureId& feature) {
    if (water == nullptr) {
        return 0U;
    }
    std::size_t removed = 0U;
    for (auto& entry : water->featureTimingRunsByScenario) {
        removed += invisible_places::water::RemoveWaterFeatureFromTimingRuns(
            entry.runs,
            feature);
    }
    for (auto& state : water->timingTakeSceneStates) {
        removed += invisible_places::water::RemoveWaterFeatureFromTimingRuns(
            state.waterFeatureTimingRuns,
            feature);
    }
    if (water->activeKeyingFeature == feature) {
        water->activeKeyingFeature.reset();
    }
    return removed;
}

void ReplaceWaterSeepageNodeSettingsProfileReferences(
    WaterWorkflowState* water,
    std::string_view previousName,
    std::string_view nextName) {
    const auto previous =
        NormalizedWaterSeepageProfileName(previousName);
    const auto settings =
        WaterSeepageNodeSettingsByName(*water, nextName);
    for (auto& node : water->seepageNodes) {
        if (NormalizedWaterSeepageProfileName(
                node.settingsProfileName) != previous) {
            continue;
        }
        node.settingsProfileName = std::string{nextName};
        invisible_places::water::ApplyWaterSeepageNodeSettings(
            settings,
            &node);
    }
    constexpr std::string_view kProfileGroup =
        "seepage_node_settings";
    (void)invisible_places::timing::ReplaceTimingWaterProfileReferences(
        water->featureTimingRunsByScenario,
        water->timingTakeSceneStates,
        water->keyedSettingsProfiles,
        kProfileGroup,
        previous,
        nextName);
}

template <typename ProfileState>
bool EraseWaterSeepageWorkingProfile(
    std::vector<ProfileState>* profiles,
    const invisible_places::water::WaterObjectProfileEditDescriptor&
        descriptor,
    std::uint32_t selectedOwnerObjectId) {
    if (profiles == nullptr ||
        descriptor.removableWorkingProfileName.empty()) {
        return false;
    }
    const auto workingName = TrimText(
        descriptor.removableWorkingProfileName);
    const auto profile = std::find_if(
        profiles->begin(),
        profiles->end(),
        [&](const ProfileState& candidate) {
            return TrimText(candidate.name) == workingName;
        });
    if (profile == profiles->end()) {
        return false;
    }
    if (profile->objectOverride) {
        if (!descriptor.ownedObjectCopy ||
            profile->ownerObjectId != selectedOwnerObjectId) {
            return false;
        }
    } else if (!descriptor.legacyEditedShadow) {
        return false;
    }
    profiles->erase(profile);
    return true;
}

void RenameWaterSeepageNodeObjectProfiles(
    WaterWorkflowState* water,
    std::uint32_t nodeId,
    std::string_view nodeName) {
    const auto renameIn = [&](auto* profiles, bool responseHalf) {
        for (auto& profile : *profiles) {
            if (!profile.objectOverride || profile.ownerObjectId != nodeId) {
                continue;
            }
            const auto renamed = UniqueWaterFlowObjectProfileName(
                *profiles,
                WaterFlowObjectProfileName(profile.baseProfileName, nodeName),
                &profile);
            if (renamed == NormalizedWaterSeepageProfileName(profile.name)) {
                continue;
            }
            const auto previous = profile.name;
            profile.name = renamed;
            ReplaceWaterSeepageProfileReferences(
                water,
                responseHalf,
                previous,
                renamed);
        }
    };
    for (auto& profile : water->seepageNodeSettingsProfiles) {
        if (!profile.objectOverride || profile.ownerObjectId != nodeId) {
            continue;
        }
        const auto renamed = UniqueWaterFlowObjectProfileName(
            water->seepageNodeSettingsProfiles,
            WaterFlowObjectProfileName(profile.baseProfileName, nodeName),
            &profile);
        if (renamed ==
            NormalizedWaterSeepageProfileName(profile.name)) {
            continue;
        }
        const auto previous = profile.name;
        profile.name = renamed;
        ReplaceWaterSeepageNodeSettingsProfileReferences(
            water,
            previous,
            renamed);
    }
    renameIn(&water->seepageLookProfiles, false);
    renameIn(&water->seepageResponseProfiles, true);
}

void RemoveWaterSeepageNodeObjectProfiles(
    WaterWorkflowState* water,
    std::uint32_t nodeId) {
    const auto removeIn = [&](auto* profiles, bool responseHalf) {
        for (std::size_t index = profiles->size(); index > 0U; --index) {
            auto& profile = (*profiles)[index - 1U];
            if (!profile.objectOverride || profile.ownerObjectId != nodeId) {
                continue;
            }
            const auto removedName = profile.name;
            const auto baseName =
                NormalizedWaterSeepageProfileName(profile.baseProfileName);
            profiles->erase(
                profiles->begin() + static_cast<std::ptrdiff_t>(index - 1U));
            ReplaceWaterSeepageProfileReferences(
                water,
                responseHalf,
                removedName,
                baseName);
        }
    };
    for (std::size_t index = water->seepageNodeSettingsProfiles.size();
         index > 0U;
         --index) {
        auto& profile = water->seepageNodeSettingsProfiles[index - 1U];
        if (!profile.objectOverride || profile.ownerObjectId != nodeId) {
            continue;
        }
        const auto removedName = profile.name;
        const auto baseName =
            NormalizedWaterSeepageProfileName(profile.baseProfileName);
        water->seepageNodeSettingsProfiles.erase(
            water->seepageNodeSettingsProfiles.begin() +
            static_cast<std::ptrdiff_t>(index - 1U));
        ReplaceWaterSeepageNodeSettingsProfileReferences(
            water,
            removedName,
            baseName);
    }
    removeIn(&water->seepageLookProfiles, false);
    removeIn(&water->seepageResponseProfiles, true);
}

// Load-time hygiene: orphaned copies dissolve to their base for every
// referencing node, and copies whose owner was renamed outside this session
// re-sync to "<base>_<node name>".
void ReconcileWaterSeepageObjectProfiles(WaterWorkflowState* water) {
    std::unordered_set<std::uint32_t> nodeIds;
    for (const auto& node : water->seepageNodes) {
        nodeIds.insert(node.id);
    }
    const auto dropOrphans = [&](auto* profiles, bool responseHalf) {
        for (std::size_t index = profiles->size(); index > 0U; --index) {
            auto& profile = (*profiles)[index - 1U];
            if (!profile.objectOverride) {
                continue;
            }
            profile.baseProfileName =
                NormalizedWaterSeepageProfileName(profile.baseProfileName);
            if (nodeIds.contains(profile.ownerObjectId)) {
                continue;
            }
            const auto removedName = profile.name;
            const auto baseName = profile.baseProfileName;
            profiles->erase(
                profiles->begin() + static_cast<std::ptrdiff_t>(index - 1U));
            ReplaceWaterSeepageProfileReferences(
                water,
                responseHalf,
                removedName,
                baseName);
        }
    };
    for (std::size_t index = water->seepageNodeSettingsProfiles.size();
         index > 0U;
         --index) {
        auto& profile = water->seepageNodeSettingsProfiles[index - 1U];
        if (!profile.objectOverride) {
            continue;
        }
        profile.baseProfileName =
            NormalizedWaterSeepageProfileName(profile.baseProfileName);
        if (nodeIds.contains(profile.ownerObjectId)) {
            continue;
        }
        const auto removedName = profile.name;
        const auto baseName = profile.baseProfileName;
        water->seepageNodeSettingsProfiles.erase(
            water->seepageNodeSettingsProfiles.begin() +
            static_cast<std::ptrdiff_t>(index - 1U));
        ReplaceWaterSeepageNodeSettingsProfileReferences(
            water,
            removedName,
            baseName);
    }
    dropOrphans(&water->seepageLookProfiles, false);
    dropOrphans(&water->seepageResponseProfiles, true);
    for (const auto& node : water->seepageNodes) {
        RenameWaterSeepageNodeObjectProfiles(
            water,
            node.id,
            WaterFlowSourceDisplayName(node.name, node.id));
    }
    // Profile values are authoritative in current documents. A dangling
    // name is repaired into a Default-derived node copy using the serialized
    // node fields, preserving malformed/manual edits instead of resetting
    // the footprint.
    for (auto& node : water->seepageNodes) {
        const auto assigned =
            NormalizedWaterSeepageProfileName(
                node.settingsProfileName);
        if (assigned == "Default") {
            node.settingsProfileName = "Default";
            invisible_places::water::ApplyWaterSeepageNodeSettings(
                water->defaultSeepageNodeSettings,
                &node);
            continue;
        }
        if (const auto profileIndex =
                FindWaterSeepageNodeSettingsProfileIndex(
                    *water,
                    assigned);
            profileIndex.has_value()) {
            invisible_places::water::ApplyWaterSeepageNodeSettings(
                water->seepageNodeSettingsProfiles[profileIndex.value()]
                    .settings,
                &node);
            continue;
        }
        const auto preserved =
            invisible_places::water::ExtractWaterSeepageNodeSettings(node);
        node.settingsProfileName = "Default";
        CommitWaterFlowObjectProfileEdit(
            &water->seepageNodeSettingsProfiles,
            &node.settingsProfileName,
            "Default",
            node.id,
            WaterFlowSourceDisplayName(node.name, node.id),
            [&](WaterSeepageNodeSettingsProfile* profile) {
                profile->settings = preserved;
            });
    }
}

std::optional<WaterPathGenerationSettings> BuiltInWaterPathProfileSettings(std::string_view name) {
    const auto normalized = NormalizeWaterProfileName(name);
    if (normalized == "Aerial_preset") {
        return invisible_places::water::DefaultWaterPathGenerationSettings(WaterScaleMode::Aerial);
    }
    if (normalized == "Mid_preset") {
        return invisible_places::water::DefaultWaterPathGenerationSettings(WaterScaleMode::Mid);
    }
    if (normalized == "Detail_preset") {
        return invisible_places::water::DefaultWaterPathGenerationSettings(WaterScaleMode::Detail);
    }
    return std::nullopt;
}

std::optional<WaterFlowTrailSettings> BuiltInWaterLaneProfileSettings(std::string_view name) {
    const auto normalized = NormalizeWaterProfileName(name);
    WaterFlowTrailSettings settings;
    if (normalized == "Calm Lanes_preset") {
        settings.trailCountTotal = 420U;
        settings.laneCount = 5U;
        settings.laneSpreadMeters = 0.08F;
        settings.laneCrossing = 0.06F;
        settings.turbulence = 0.015F;
        settings.speedMetersPerSecond = 0.24F;
        settings.seed = 11U;
        return settings;
    }
    if (normalized == "Braided Lanes_preset") {
        settings.trailCountTotal = 1100U;
        settings.laneCount = 11U;
        settings.laneSpreadMeters = 0.28F;
        settings.laneCrossing = 0.62F;
        settings.turbulence = 0.22F;
        settings.speedMetersPerSecond = 0.62F;
        settings.seed = 37U;
        return settings;
    }
    if (normalized == "Wide Sheet_preset") {
        settings.trailCountTotal = 1800U;
        settings.laneCount = 17U;
        settings.laneSpreadMeters = 0.55F;
        settings.laneCrossing = 0.18F;
        settings.turbulence = 0.08F;
        settings.speedMetersPerSecond = 0.38F;
        settings.seed = 73U;
        return settings;
    }
    return std::nullopt;
}

SavedWaterTrailProfileState MakeWaterTrailProfile(
    std::string_view name,
    const WaterTrailGeometrySettings& geometry,
    PointCloudStyleState style) {
    style = MakeWaterTrailSessionStyle(style, geometry);
    return {
        .name = NormalizeWaterProfileName(name),
        .geometry = geometry,
        .style = style,
    };
}

std::optional<SavedWaterTrailProfileState> BuiltInWaterTrailProfile(
    const PreviewRuntimeState& runtimeState,
    std::string_view name) {
    const auto normalized = NormalizeWaterProfileName(name);
    WaterTrailGeometrySettings geometry = runtimeState.water.defaultTrailGeometry;
    if (normalized == "Water Flow_preset") {
        return MakeWaterTrailProfile(normalized, geometry, runtimeState.water.defaultPointVisualStyle);
    }
    if (normalized == WaterOverlayVisualPresetName(WaterOverlayVisualPreset::WhiteNeedleGlow)) {
        geometry.trailLengthMeters = 0.95F;
        geometry.pointSpacingMeters = 0.018F;
        geometry.widthMeters = 0.0055F;
        geometry.streakLengthMeters = 0.045F;
        return MakeWaterTrailProfile(
            normalized,
            geometry,
            MakeWaterOverlayVisualPreset(WaterOverlayVisualPreset::WhiteNeedleGlow));
    }
    if (normalized == WaterOverlayVisualPresetName(WaterOverlayVisualPreset::WhiteGoldSurfels)) {
        geometry.trailLengthMeters = 1.35F;
        geometry.pointSpacingMeters = 0.026F;
        geometry.widthMeters = 0.012F;
        geometry.streakLengthMeters = 0.108F;
        return MakeWaterTrailProfile(
            normalized,
            geometry,
            MakeWaterOverlayVisualPreset(WaterOverlayVisualPreset::WhiteGoldSurfels));
    }
    if (normalized == WaterOverlayVisualPresetName(WaterOverlayVisualPreset::SoftMistLines)) {
        geometry.trailLengthMeters = 2.2F;
        geometry.pointSpacingMeters = 0.045F;
        geometry.widthMeters = 0.040F;
        geometry.streakLengthMeters = 0.160F;
        return MakeWaterTrailProfile(
            normalized,
            geometry,
            MakeWaterOverlayVisualPreset(WaterOverlayVisualPreset::SoftMistLines));
    }
    if (normalized == WaterOverlayVisualPresetName(WaterOverlayVisualPreset::BlueSilverThreads)) {
        geometry.trailLengthMeters = 1.1F;
        geometry.pointSpacingMeters = 0.022F;
        geometry.widthMeters = 0.008F;
        geometry.streakLengthMeters = 0.055F;
        return MakeWaterTrailProfile(
            normalized,
            geometry,
            MakeWaterOverlayVisualPreset(WaterOverlayVisualPreset::BlueSilverThreads));
    }
    return std::nullopt;
}

bool IsProtectedWaterPathProfileName(std::string_view name) {
    return BuiltInWaterPathProfileSettings(name).has_value();
}

bool IsProtectedWaterLaneProfileName(std::string_view name) {
    return BuiltInWaterLaneProfileSettings(name).has_value();
}

bool IsProtectedWaterTrailProfileName(const PreviewRuntimeState& runtimeState, std::string_view name) {
    return BuiltInWaterTrailProfile(runtimeState, name).has_value();
}

void EnsureWaterProfiles(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    auto& water = runtimeState->water;
    // These name-entry buffers are session UI state, not project data. A
    // newly loaded/imported project must never inherit a prior project's
    // Save As text just because object ids and generated copy names match.
    water.pathProfilePromotion = {};
    water.laneProfilePromotion = {};
    water.trailProfilePromotion = {};
    auto sanitizeNameList = [](auto* profiles, auto protectedPredicate) {
        using Profile = typename std::remove_reference_t<decltype(*profiles)>::value_type;
        std::vector<Profile> kept;
        kept.reserve(profiles->size());
        for (auto profile : *profiles) {
            profile.name = NormalizeWaterProfileName(profile.name);
            const auto duplicate = std::any_of(
                kept.begin(),
                kept.end(),
                [&](const Profile& existing) {
                    return NormalizeWaterProfileName(existing.name) == profile.name;
            });
            if (profile.name == kWaterProfileDefaultName ||
                invisible_places::water::
                    WaterObjectProfileNameIsLegacyEditedShadow(
                        profile.name,
                        profile.objectOverride) ||
                protectedPredicate(profile.name) ||
                duplicate) {
                continue;
            }
            kept.push_back(std::move(profile));
        }
        *profiles = std::move(kept);
    };
    sanitizeNameList(&water.pathProfiles, [](std::string_view name) {
        return IsProtectedWaterPathProfileName(name);
    });
    sanitizeNameList(&water.laneProfiles, [](std::string_view name) {
        return IsProtectedWaterLaneProfileName(name);
    });
    sanitizeNameList(&water.trailProfiles, [&](std::string_view name) {
        return IsProtectedWaterTrailProfileName(*runtimeState, name);
    });
    water.selectedPathProfileName = NormalizeWaterProfileName(water.selectedPathProfileName);
    water.selectedLaneProfileName = NormalizeWaterProfileName(water.selectedLaneProfileName);
    water.selectedTrailProfileName = NormalizeWaterProfileName(water.selectedTrailProfileName);
    water.pathProfileNameBuffer = BaseWaterProfileName(water.selectedPathProfileName);
    water.laneProfileNameBuffer = BaseWaterProfileName(water.selectedLaneProfileName);
    water.trailProfileNameBuffer = BaseWaterProfileName(water.selectedTrailProfileName);
    for (auto& emitter : water.emitters) {
        emitter.pathProfileName = NormalizeWaterProfileName(emitter.pathProfileName, kWaterProfileGlobalName);
        emitter.laneProfileName = NormalizeWaterProfileName(emitter.laneProfileName, kWaterProfileGlobalName);
        emitter.trailProfileName = NormalizeWaterProfileName(emitter.trailProfileName, kWaterProfileGlobalName);
    }
    water.keyedSettingsProfiles = invisible_places::water::
        SanitizeWaterKeyedSettingsProfileLibrary(
            std::move(water.keyedSettingsProfiles));
    for (auto& source : water.manualFlowPaths) {
        source.laneProfileName = NormalizeWaterProfileName(
            source.laneProfileName,
            kWaterProfileGlobalName);
        source.trailProfileName = NormalizeWaterProfileName(
            source.trailProfileName,
            kWaterProfileGlobalName);
        source.keyedSettingsProfileName =
            TrimText(source.keyedSettingsProfileName);
        if (!source.keyedSettingsProfileName.empty() &&
            std::none_of(
                water.keyedSettingsProfiles.begin(),
                water.keyedSettingsProfiles.end(),
                [&](const auto& profile) {
                    return profile.featureKind ==
                               invisible_places::water::
                                   WaterKeyedFeatureKind::FlowPath &&
                           profile.name == source.keyedSettingsProfileName;
                })) {
            source.keyedSettingsProfileName.clear();
        }
    }
    // Object copies must reference a live owner: orphans dissolve back to
    // their base for every referencing source, and copies whose owner was
    // renamed outside this session re-sync to "<base>_<source name>".
    std::unordered_set<std::uint32_t> flowSourceIds;
    for (const auto& emitter : water.emitters) {
        flowSourceIds.insert(emitter.id);
    }
    for (const auto& source : water.manualFlowPaths) {
        flowSourceIds.insert(source.id);
    }
    WaterFlowProfileReferenceRewrite reconciliation;
    const auto dropOrphanCopies = [&](auto* profiles, WaterProfileKind kind) {
        for (std::size_t index = profiles->size(); index > 0U; --index) {
            auto& profile = (*profiles)[index - 1U];
            if (!profile.objectOverride) {
                continue;
            }
            profile.baseProfileName =
                NormalizeWaterProfileName(profile.baseProfileName);
            if (flowSourceIds.contains(profile.ownerObjectId)) {
                continue;
            }
            const auto removedName = profile.name;
            const auto baseName = profile.baseProfileName;
            profiles->erase(
                profiles->begin() + static_cast<std::ptrdiff_t>(index - 1U));
            MergeWaterFlowProfileReferenceRewrite(
                &reconciliation,
                ReplaceWaterFlowProfileReferences(
                    &water,
                    kind,
                    removedName,
                    baseName));
        }
    };
    dropOrphanCopies(&water.pathProfiles, WaterProfileKind::Path);
    dropOrphanCopies(&water.laneProfiles, WaterProfileKind::Lane);
    dropOrphanCopies(&water.trailProfiles, WaterProfileKind::Trail);
    for (const auto& emitter : water.emitters) {
        MergeWaterFlowProfileReferenceRewrite(
            &reconciliation,
            RenameWaterFlowSourceObjectProfiles(
                &water,
                emitter.id,
                WaterFlowSourceDisplayName(emitter.name, emitter.id)));
    }
    for (const auto& source : water.manualFlowPaths) {
        MergeWaterFlowProfileReferenceRewrite(
            &reconciliation,
            RenameWaterFlowSourceObjectProfiles(
                &water,
                source.id,
                WaterFlowSourceDisplayName(source.name, source.id)));
    }
    for (const auto sourceId : reconciliation.path.pointSourceIds) {
        MarkWaterPathDirty(runtimeState, sourceId);
    }
    // The global selectors only ever hold shared names; a selection left on
    // an object copy falls back to the copy's base.
    const auto selectBase = [](const auto& profiles, std::string* selectedName) {
        if (const auto* copy = FindWaterFlowObjectProfileByName(profiles, *selectedName);
            copy != nullptr) {
            *selectedName = NormalizeWaterProfileName(copy->baseProfileName);
        }
    };
    selectBase(water.pathProfiles, &water.selectedPathProfileName);
    selectBase(water.laneProfiles, &water.selectedLaneProfileName);
    selectBase(water.trailProfiles, &water.selectedTrailProfileName);
    water.pathProfileNameBuffer = BaseWaterProfileName(water.selectedPathProfileName);
    water.laneProfileNameBuffer = BaseWaterProfileName(water.selectedLaneProfileName);
    water.trailProfileNameBuffer = BaseWaterProfileName(water.selectedTrailProfileName);
    EnsureWaterRainProfiles(&water);
}

