void SuggestWaterEmittersForActiveLayer(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    const auto supportIndex = ResolveWaterSupportSessionIndex(*runtimeState);
    if (!supportIndex.has_value() || supportIndex.value() >= runtimeState->sessions.size()) {
        runtimeState->errorMessage = "Canonical analysis sources are still loading or unavailable; source suggestions are disabled.";
        runtimeState->statusMessage.clear();
        return;
    }
    const auto& session = runtimeState->sessions[supportIndex.value()];
    if (session.offlinePointCloud == nullptr) {
        runtimeState->errorMessage = "The active water support scene is not available on CPU.";
        runtimeState->statusMessage.clear();
        return;
    }
    const auto defaultSourceSettings = ActiveProfileDefaultWaterSourceSettings(runtimeState->water);
    const auto* supportCloud = EnsureWaterSupportCloud(
        runtimeState,
        session,
        defaultSourceSettings.path);
    if (supportCloud == nullptr || supportCloud->positions.empty()) {
        runtimeState->errorMessage = "No usable point-cloud support was available for water source suggestions.";
        runtimeState->statusMessage.clear();
        return;
    }

    const auto firstId = NextWaterEmitterId(*runtimeState);
    auto suggestions = invisible_places::water::SuggestWaterEmitters(
        *supportCloud,
        runtimeState->water.emitters,
        defaultSourceSettings.path,
        firstId,
        runtimeState->water.maxAutoSuggestions);
    if (suggestions.empty()) {
        runtimeState->statusMessage = "No conservative water source candidates were found.";
        runtimeState->errorMessage.clear();
        return;
    }

    runtimeState->water.nextEmitterId = firstId + static_cast<std::uint32_t>(suggestions.size());
    runtimeState->water.emitters.insert(
        runtimeState->water.emitters.end(),
        std::make_move_iterator(suggestions.begin()),
        std::make_move_iterator(suggestions.end()));
    for (std::uint32_t emitterId = firstId; emitterId < runtimeState->water.nextEmitterId; ++emitterId) {
        MarkWaterPathDirty(runtimeState, emitterId);
    }
    runtimeState->statusMessage =
        "Suggested " + FormatPointCount(runtimeState->water.nextEmitterId - firstId) +
        " conservative water sources; path bake required.";
    runtimeState->errorMessage.clear();
}

void PropagateWaterEmittersToActiveLayer(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    const auto supportIndex = ResolveWaterSupportSessionIndex(*runtimeState);
    if (!supportIndex.has_value() || supportIndex.value() >= runtimeState->sessions.size()) {
        runtimeState->errorMessage = "Canonical analysis sources are still loading or unavailable; emitter propagation is disabled.";
        runtimeState->statusMessage.clear();
        return;
    }
    const auto& targetSession = runtimeState->sessions[supportIndex.value()];
    if (targetSession.offlinePointCloud == nullptr) {
        runtimeState->errorMessage = "The active water support scene is not available on CPU.";
        runtimeState->statusMessage.clear();
        return;
    }
    const auto defaultSourceSettings = ActiveProfileDefaultWaterSourceSettings(runtimeState->water);
    const auto* supportCloud = EnsureWaterSupportCloud(
        runtimeState,
        targetSession,
        defaultSourceSettings.path);
    if (supportCloud == nullptr || supportCloud->positions.empty()) {
        runtimeState->errorMessage = "No usable point-cloud support was available for water source snapping.";
        runtimeState->statusMessage.clear();
        return;
    }

    std::vector<WaterEmitter> propagated;
    std::vector<std::uint32_t> propagatedEmitterIds;
    for (const auto& emitter : runtimeState->water.emitters) {
        if (emitter.status == WaterEmitterStatus::Disabled ||
            emitter.origin == WaterEmitterOrigin::Propagated) {
            continue;
        }
        const auto& pathSettings =
            invisible_places::water::ResolveWaterSourceSettings(
                emitter,
                runtimeState->water.emitters,
                defaultSourceSettings).path;
        const auto snapped = invisible_places::water::SnapEmitterToCloud(
            *supportCloud,
            emitter.position,
            pathSettings);
        if (!snapped.has_value()) {
            continue;
        }

        WaterEmitter clone = emitter;
        clone.id = NextWaterEmitterId(*runtimeState) + static_cast<std::uint32_t>(propagated.size());
        clone.name = emitter.name + " snapped";
        clone.position = snapped.value();
        clone.origin = WaterEmitterOrigin::Propagated;
        clone.status = WaterEmitterStatus::Accepted;
        clone.parentId = emitter.id;
        clone.radius = std::max(pathSettings.supportVoxelSize * 3.0F, emitter.radius * 0.45F);
        clone.confidence = std::min(0.95F, emitter.confidence);
        propagatedEmitterIds.push_back(clone.id);
        propagated.push_back(std::move(clone));
    }

    if (propagated.empty()) {
        runtimeState->statusMessage = "No emitters were propagated to the active scale.";
        runtimeState->errorMessage.clear();
        return;
    }

    runtimeState->water.nextEmitterId =
        NextWaterEmitterId(*runtimeState) + static_cast<std::uint32_t>(propagated.size());
    runtimeState->water.emitters.insert(
        runtimeState->water.emitters.end(),
        std::make_move_iterator(propagated.begin()),
        std::make_move_iterator(propagated.end()));
    for (const auto emitterId : propagatedEmitterIds) {
        MarkWaterPathDirty(runtimeState, emitterId);
    }
    runtimeState->statusMessage = "Snapped accepted emitters to the active support scene; path bake required.";
    runtimeState->errorMessage.clear();
}

ProjectDocument BuildProjectDocument(const PreviewRuntimeState& runtimeState) {
    ProjectDocument document;
    document.projectName = runtimeState.persistence.projectName;
    const auto projectWindowSize =
        ProjectLiveViewWindowSize(runtimeState.projectSettings);
    document.liveViewWindowWidth =
        static_cast<std::uint32_t>(projectWindowSize.width);
    document.liveViewWindowHeight =
        static_cast<std::uint32_t>(projectWindowSize.height);
    document.lockLiveViewWindowSize =
        runtimeState.projectSettings.lockLiveViewWindowSize;
    document.backgroundColor = runtimeState.projectSettings.backgroundColor;
    document.eyeDomeLightingEnabled = runtimeState.projectSettings.eyeDomeLightingEnabled;
    document.proResAlphaPreviewEnabled = runtimeState.projectSettings.proResAlphaPreviewEnabled;
    document.eyeDomeLightingThickness = runtimeState.projectSettings.eyeDomeLightingThickness;
    document.constantUpdateView = runtimeState.projectSettings.constantUpdateView;
    document.liveVisualEffects = runtimeState.projectSettings.liveVisualEffects;
    document.previewPerformanceMode = runtimeState.projectSettings.previewPerformanceMode;
    document.loadAllScalarFields = runtimeState.projectSettings.loadAllScalarFields;
    document.scalarFieldBudgetGigabytes =
        runtimeState.projectSettings.scalarFieldBudgetGigabytes;
    document.sidePanelPinned = runtimeState.sidePanel.pinned;
    document.showLidarTab = runtimeState.showLidarTab;
    document.showGsplatTab = runtimeState.showGsplatTab;
    document.orbitControlMode = runtimeState.cameraInteraction.orbitControlMode;
    document.autoLowerGsplatQualityWhileNavigating =
        runtimeState.projectSettings.autoLowerGsplatQualityWhileNavigating;
    document.pointCloudPreviewLodMode = PointCloudPreviewLodMode::FullResolution;
    document.interactivePointCap = runtimeState.projectSettings.interactivePointCap;
    document.pointCloudRendererMode = runtimeState.projectSettings.pointCloudRendererMode;
    document.cameraState = runtimeState.camera.CaptureState();
    document.cameraShots = runtimeState.cameraShots;
    for (auto& shot : document.cameraShots) {
        CanonicalizeAssociatedLayerPathsForSceneGroups(runtimeState, &shot.associatedLayerPaths);
    }
    document.cameraPathShotIndices = runtimeState.cameraPanel.pathShotIndices;
    document.cameraPathDurationFrames = runtimeState.cameraPanel.pathDurationFrames;
    document.lastAnimationPath = runtimeState.animationPanel.currentFilePath;
    if (runtimeState.animationPanel.currentPath.has_value() &&
        !runtimeState.animationPanel.currentFilePath.empty()) {
        document.activeAnimationPath =
            runtimeState.animationPanel.currentFilePath;
        document.activeAnimationPosition = std::clamp(
            runtimeState.animationPanel.scrubAmount,
            0.0F,
            1.0F);
    }
    document.hasSavedAnimationRegistry = true;
    for (std::size_t index = 0; index < runtimeState.animationPanel.availableFiles.size(); ++index) {
        auto associatedLayerPaths =
            AnimationRegistryAssociationPaths(runtimeState.animationPanel, index);
        CanonicalizeAssociatedLayerPathsForSceneGroups(runtimeState, &associatedLayerPaths);
        const auto* registryPath = RegistryAnimationPath(
            runtimeState,
            index);
        document.savedAnimations.push_back(
            {.filePath = runtimeState.animationPanel.availableFiles[index],
             .associatedLayerPaths = std::move(associatedLayerPaths),
             .velocityBlendLink =
                 registryPath != nullptr
                     ? registryPath->velocityBlendLink
                     : std::nullopt});
    }
    document.renderJobSettings = RenderSettingsFromExportPreset(
        ViewedExportPreset(runtimeState),
        runtimeState.renderSettings.outputDirectory);
    document.exportPresets = runtimeState.animationPanel.exportPresets;
    document.selectedExportPresetName = runtimeState.animationPanel.selectedExportPresetName;
    document.tempExportPreset = runtimeState.animationPanel.editedExportPreset;
    document.pointVisuals.reserve(runtimeState.pointVisualLibrary.pointVisuals.size());
    for (const auto& visual : runtimeState.pointVisualLibrary.pointVisuals) {
        ProjectLayerDocument::PointVisual visualDocument;
        visualDocument.name = NormalizePointVisualName(visual.name);
        visualDocument.style = visual.style;
        ClearPointCloudStyleShoreline(&visualDocument.style);
        document.pointVisuals.push_back(std::move(visualDocument));
    }
    if (document.pointVisuals.empty()) {
        if (const auto sessionIt = std::find_if(
                runtimeState.sessions.begin(),
                runtimeState.sessions.end(),
                [](const PreviewLayerSession& session) {
                    return IsProjectPointVisualSession(session);
                });
            sessionIt != runtimeState.sessions.end()) {
            auto style = sessionIt->pointStyle;
            ClearPointCloudStyleShoreline(&style);
            document.pointVisuals.push_back(
                {.name = std::string{kDefaultPointVisualName}, .style = style});
        }
    }
    document.selectedPointVisualName =
        runtimeState.pointVisualLibrary.selectedPointVisualName.empty()
            ? std::string{kDefaultPointVisualName}
            : NormalizePointVisualName(runtimeState.pointVisualLibrary.selectedPointVisualName);
    if (document.pointVisuals.empty()) {
        document.pointVisuals.push_back({.name = std::string{kDefaultPointVisualName}, .style = PointCloudStyleState{}});
        document.selectedPointVisualName = std::string{kDefaultPointVisualName};
    }
    document.sceneVisualStates.reserve(runtimeState.pointVisualLibrary.sceneVisualStates.size());
    for (const auto& state : runtimeState.pointVisualLibrary.sceneVisualStates) {
        if (state.sceneGroupName.empty()) {
            continue;
        }
        invisible_places::serialization::ScenePointVisualStateDocument stateDocument;
        stateDocument.sceneGroupName = state.sceneGroupName;
        stateDocument.visual.name = NormalizePointVisualName(state.visual.name);
        stateDocument.visual.style = state.visual.style;
        ClearPointCloudStyleShoreline(&stateDocument.visual.style);
        document.sceneVisualStates.push_back(std::move(stateDocument));
    }
    document.gsplatVisualStyle = runtimeState.projectSettings.gsplatVisualStyle;
    document.waterEmitters = runtimeState.water.emitters;
    document.waterManualFlowPaths = runtimeState.water.manualFlowPaths;
    document.waterSeepageNodes = runtimeState.water.seepageNodes;
    document.waterShorelineDefaultSettings.reset();
    document.waterShorelineProfiles =
        runtimeState.water.shorelineProfiles;
    document.selectedWaterShorelineProfileName.clear();
    document.waterShorelineInstances = runtimeState.water.shorelineInstances;
    document.nextWaterShorelineInstanceId =
        runtimeState.water.nextShorelineInstanceId;
    document.waterSeepageDefaultNodeSettings =
        runtimeState.water.defaultSeepageNodeSettings;
    document.waterSeepageNodeSettingsProfiles =
        WithoutPresetSeepageNodeSettingsProfiles(
            runtimeState.water.seepageNodeSettingsProfiles);
    document.waterSeepageDefaultLook = runtimeState.water.defaultSeepageLook;
    document.waterSeepageLookProfiles = WithoutPresetSeepageLookProfiles(
        runtimeState.water.seepageLookProfiles);
    document.waterSeepageResponseProfiles = WithoutPresetSeepageResponseProfiles(
        runtimeState.water.seepageResponseProfiles);
    document.waterScenarios = runtimeState.water.seepageScenarios;
    document.selectedWaterScenarioId = runtimeState.water.selectedSeepageScenarioId;
    document.waterTimingRuns = runtimeState.water.timingRuns;
    document.waterTimingRunSequence = runtimeState.water.nextTimingRunSequence;
    document.waterFeatureTimingRuns =
        runtimeState.water.featureTimingRunsByScenario;
    document.waterKeyedSettingsProfiles =
        runtimeState.water.keyedSettingsProfiles;
    document.waterRainProfiles = runtimeState.water.rainProfiles;
    document.waterFeatureTimingRunSequence =
        runtimeState.water.nextFeatureTimingRunSequence;
    document.timingTakes = runtimeState.water.timingTakes;
    document.selectedTimingTakeId =
        invisible_places::timing::NormalizeTimingTakeId(
            runtimeState.water.selectedTimingTakeId);
    document.timingTakeStates =
        runtimeState.water.timingTakeSceneStates;
    document.timingColourisePalettes =
        runtimeState.water.savedTimingColourisePalettes;
    document.timingScalarBoundsStores =
        runtimeState.water.timingScalarBoundsStores;
    document.timingTakeSequence =
        runtimeState.water.nextTimingTakeSequence;
    document.timingColourisePaletteSequence =
        runtimeState.water.nextTimingColourisePaletteSequence;
    document.tempWaterScenario = runtimeState.water.editedScenario;
    document.waterFlowTrailSettings = runtimeState.water.flowTrailSettings;
    document.waterShowFlowTrails = runtimeState.water.showFlowTrails;
    document.waterDynamicMeshFlowSettings = runtimeState.water.dynamicMeshFlowSettings;
    document.waterRainSettings = runtimeState.water.collisionRainSettings;
    document.waterRainVisualSettings = runtimeState.water.rainVisual;
    document.activeWaterSceneGroupName =
        runtimeState.water.authoritativeWaterSurfaceSceneGroupName.empty()
            ? runtimeState.water.activeWaterSurfaceSceneGroupName
            : runtimeState.water.authoritativeWaterSurfaceSceneGroupName;
    {
        invisible_places::serialization::WaterSceneStateDocument waterSceneState;
        waterSceneState.sceneGroupName =
            document.activeWaterSceneGroupName.empty()
                ? std::string{"Default"}
                : document.activeWaterSceneGroupName;
        if (document.activeWaterSceneGroupName.empty()) {
            const auto supportIndex =
                ResolveWaterRuntimeSessionIndex(runtimeState);
            if (supportIndex.has_value() &&
                supportIndex.value() < runtimeState.sessions.size()) {
                const auto sceneKey = ProjectVisualSceneKey(
                    runtimeState.sessions[supportIndex.value()]);
                if (!sceneKey.empty()) {
                    waterSceneState.sceneGroupName = sceneKey;
                    document.activeWaterSceneGroupName = sceneKey;
                }
            }
        }
        waterSceneState.emitters = runtimeState.water.emitters;
        waterSceneState.manualFlowPaths = runtimeState.water.manualFlowPaths;
        waterSceneState.seepageNodes = runtimeState.water.seepageNodes;
        waterSceneState.pathCache = CurrentWaterPathCacheForDocument(runtimeState);
        waterSceneState.dynamicMeshPath = runtimeState.water.dynamicMeshFlowSettings.meshPath;
        document.waterSceneStates.push_back(std::move(waterSceneState));
    }
    document.waterSourceSettings = runtimeState.water.defaultSourceSettings;
    document.tempWaterSourceSettings = runtimeState.water.tempDefaultSourceSettings;
    document.waterTrailGeometry = runtimeState.water.defaultTrailGeometry;
    document.waterAnimationTrailSettings = runtimeState.water.defaultAnimationTrailSettings;
    document.tempWaterAnimationTrailSettings = runtimeState.water.tempDefaultAnimationTrailSettings;
    document.waterAnimationTrailProfiles.clear();
    document.waterAnimationTrailProfiles.reserve(runtimeState.water.animationTrailProfiles.size());
    for (const auto& profile : runtimeState.water.animationTrailProfiles) {
        document.waterAnimationTrailProfiles.push_back({
            .name = NormalizeWaterAnimationTrailProfileName(profile.name),
            .settings = profile.settings,
        });
    }
    document.selectedWaterPathProfileName =
        NormalizeWaterProfileName(runtimeState.water.selectedPathProfileName);
    document.selectedWaterLaneProfileName =
        NormalizeWaterProfileName(runtimeState.water.selectedLaneProfileName);
    document.selectedWaterTrailProfileName =
        NormalizeWaterProfileName(runtimeState.water.selectedTrailProfileName);
    document.tempWaterPathProfileSettings = runtimeState.water.editedPathProfileSettings;
    document.tempWaterLaneProfileSettings = runtimeState.water.editedLaneProfileSettings;
    document.waterPathProfiles.reserve(runtimeState.water.pathProfiles.size());
    for (const auto& profile : runtimeState.water.pathProfiles) {
        document.waterPathProfiles.push_back(MakeWaterPathProfileDocument(profile));
    }
    document.waterLaneProfiles.reserve(runtimeState.water.laneProfiles.size());
    for (const auto& profile : runtimeState.water.laneProfiles) {
        document.waterLaneProfiles.push_back(MakeWaterLaneProfileDocument(profile));
    }
    document.waterTrailProfiles.reserve(runtimeState.water.trailProfiles.size());
    for (const auto& profile : runtimeState.water.trailProfiles) {
        document.waterTrailProfiles.push_back(MakeWaterTrailProfileDocument(profile));
    }
    if (runtimeState.water.editedTrailProfile.has_value()) {
        document.tempWaterTrailProfile =
            MakeWaterTrailProfileDocument(runtimeState.water.editedTrailProfile.value());
    }
    if (runtimeState.water.editedDynamicMeshTrailProfile.has_value()) {
        document.tempWaterDynamicMeshTrailProfile =
            MakeWaterTrailProfileDocument(
                runtimeState.water.editedDynamicMeshTrailProfile.value());
    }
    document.waterPointVisualStyle = runtimeState.water.defaultPointVisualStyle;
    document.tempWaterPointVisualStyle = runtimeState.water.tempDefaultPointVisualStyle;
    auto appendWaterProjectVisual = [&document](std::string_view name, const PointCloudStyleState& style) {
        const auto normalized = NormalizePointVisualName(name);
        if (!IsWaterProjectCustomVisualName(normalized)) {
            return;
        }
        const auto existing = std::find_if(
            document.waterPointVisuals.begin(),
            document.waterPointVisuals.end(),
            [&normalized](const ProjectLayerDocument::PointVisual& visual) {
                return NormalizePointVisualName(visual.name) == normalized;
            });
        if (existing != document.waterPointVisuals.end()) {
            return;
        }

        ProjectLayerDocument::PointVisual visual;
        visual.name = normalized;
        visual.style = MakeWaterTrailExportStyle(style);
        document.waterPointVisuals.push_back(std::move(visual));
    };
    for (const auto& visual : runtimeState.water.pointVisuals) {
        appendWaterProjectVisual(visual.name, visual.style);
    }
    document.selectedWaterPointVisualName =
        runtimeState.water.selectedPointVisualName.empty()
            ? std::string{"Water Flow_preset"}
            : NormalizePointVisualName(runtimeState.water.selectedPointVisualName);
    if (document.selectedWaterPointVisualName.empty() ||
        document.selectedWaterPointVisualName == std::string{kDefaultPointVisualName}) {
        document.selectedWaterPointVisualName = "Water Flow_preset";
    } else if (IsEditedPointVisualName(document.selectedWaterPointVisualName)) {
        document.selectedWaterPointVisualName = BasePointVisualName(document.selectedWaterPointVisualName);
    }
    document.waterSettings.path = runtimeState.water.defaultSourceSettings.path;
    document.waterSettings.trail.particleJitter =
        runtimeState.water.defaultSourceSettings.trailShape.particleJitter;
    document.waterSettings.trail.splineAnchorSpacing =
        runtimeState.water.defaultSourceSettings.trailShape.splineAnchorSpacing;
    document.waterSettings.trail.particleDensity =
        runtimeState.water.defaultAnimationTrailSettings.particleDensity;
    document.waterSettings.trail.particleSpeed =
        runtimeState.water.defaultAnimationTrailSettings.particleSpeed;
    document.waterSettings.visual.colorVariation =
        runtimeState.water.defaultAnimationTrailSettings.colorVariation;
    if (runtimeState.water.tempDefaultSourceSettings.has_value() ||
        runtimeState.water.tempDefaultAnimationTrailSettings.has_value()) {
        auto tempBundle = document.waterSettings;
        if (runtimeState.water.tempDefaultSourceSettings.has_value()) {
            tempBundle.path = runtimeState.water.tempDefaultSourceSettings->path;
            tempBundle.trail.particleJitter =
                runtimeState.water.tempDefaultSourceSettings->trailShape.particleJitter;
            tempBundle.trail.splineAnchorSpacing =
                runtimeState.water.tempDefaultSourceSettings->trailShape.splineAnchorSpacing;
        }
        if (runtimeState.water.tempDefaultAnimationTrailSettings.has_value()) {
            tempBundle.trail.particleDensity =
                runtimeState.water.tempDefaultAnimationTrailSettings->particleDensity;
            tempBundle.trail.particleSpeed =
                runtimeState.water.tempDefaultAnimationTrailSettings->particleSpeed;
            tempBundle.visual.colorVariation =
                runtimeState.water.tempDefaultAnimationTrailSettings->colorVariation;
        }
        document.tempWaterSettings = tempBundle;
    }
    document.waterBakeSettings = runtimeState.water.defaultSourceSettings.path;
    document.waterRenderSettings = document.waterSettings;
    document.waterPathCache = CurrentWaterPathCacheForDocument(runtimeState);

    if (runtimeState.selectedSessionIndex.has_value()) {
        const auto& selectedSession =
            runtimeState.sessions[runtimeState.selectedSessionIndex.value()];
        document.selectedLayerPath = selectedSession.sourcePath;
        document.activeSceneGroupName = selectedSession.sceneGroupName;
    }

    document.scenePointCloudGroups.reserve(runtimeState.pointCloudScenes.size());
    for (const auto& scene : runtimeState.pointCloudScenes) {
        invisible_places::serialization::ScenePointCloudGroupDocument groupDocument;
        groupDocument.sceneGroupName = scene.sceneGroupName;
        groupDocument.displaySpacingMeters =
            scene.committedDisplaySpacingMicrometres.has_value()
                ? static_cast<float>(scene.committedDisplaySpacingMicrometres.value()) / 1'000'000.0F
                : 0.0F;
        groupDocument.displayLoaded = scene.displayLoaded;
        groupDocument.displayVisible = scene.displayVisible;
        groupDocument.waterSurfaceCache = scene.waterSurfaceCache;
        for (std::size_t roleIndex = 0;
             roleIndex < invisible_places::scene::kScenePointCloudRoleCount;
             ++roleIndex) {
            const auto role = static_cast<invisible_places::scene::ScenePointCloudRole>(roleIndex);
            invisible_places::serialization::ScenePointCloudRoleSourceDocument roleDocument;
            roleDocument.sceneRole = std::string{invisible_places::scene::ScenePointCloudRoleName(role)};
            if (scene.analysisSessionIndices[roleIndex].has_value()) {
                roleDocument.analysisSourcePath = runtimeState.sessions[
                    scene.analysisSessionIndices[roleIndex].value()].sourcePath;
            }
            if (scene.committedDisplaySessionIndices[roleIndex].has_value()) {
                roleDocument.displaySourcePath = runtimeState.sessions[
                    scene.committedDisplaySessionIndices[roleIndex].value()].sourcePath;
            }
            groupDocument.roleSources.push_back(std::move(roleDocument));
        }
        document.scenePointCloudGroups.push_back(std::move(groupDocument));
    }

    document.layers.reserve(runtimeState.sessions.size());
    for (const auto& session : runtimeState.sessions) {
        if (IsGeneratedWaterOverlaySession(session)) {
            continue;
        }

        ProjectLayerDocument layerDocument;
        layerDocument.kind = session.kind == LayerKind::GaussianSplat
                                 ? invisible_places::serialization::SerializedLayerKind::GaussianSplat
                                 : invisible_places::serialization::SerializedLayerKind::PointCloud;
        layerDocument.sourcePath = session.sourcePath;
        layerDocument.sceneGroupName = session.sceneGroupName;
        layerDocument.sceneRole = session.sceneRole;
        layerDocument.inferredPointSpacingMeters = session.inferredPointSpacingMeters;
        layerDocument.pointSpacingMeters = EffectivePointSpacingMeters(session);
        layerDocument.pointSpacingManualOverride = session.pointSpacingManualOverride;
        layerDocument.scenePrimaryRole = session.scenePrimaryRole;
        layerDocument.selectedSceneVariantPath = session.selectedSceneVariantPath;
        layerDocument.loaded = session.loaded;
        layerDocument.visible = session.visible;
        if (const auto* scene = FindScenePointCloudRuntime(runtimeState, session); scene != nullptr) {
            const auto role = invisible_places::scene::ParseScenePointCloudRole(session.sceneRole);
            if (role.has_value()) {
                const auto roleIndex = invisible_places::scene::ScenePointCloudRoleIndex(role.value());
                if (scene->analysisSessionIndices[roleIndex].has_value()) {
                    layerDocument.selectedSceneVariantPath = runtimeState.sessions[
                        scene->analysisSessionIndices[roleIndex].value()].sourcePath;
                }
            }
            layerDocument.loaded = scene->displayLoaded && session.committedDisplaySource;
            layerDocument.visible = layerDocument.loaded && scene->displayVisible;
        }
        if (session.kind == LayerKind::PointCloud) {
            layerDocument.pointBudgetActivePoints =
                session.kind == LayerKind::PointCloud ? session.totalPrimitives : session.pointBudget.activePoints;
        }
        document.layers.push_back(std::move(layerDocument));
    }

    return document;
}

std::optional<std::size_t> FindSessionIndexBySourcePath(
    const PreviewRuntimeState& runtimeState,
    const std::filesystem::path& sourcePath) {
    for (std::size_t index = 0; index < runtimeState.sessions.size(); ++index) {
        if (PathsReferToSameLocation(
                runtimeState.sessions[index].sourcePath,
                sourcePath)) {
            return index;
        }
    }

    return std::nullopt;
}

std::optional<std::size_t> FindSessionIndexForSceneGroup(
    const PreviewRuntimeState& runtimeState,
    std::string_view sceneGroupName) {
    if (sceneGroupName.empty()) {
        return std::nullopt;
    }

    const auto sceneIt = std::find_if(
        runtimeState.pointCloudScenes.begin(),
        runtimeState.pointCloudScenes.end(),
        [&](const ScenePointCloudRuntime& scene) {
            return scene.sceneGroupName == sceneGroupName;
        });
    if (sceneIt != runtimeState.pointCloudScenes.end()) {
        for (const auto sessionIndex :
             sceneIt->committedDisplaySessionIndices) {
            if (sessionIndex.has_value() &&
                sessionIndex.value() < runtimeState.sessions.size()) {
                return sessionIndex;
            }
        }
        for (const auto sessionIndex : sceneIt->analysisSessionIndices) {
            if (sessionIndex.has_value() &&
                sessionIndex.value() < runtimeState.sessions.size()) {
                return sessionIndex;
            }
        }
    }

    const auto sessionIt = std::find_if(
        runtimeState.sessions.begin(),
        runtimeState.sessions.end(),
        [&](const PreviewLayerSession& session) {
            return session.sceneGroupName == sceneGroupName &&
                   !IsGeneratedWaterOverlaySession(session);
        });
    return sessionIt == runtimeState.sessions.end()
               ? std::nullopt
               : std::optional<std::size_t>{
                     static_cast<std::size_t>(
                         std::distance(
                             runtimeState.sessions.begin(),
                             sessionIt))};
}

void StartQueuedLayerLoadIfIdle(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr ||
        runtimeState->pendingLoad.has_value() ||
        runtimeState->water.waterSurfaceCacheWarmup.worker.joinable() ||
        runtimeState->water.waterSurfaceCachePreprocessPending ||
        runtimeState->persistence.queuedLoads.empty()) {
        return;
    }

    const auto nextLoad = runtimeState->persistence.queuedLoads.front();
    runtimeState->persistence.queuedLoads.erase(runtimeState->persistence.queuedLoads.begin());
    BeginLayerLoad(
        nextLoad.sessionIndex,
        runtimeState,
        nextLoad.purpose,
        nextLoad.sceneSwitchGeneration);
}

const SceneDisplayBundleRuntime* FinestSceneDisplayBundle(
    const ScenePointCloudRuntime& scene) {
    if (scene.displayBundles.empty()) {
        return nullptr;
    }
    return &*std::min_element(
        scene.displayBundles.begin(),
        scene.displayBundles.end(),
        [](const SceneDisplayBundleRuntime& left, const SceneDisplayBundleRuntime& right) {
            if (left.spacingMicrometres != right.spacingMicrometres) {
                return left.spacingMicrometres < right.spacingMicrometres;
            }
            return left.totalPointCount > right.totalPointCount;
        });
}

std::array<std::optional<std::size_t>, invisible_places::scene::kScenePointCloudRoleCount>
SceneFullDensityExportSessionIndices(const ScenePointCloudRuntime& scene) {
    std::array<std::optional<std::size_t>, invisible_places::scene::kScenePointCloudRoleCount>
        indices{};
    if (const auto* finestBundle = FinestSceneDisplayBundle(scene); finestBundle != nullptr) {
        for (std::size_t roleIndex = 0; roleIndex < finestBundle->sessionIndices.size(); ++roleIndex) {
            indices[roleIndex] = finestBundle->sessionIndices[roleIndex];
        }
        return indices;
    }
    return scene.analysisSessionIndices;
}

bool SceneFullDensityExportUsesSession(
    const ScenePointCloudRuntime& scene,
    std::size_t sessionIndex) {
    const auto exportIndices = SceneFullDensityExportSessionIndices(scene);
    return std::any_of(
        exportIndices.begin(),
        exportIndices.end(),
        [&](const std::optional<std::size_t>& candidate) {
            return candidate.has_value() && candidate.value() == sessionIndex;
        });
}

bool IsExportPointCloudSourceCandidate(
    const PreviewRuntimeState& runtimeState,
    std::size_t sessionIndex) {
    if (sessionIndex >= runtimeState.sessions.size()) {
        return false;
    }

    const auto& session = runtimeState.sessions[sessionIndex];
    if (session.kind != LayerKind::PointCloud ||
        IsInactiveLegacyWaterOverlaySession(session)) {
        return false;
    }
    if (!IsSceneGroupedPointCloud(session)) {
        return IsRenderablePointCloudSource(runtimeState, session);
    }

    const auto* scene = FindScenePointCloudRuntime(runtimeState, session);
    if (scene == nullptr || !scene->displayLoaded || !scene->displayVisible) {
        return false;
    }

    // Final exports ignore the live density switch. The viewport can stay on a
    // coarse bundle, while output renders the finest complete scene bundle.
    return SceneFullDensityExportUsesSession(*scene, sessionIndex);
}

bool IsExportPointCloudSourceReady(
    const PreviewRuntimeState& runtimeState,
    std::size_t sessionIndex) {
    if (!IsExportPointCloudSourceCandidate(runtimeState, sessionIndex)) {
        return false;
    }
    const auto& session = runtimeState.sessions[sessionIndex];
    return session.loaded &&
           session.gpuResident &&
           session.offlinePointCloud != nullptr;
}

bool IsGpuAnimationExportPointCloudSourceReady(
    const PreviewRuntimeState& runtimeState,
    std::size_t sessionIndex) {
    if (IsExportPointCloudSourceReady(runtimeState, sessionIndex)) {
        return true;
    }
    if (!IsExportPointCloudSourceCandidate(runtimeState, sessionIndex) ||
        sessionIndex >= runtimeState.sessions.size()) {
        return false;
    }
    const auto& session = runtimeState.sessions[sessionIndex];
    return runtimeState.water.dynamicMeshFlowGpuSessionIndex == sessionIndex &&
           session.dynamicMeshFlowGpuPreview &&
           session.loaded &&
           session.gpuResident &&
           session.totalPrimitives > 0U;
}

bool EnsureFullDensityExportSourcesReady(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    if (runtimeState->water.flowTrailBuildJob.worker.joinable() ||
        runtimeState->water.flowTrailBuildJob.pendingCapture) {
        runtimeState->statusMessage =
            "Finishing the current Flow trail update before export.";
        runtimeState->errorMessage.clear();
        return false;
    }

    for (std::size_t sessionIndex = 0U;
         sessionIndex < runtimeState->sessions.size();
         ++sessionIndex) {
        const auto& session = runtimeState->sessions[sessionIndex];
        if (!session.loaded || !session.waterFlowGpuPreview) {
            continue;
        }
        const auto diagnostics = viewport->WaterFlowGpuSourceState(sessionIndex);
        const auto requestedRevision = std::max(
            diagnostics.requestedRevision,
            session.waterFlowGpuRevision);
        if (diagnostics.pending || requestedRevision == 0U ||
            diagnostics.completedRevision < requestedRevision) {
            runtimeState->statusMessage =
                "Finishing GPU Flow source " +
                std::to_string(session.waterFlowSourceId.value_or(0U)) +
                " before export (revision " +
                std::to_string(diagnostics.completedRevision) + " / " +
                std::to_string(requestedRevision) + ").";
            runtimeState->errorMessage.clear();
            return false;
        }
    }

    const bool needsFlowCpuSnapshot = std::any_of(
        runtimeState->sessions.begin(),
        runtimeState->sessions.end(),
        [](const PreviewLayerSession& session) {
            return session.loaded && session.waterFlowGpuPreview &&
                   (session.offlinePointCloud == nullptr ||
                    session.waterFlowCpuSnapshotRevision < session.waterFlowGpuRevision);
        });
    if (needsFlowCpuSnapshot) {
        if (!QueueWaterFlowCpuExportSnapshot(runtimeState)) {
            runtimeState->errorMessage =
                "The settled GPU Flow output could not queue its CPU export snapshot.";
            runtimeState->statusMessage.clear();
            return false;
        }
        runtimeState->statusMessage =
            "Preparing deterministic CPU Flow snapshots for offline export.";
        runtimeState->errorMessage.clear();
        return false;
    }

    if (runtimeState->pendingLoad.has_value()) {
        runtimeState->statusMessage =
            "Preparing full-density export point clouds; wait for the current layer load to finish.";
        runtimeState->errorMessage.clear();
        return false;
    }

    bool queuedAny = false;
    std::size_t missingSourceCount = 0U;
    for (const auto& scene : runtimeState->pointCloudScenes) {
        if (!scene.displayLoaded || !scene.displayVisible) {
            continue;
        }
        const auto exportIndices = SceneFullDensityExportSessionIndices(scene);
        for (const auto sessionIndex : exportIndices) {
            if (!sessionIndex.has_value() || sessionIndex.value() >= runtimeState->sessions.size()) {
                ++missingSourceCount;
                continue;
            }

            const auto index = sessionIndex.value();
            auto& session = runtimeState->sessions[index];
            if (session.loaded && session.gpuResident && session.offlinePointCloud != nullptr) {
                continue;
            }
            QueueLayerLoad(runtimeState, index, PointCloudLoadPurpose::ExportGpu);
            queuedAny = true;
        }
    }

    if (missingSourceCount > 0U) {
        runtimeState->errorMessage =
            "The full-density export bundle is incomplete for one or more visible scenes.";
        runtimeState->statusMessage.clear();
        return false;
    }

    if (queuedAny) {
        StartQueuedLayerLoadIfIdle(runtimeState);
        runtimeState->statusMessage =
            "Preparing full-density export point clouds; start the export again when loading finishes.";
        runtimeState->errorMessage.clear();
        return false;
    }

    // Every export source is loaded; now every scalar field its authored
    // state references must be resident, so the frozen export renders with
    // the same field data the preview resolves.
    for (const auto& scene : runtimeState->pointCloudScenes) {
        if (!scene.displayLoaded || !scene.displayVisible) {
            continue;
        }
        for (const auto sessionIndex : SceneFullDensityExportSessionIndices(scene)) {
            if (!sessionIndex.has_value() ||
                sessionIndex.value() >= runtimeState->sessions.size()) {
                continue;
            }
            const auto missing = SessionMissingRequiredScalarFieldName(
                *runtimeState,
                runtimeState->sessions[sessionIndex.value()]);
            if (!missing.has_value()) {
                continue;
            }
            if (!runtimeState->pendingScalarFieldLoad.has_value()) {
                StartScalarFieldLoad(
                    runtimeState,
                    sessionIndex.value(),
                    missing.value());
            }
            runtimeState->statusMessage =
                "Loading scalar field '" + missing.value() +
                "' for export; start the export again when loading finishes.";
            runtimeState->errorMessage.clear();
            return false;
        }
    }
    return true;
}

struct ExportSourceReleaseSummary {
    std::size_t gpuSessionCount = 0U;
    std::size_t cpuSessionCount = 0U;
    std::size_t retainedAnalysisCpuSessionCount = 0U;
    std::string warning;
};

ExportSourceReleaseSummary ReleaseExportOnlyPointCloudSources(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    ExportSourceReleaseSummary summary;
    if (runtimeState == nullptr || viewport == nullptr) {
        return summary;
    }

    // Finest-density scene roles can be loaded and uploaded solely for an
    // export while the viewport continues to show a coarser committed bundle.
    // Reuse them throughout one batch, then retire only sessions with no live
    // display owner. Analysis sources keep their CPU payload because Shoreline,
    // Seepage, Rain, and Flow may still use it; their export-only GPU copy is
    // safe to release. The shared WaterSurfaceCache is independent and remains
    // warm.
    std::vector<std::size_t> releaseIndices;
    for (const auto& scene : runtimeState->pointCloudScenes) {
        for (const auto sessionIndex :
             SceneFullDensityExportSessionIndices(scene)) {
            if (!sessionIndex.has_value() ||
                sessionIndex.value() >= runtimeState->sessions.size() ||
                std::find(
                    releaseIndices.begin(),
                    releaseIndices.end(),
                    sessionIndex.value()) != releaseIndices.end()) {
                continue;
            }
            const auto& session =
                runtimeState->sessions[sessionIndex.value()];
            if (session.committedDisplaySource ||
                session.pendingDisplaySource) {
                continue;
            }
            const bool hasExportOnlyGpuCopy =
                session.gpuResident || session.loaded;
            const bool hasUnownedCpuCopy =
                session.cpuResident && !session.analysisSource;
            if (hasExportOnlyGpuCopy || hasUnownedCpuCopy) {
                releaseIndices.push_back(sessionIndex.value());
            }
        }
    }
    if (releaseIndices.empty()) {
        return summary;
    }

    const bool hasGpuResources = std::any_of(
        releaseIndices.begin(),
        releaseIndices.end(),
        [&](std::size_t index) {
            return runtimeState->sessions[index].gpuResident ||
                   runtimeState->sessions[index].loaded;
        });
    std::optional<PointCloudMutationBatchScope> mutationBatch;
    try {
        // Removing all role buffers under one resource mutation avoids a
        // separate device settle for ROCK, SAND, and VEG.
        if (hasGpuResources) {
            mutationBatch.emplace(viewport);
        }
        for (const auto index : releaseIndices) {
            auto& session = runtimeState->sessions[index];
            const bool hadGpuResources =
                session.gpuResident || session.loaded;
            const bool hadCpuResources = session.cpuResident;
            const bool releaseCpuResources = !session.analysisSource;
            UnloadLayerByIndex(
                runtimeState,
                viewport,
                index,
                releaseCpuResources);
            if (hadGpuResources &&
                !session.gpuResident && !session.loaded) {
                ++summary.gpuSessionCount;
            }
            if (hadCpuResources && releaseCpuResources &&
                !session.cpuResident) {
                ++summary.cpuSessionCount;
            } else if (hadCpuResources && !releaseCpuResources &&
                       session.cpuResident) {
                ++summary.retainedAnalysisCpuSessionCount;
            }
        }
        if (mutationBatch.has_value()) {
            mutationBatch->Finish();
        }
        if (summary.gpuSessionCount > 0U) {
            runtimeState->previewRenderStateSignatureValid = false;
        }
        std::cout
            << "Released export-only point-cloud residency: "
            << summary.gpuSessionCount << " GPU session(s), "
            << summary.cpuSessionCount << " unowned CPU session(s); retained "
            << summary.retainedAnalysisCpuSessionCount
            << " analysis CPU session(s)." << std::endl;
    } catch (const std::exception& error) {
        summary.warning =
            "Could not fully release export-only point-cloud resources: " +
            std::string{error.what()};
    }
    return summary;
}

void StopBackgroundWorkForShutdown(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }

    runtimeState->persistence.queuedLoads.clear();
    if (runtimeState->offlineRenderJob.active) {
        std::cout << "Requesting animation export shutdown..." << std::endl;
        runtimeState->offlineRenderJob.cancelRequested = true;
        RequestAnimationExportWriterCancellation(&runtimeState->offlineRenderJob);
        if (runtimeState->offlineRenderJob.worker.joinable()) {
            runtimeState->offlineRenderJob.worker = std::jthread{};
        }
    }
    runtimeState->exportPowerAssertion.Reset();
    if (runtimeState->water.flowTrailBuildJob.worker.joinable()) {
        runtimeState->water.flowTrailBuildJob.worker.request_stop();
        runtimeState->water.flowTrailBuildJob.worker = std::jthread{};
    }
    runtimeState->water.flowTrailBuildJob.pendingCapture = false;
    CancelWaterSurfaceCacheWarmup(&runtimeState->water);
    auto& histogramJob =
        runtimeState->timingColouriseHistogram;
    histogramJob.pendingBatch.reset();
    if (histogramJob.worker.joinable()) {
        histogramJob.worker.request_stop();
        histogramJob.worker = std::jthread{};
    }
    histogramJob.shared.reset();
    histogramJob.activeBatchId.clear();
    if (runtimeState->animationVelocityPreviewJob.worker.joinable()) {
        runtimeState->animationVelocityPreviewJob.worker.request_stop();
        runtimeState->animationVelocityPreviewJob.worker = std::jthread{};
    }
    runtimeState->animationVelocityPreviewJob.shared.reset();
    if (runtimeState->animationStrongAlignmentJob.worker.joinable()) {
        runtimeState->animationStrongAlignmentJob.worker.request_stop();
        runtimeState->animationStrongAlignmentJob.worker = std::jthread{};
    }
    runtimeState->animationStrongAlignmentJob.shared.reset();
    if (runtimeState->animationMatchingFrameGhostJob.worker.joinable()) {
        runtimeState->animationMatchingFrameGhostJob.worker.request_stop();
        runtimeState->animationMatchingFrameGhostJob.worker = std::jthread{};
    }
    runtimeState->animationMatchingFrameGhostJob.shared.reset();
    runtimeState->animationMatchingFrameGhostJob.sourceCache.reset();

    if (runtimeState->pendingScalarFieldLoad.has_value()) {
        std::cout
            << "Waiting for background scalar-field load to finish before shutdown..."
            << std::endl;
        runtimeState->pendingScalarFieldLoad->backgroundThread.request_stop();
        runtimeState->pendingScalarFieldLoad.reset();
    }

    if (runtimeState->pendingLoad.has_value()) {
        std::cout
            << "Waiting for background layer load to finish before shutdown..."
            << std::endl;
        runtimeState->pendingLoad->backgroundThread.request_stop();
        runtimeState->pendingLoad.reset();
    }
}

const invisible_places::serialization::ScenePointCloudRoleSourceDocument*
FindSceneRoleSourceDocument(
    const invisible_places::serialization::ScenePointCloudGroupDocument& groupDocument,
    invisible_places::scene::ScenePointCloudRole role) {
    const auto roleName = invisible_places::scene::ScenePointCloudRoleName(role);
    const auto it = std::find_if(
        groupDocument.roleSources.begin(),
        groupDocument.roleSources.end(),
        [&](const invisible_places::serialization::ScenePointCloudRoleSourceDocument& source) {
            return NormalizeSceneRoleName(source.sceneRole) == NormalizeSceneRoleName(roleName);
        });
    return it == groupDocument.roleSources.end() ? nullptr : &*it;
}

void ReleaseScenePointCloudResidency(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    ScenePointCloudRuntime* scene) {
    if (runtimeState == nullptr || viewport == nullptr || scene == nullptr) {
        return;
    }
    const auto sceneFolderKey = NormalizePathKey(scene->sourceFolder);
    for (std::size_t index = 0; index < runtimeState->sessions.size(); ++index) {
        auto& session = runtimeState->sessions[index];
        if (!IsSceneGroupedPointCloud(session) ||
            NormalizePathKey(session.sourcePath.parent_path()) != sceneFolderKey) {
            continue;
        }
        session.committedDisplaySource = false;
        session.pendingDisplaySource = false;
        if (session.gpuResident || session.cpuResident) {
            UnloadLayerByIndex(runtimeState, viewport, index, true);
        }
    }
    std::erase_if(
        runtimeState->persistence.queuedLoads,
        [&](const QueuedLayerLoad& load) {
            return load.sessionIndex < runtimeState->sessions.size() &&
                   IsSceneGroupedPointCloud(runtimeState->sessions[load.sessionIndex]) &&
                   NormalizePathKey(
                       runtimeState->sessions[load.sessionIndex].sourcePath.parent_path()) == sceneFolderKey;
        });
    scene->displayLoaded = false;
    scene->pendingDisplaySessionIndices = {};
    scene->pendingDisplaySpacingMicrometres.reset();
    scene->pendingMixedDisplay = false;
    scene->stagedReadyCount = 0U;

    runtimeState->water.activeSupportSessionIndex.reset();
    runtimeState->water.combinedSupportCloud.reset();
    runtimeState->water.combinedSupportSignature.clear();
    runtimeState->water.trailSurfaceIndex.reset();
    runtimeState->water.trailSurfaceIndexSupportSignature.clear();
    runtimeState->water.trailSurfaceIndexSupportPath.clear();
}

bool ApplyScenePointCloudGroupDocuments(
    const ProjectDocument& document,
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }

    bool requestedAnyDisplay = false;
    for (auto& scene : runtimeState->pointCloudScenes) {
        const auto groupIt = std::find_if(
            document.scenePointCloudGroups.begin(),
            document.scenePointCloudGroups.end(),
            [&](const invisible_places::serialization::ScenePointCloudGroupDocument& group) {
                if (group.sceneGroupName != scene.sceneGroupName) {
                    return false;
                }
                const bool hasFolderQualifiedPath = std::any_of(
                    group.roleSources.begin(),
                    group.roleSources.end(),
                    [&](const invisible_places::serialization::ScenePointCloudRoleSourceDocument& source) {
                        return (!source.analysisSourcePath.empty() &&
                                PathsReferToSameLocation(
                                    source.analysisSourcePath.parent_path(),
                                    scene.sourceFolder)) ||
                               (!source.displaySourcePath.empty() &&
                                PathsReferToSameLocation(
                                    source.displaySourcePath.parent_path(),
                                    scene.sourceFolder));
                    });
                const bool hasAnySourcePath = std::any_of(
                    group.roleSources.begin(),
                    group.roleSources.end(),
                    [](const invisible_places::serialization::ScenePointCloudRoleSourceDocument& source) {
                        return !source.analysisSourcePath.empty() || !source.displaySourcePath.empty();
                    });
                return hasFolderQualifiedPath || !hasAnySourcePath;
            });
        if (groupIt == document.scenePointCloudGroups.end()) {
            ReleaseScenePointCloudResidency(runtimeState, viewport, &scene);
            continue;
        }

        for (auto& session : runtimeState->sessions) {
            if (IsSceneGroupedPointCloud(session) &&
                PathsReferToSameLocation(
                    session.sourcePath.parent_path(),
                    scene.sourceFolder)) {
                session.analysisSource = false;
            }
        }
        for (std::size_t roleIndex = 0;
             roleIndex < invisible_places::scene::kScenePointCloudRoleCount;
             ++roleIndex) {
            const auto role = static_cast<invisible_places::scene::ScenePointCloudRole>(roleIndex);
            const auto* roleDocument = FindSceneRoleSourceDocument(*groupIt, role);
            auto analysisIndex = scene.analysisSessionIndices[roleIndex];
            if (roleDocument != nullptr && !roleDocument->analysisSourcePath.empty()) {
                const auto savedIndex = SessionIndexForSourcePath(
                    runtimeState->sessions,
                    roleDocument->analysisSourcePath);
                if (savedIndex.has_value() &&
                    PathsReferToSameLocation(
                        runtimeState->sessions[savedIndex.value()].sourcePath.parent_path(),
                        scene.sourceFolder)) {
                    analysisIndex = savedIndex;
                } else {
                    scene.switchError = "Saved analysis source is missing; using the canonical scene source where available.";
                }
            }
            scene.analysisSessionIndices[roleIndex] = analysisIndex;
            if (analysisIndex.has_value()) {
                auto& analysisSession = runtimeState->sessions[analysisIndex.value()];
                analysisSession.analysisSource = true;
                for (auto& session : runtimeState->sessions) {
                    if (IsSceneGroupedPointCloud(session) &&
                        PathsReferToSameLocation(
                            session.sourcePath.parent_path(),
                            scene.sourceFolder) &&
                        NormalizeSceneRoleName(session.sceneRole) ==
                            NormalizeSceneRoleName(analysisSession.sceneRole)) {
                        session.selectedSceneVariantPath = analysisSession.sourcePath;
                    }
                }
            }
        }

        scene.displayVisible = groupIt->displayVisible;
        scene.waterSurfaceCache = groupIt->waterSurfaceCache;
        scene.waterSurfaceCacheStatus = InitialWaterSurfaceCacheStatus(
            *runtimeState,
            scene);
        const bool shouldLoadDisplay = groupIt->displayLoaded;

        const SceneDisplayBundleRuntime* desiredBundle = nullptr;
        const auto savedSpacing = invisible_places::scene::QuantizePointSpacingMicrometres(
            groupIt->displaySpacingMeters);
        if (savedSpacing.has_value()) {
            desiredBundle = FindSceneDisplayBundle(scene, savedSpacing.value());
        }
        if (desiredBundle == nullptr) {
            for (const auto& bundle : scene.displayBundles) {
                bool pathsMatch = true;
                for (std::size_t roleIndex = 0;
                     roleIndex < invisible_places::scene::kScenePointCloudRoleCount;
                     ++roleIndex) {
                    const auto role = static_cast<invisible_places::scene::ScenePointCloudRole>(roleIndex);
                    const auto* roleDocument = FindSceneRoleSourceDocument(*groupIt, role);
                    pathsMatch &= roleDocument != nullptr &&
                                  !roleDocument->displaySourcePath.empty() &&
                                  PathsReferToSameLocation(
                                      roleDocument->displaySourcePath,
                                      runtimeState->sessions[bundle.sessionIndices[roleIndex]].sourcePath);
                }
                if (pathsMatch) {
                    desiredBundle = &bundle;
                    break;
                }
            }
        }
        if (desiredBundle == nullptr && !scene.displayBundles.empty()) {
            desiredBundle = &*std::min_element(
                scene.displayBundles.begin(),
                scene.displayBundles.end(),
                [&](const SceneDisplayBundleRuntime& left, const SceneDisplayBundleRuntime& right) {
                    if (!savedSpacing.has_value()) {
                        return left.spacingMicrometres < right.spacingMicrometres;
                    }
                    const auto leftDistance = left.spacingMicrometres > savedSpacing.value()
                                                  ? left.spacingMicrometres - savedSpacing.value()
                                                  : savedSpacing.value() - left.spacingMicrometres;
                    const auto rightDistance = right.spacingMicrometres > savedSpacing.value()
                                                   ? right.spacingMicrometres - savedSpacing.value()
                                                   : savedSpacing.value() - right.spacingMicrometres;
                    return leftDistance != rightDistance
                               ? leftDistance < rightDistance
                               : left.spacingMicrometres < right.spacingMicrometres;
                });
            scene.switchError = "Saved display density is unavailable; selected the nearest complete bundle.";
        }

        if (desiredBundle == nullptr) {
            std::array<std::optional<std::size_t>, invisible_places::scene::kScenePointCloudRoleCount>
                mixedDisplayIndices{};
            for (std::size_t roleIndex = 0;
                 roleIndex < invisible_places::scene::kScenePointCloudRoleCount;
                 ++roleIndex) {
                const auto role = static_cast<invisible_places::scene::ScenePointCloudRole>(roleIndex);
                const auto* roleDocument = FindSceneRoleSourceDocument(*groupIt, role);
                if (roleDocument != nullptr && !roleDocument->displaySourcePath.empty()) {
                    mixedDisplayIndices[roleIndex] = SessionIndexForSourcePath(
                        runtimeState->sessions,
                        roleDocument->displaySourcePath);
                }
                if (!mixedDisplayIndices[roleIndex].has_value()) {
                    mixedDisplayIndices[roleIndex] = scene.analysisSessionIndices[roleIndex];
                }
            }
            scene.mixedDisplay = true;
            scene.switchError = "No complete ROCK/SAND/VEG display bundle is available; the saved mixed set is not switchable.";
            if (!shouldLoadDisplay) {
                ReleaseScenePointCloudResidency(runtimeState, viewport, &scene);
                scene.committedDisplaySessionIndices = mixedDisplayIndices;
                scene.committedDisplaySpacingMicrometres.reset();
                scene.mixedDisplay = true;
                continue;
            }
            requestedAnyDisplay |= RequestSceneMixedDisplayLoad(
                runtimeState,
                viewport,
                &scene,
                mixedDisplayIndices);
            continue;
        }

        if (!shouldLoadDisplay) {
            ReleaseScenePointCloudResidency(runtimeState, viewport, &scene);
            for (std::size_t roleIndex = 0;
                 roleIndex < invisible_places::scene::kScenePointCloudRoleCount;
                 ++roleIndex) {
                scene.committedDisplaySessionIndices[roleIndex] =
                    desiredBundle->sessionIndices[roleIndex];
            }
            scene.committedDisplaySpacingMicrometres = desiredBundle->spacingMicrometres;
            scene.mixedDisplay = false;
            continue;
        }

        requestedAnyDisplay |= RequestSceneDisplaySwitch(
            runtimeState,
            viewport,
            &scene,
            desiredBundle->spacingMicrometres);
    }
    return requestedAnyDisplay;
}

bool ApplyProjectDocumentToRuntime(
    const ProjectDocument& sourceDocument,
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }

    if (runtimeState->pendingLoad.has_value()) {
        runtimeState->statusMessage = "Please wait for the current layer to finish loading before loading a project.";
        return false;
    }

    auto document = sourceDocument;
    invisible_places::app::workspace::ResolveProjectDocument(
        &document,
        WorkspaceRoots(*runtimeState));

    // Project application is a full context switch. Clear the previous
    // animation before water/profile state is synchronized, then restore the
    // persisted animation only after its project-owned libraries are ready.
    runtimeState->animationPlayback.active = false;
    runtimeState->animationPanel.currentPath.reset();
    runtimeState->animationPanel.currentFilePath.clear();
    runtimeState->animationPanel.currentPathUsesEdited = false;
    runtimeState->animationPanel.selectedFileUsesEdited = false;
    runtimeState->animationPanel.selectedFileIndex.reset();
    runtimeState->animationPanel.selectedKeyIndex.reset();
    runtimeState->animationPanel.scrubAmount = 0.0F;
    runtimeState->animationPanel.timelineViewRange = {};
    runtimeState->animationPanel.timelineViewDrag.reset();
    runtimeState->animationPanel.dirty = false;
    if (runtimeState->animationMatchingFrameGhostJob.worker.joinable()) {
        runtimeState->animationMatchingFrameGhostJob.worker.request_stop();
        runtimeState->animationMatchingFrameGhostJob.worker =
            std::jthread{};
    }
    runtimeState->animationMatchingFrameGhostJob.shared.reset();
    runtimeState->animationMatchingFrameGhostJob.sourceCache.reset();
    viewport->RemovePointCloud(kAnimationMatchingFrameGhostLayerId);
    runtimeState->animationPanel.matchingFrameGhost = {};
    runtimeState->animationPanel.requestedMatchingFrameGhostCapture.reset();
    runtimeState->animationPanel.requestedMatchingFrameGhostClear = false;
    runtimeState->animationPanel.requestedFixedLensNormalization.reset();

    CancelWaterFlowTrailBuildJob(&runtimeState->water);
    runtimeState->water.flowTrailSourceRequests.clear();
    runtimeState->water.flowTrailSourceArtifacts.clear();

    runtimeState->projectSettings.backgroundColor = document.backgroundColor;
    runtimeState->projectSettings.liveViewWindowWidth =
        static_cast<int>(std::min<std::uint32_t>(
            document.liveViewWindowWidth,
            static_cast<std::uint32_t>(
                kMaximumLiveViewWindowDimension)));
    runtimeState->projectSettings.liveViewWindowHeight =
        static_cast<int>(std::min<std::uint32_t>(
            document.liveViewWindowHeight,
            static_cast<std::uint32_t>(
                kMaximumLiveViewWindowDimension)));
    const auto projectWindowSize =
        ProjectLiveViewWindowSize(runtimeState->projectSettings);
    runtimeState->projectSettings.liveViewWindowWidth =
        projectWindowSize.width;
    runtimeState->projectSettings.liveViewWindowHeight =
        projectWindowSize.height;
    runtimeState->projectSettings.lockLiveViewWindowSize =
        document.lockLiveViewWindowSize;
    runtimeState->pendingLiveViewWindowSize.reset();
    if (runtimeState->projectSettings.lockLiveViewWindowSize) {
        runtimeState->pendingLiveViewWindowSize = projectWindowSize;
    }
    runtimeState->projectSettings.eyeDomeLightingEnabled = document.eyeDomeLightingEnabled;
    runtimeState->projectSettings.proResAlphaPreviewEnabled = document.proResAlphaPreviewEnabled;
    runtimeState->projectSettings.eyeDomeLightingThickness =
        std::clamp(document.eyeDomeLightingThickness, 1.0F, 24.0F);
    runtimeState->projectSettings.constantUpdateView = document.constantUpdateView;
    runtimeState->projectSettings.liveVisualEffects = document.liveVisualEffects;
    runtimeState->projectSettings.previewPerformanceMode = document.previewPerformanceMode;
    runtimeState->projectSettings.loadAllScalarFields = document.loadAllScalarFields;
    runtimeState->projectSettings.scalarFieldBudgetGigabytes =
        std::max(0.0F, document.scalarFieldBudgetGigabytes);
    runtimeState->sidePanel.pinned = document.sidePanelPinned;
    runtimeState->showLidarTab = document.showLidarTab;
    runtimeState->showGsplatTab = document.showGsplatTab;
    runtimeState->cameraInteraction.orbitControlMode = document.orbitControlMode;
    runtimeState->cameraInteraction.trackballOrbitActive = false;
    runtimeState->projectSettings.autoLowerGsplatQualityWhileNavigating =
        document.autoLowerGsplatQualityWhileNavigating;
    runtimeState->projectSettings.gsplatVisualStyle = document.gsplatVisualStyle;
    runtimeState->pointVisualLibrary.pointVisuals.clear();
    runtimeState->pointVisualLibrary.pointVisuals.reserve(document.pointVisuals.size());
    for (const auto& visualDocument : document.pointVisuals) {
        runtimeState->pointVisualLibrary.pointVisuals.push_back({
            .name = NormalizePointVisualName(visualDocument.name),
            .style = visualDocument.style,
        });
    }
    runtimeState->pointVisualLibrary.selectedPointVisualName =
        NormalizePointVisualName(document.selectedPointVisualName);
    runtimeState->pointVisualLibrary.pointVisualNameBuffer =
        BasePointVisualName(runtimeState->pointVisualLibrary.selectedPointVisualName);
    runtimeState->pointVisualLibrary.sceneVisualStates.clear();
    runtimeState->pointVisualLibrary.sceneVisualStates.reserve(document.sceneVisualStates.size());
    for (const auto& stateDocument : document.sceneVisualStates) {
        if (stateDocument.sceneGroupName.empty()) {
            continue;
        }
        runtimeState->pointVisualLibrary.sceneVisualStates.push_back({
            .sceneGroupName = stateDocument.sceneGroupName,
            .visual = {
                .name = NormalizePointVisualName(stateDocument.visual.name),
                .style = stateDocument.visual.style,
            },
        });
    }
    EnsureProjectPointVisuals(runtimeState);
    runtimeState->projectSettings.pointCloudPreviewLodMode = PointCloudPreviewLodMode::FullResolution;
    runtimeState->projectSettings.interactivePointCap = document.interactivePointCap;
    runtimeState->projectSettings.pointCloudRendererMode = document.pointCloudRendererMode;
    auto renderSettings = document.renderJobSettings;
    if (renderSettings.outputDirectory.empty() && !runtimeState->renderSettings.outputDirectory.empty()) {
        renderSettings.outputDirectory = runtimeState->renderSettings.outputDirectory;
    }
    runtimeState->renderSettings = renderSettings;
    runtimeState->animationPanel.exportPresets = document.exportPresets;
    runtimeState->animationPanel.selectedExportPresetName =
        document.selectedExportPresetName.empty()
            ? std::string{invisible_places::output::kMp4PresetName}
            : document.selectedExportPresetName;
    runtimeState->animationPanel.editedExportPreset = document.tempExportPreset;
    runtimeState->animationPanel.exportPresetNameBuffer =
        invisible_places::output::BaseExportPresetName(
            runtimeState->animationPanel.selectedExportPresetName);
    EnsureExportPresets(runtimeState);
    ApplyActiveExportPresetToRenderSettings(runtimeState);
    runtimeState->water.emitters = document.waterEmitters;
    runtimeState->water.manualFlowPaths = document.waterManualFlowPaths;
    runtimeState->water.seepageNodes = document.waterSeepageNodes;
    std::optional<PointCloudShorelineWaveSettings>
        legacyPrimaryShoreline;
    if (const auto selectedStyle = ProjectPointVisualStyleByName(
            runtimeState->pointVisualLibrary,
            runtimeState->pointVisualLibrary.selectedPointVisualName);
        selectedStyle.has_value()) {
        const auto settings =
            invisible_places::renderer::pointcloud::
                ExtractPointCloudShorelineWaveSettings(
                    selectedStyle.value());
        const bool legacyOwnership =
            document.sourceSchemaVersion <
            invisible_places::serialization::
                kWaterOwnedShorelineProjectSchemaVersion;
        if (legacyOwnership && settings.enabled) {
            legacyPrimaryShoreline = settings;
        }
    }
    runtimeState->water.shorelineProfiles =
        document.waterShorelineProfiles;
    runtimeState->water.shorelineInstances = document.waterShorelineInstances;
    runtimeState->water.nextShorelineInstanceId = std::max(
        document.nextWaterShorelineInstanceId,
        NextAvailableShorelineInstanceId(
            runtimeState->water.shorelineInstances));
    runtimeState->water.selectedShorelineInstanceIndex.reset();
    runtimeState->water.selectedShorelineProfileName =
        NormalizeWaterShorelineProfileName(
            document.selectedWaterShorelineProfileName);
    NormalizeWaterShorelineState(
        &runtimeState->water,
        legacyPrimaryShoreline);
    ClearWaterShorelineFromSavedVisuals(runtimeState);
    runtimeState->water.defaultSeepageNodeSettings =
        document.waterSeepageDefaultNodeSettings;
    runtimeState->water.seepageNodeSettingsProfiles =
        document.waterSeepageNodeSettingsProfiles;
    runtimeState->water.defaultSeepageLook = document.waterSeepageDefaultLook;
    runtimeState->water.seepageLookProfiles = document.waterSeepageLookProfiles;
    runtimeState->water.seepageResponseProfiles =
        document.waterSeepageResponseProfiles;
    MigrateLegacyWaterSeepageLooks(
        &runtimeState->water,
        !document.waterSeepageResponseProfiles.empty());
    MigrateLegacyWaterSeepageNodeSettings(&runtimeState->water);
    SeedWaterSeepageProfilePresets(&runtimeState->water);
    runtimeState->water.seepageScenarios = document.waterScenarios.empty()
        ? invisible_places::water::DefaultWaterScenarioDefinitions()
        : document.waterScenarios;
    runtimeState->water.selectedSeepageScenarioId = document.selectedWaterScenarioId;
    runtimeState->water.timingRuns = document.waterTimingRuns;
    runtimeState->water.nextTimingRunSequence = document.waterTimingRunSequence;
    runtimeState->water.featureTimingRunsByScenario =
        document.waterFeatureTimingRuns;
    runtimeState->water.keyedSettingsProfiles =
        document.waterKeyedSettingsProfiles;
    runtimeState->water.nextFeatureTimingRunSequence =
        document.waterFeatureTimingRunSequence;
    runtimeState->water.timingTakeSceneStates =
        document.timingTakeStates;
    // After nodes, profiles, legacy tracks, canonical Timing Take states, and
    // keyed packages are all loaded so reconciliation can rewrite every
    // reference kind.
    ReconcileWaterSeepageObjectProfiles(&runtimeState->water);
    runtimeState->water.timingTakes = document.timingTakes;
    runtimeState->water.rainProfiles = document.waterRainProfiles;
    runtimeState->water.selectedTimingTakeId =
        invisible_places::timing::NormalizeTimingTakeId(
            document.selectedTimingTakeId);
    runtimeState->water.savedTimingColourisePalettes =
        document.timingColourisePalettes;
    runtimeState->water.timingScalarBoundsStores =
        document.timingScalarBoundsStores;
    runtimeState->water.nextTimingTakeSequence =
        document.timingTakeSequence;
    runtimeState->water.nextTimingColourisePaletteSequence =
        document.timingColourisePaletteSequence;
    runtimeState->water.editedScenario = document.tempWaterScenario;
    if (runtimeState->water.editedScenario.has_value() &&
        FindWaterScenarioDefinition(
            runtimeState->water,
            runtimeState->water.editedScenario->id) == nullptr) {
        runtimeState->water.editedScenario.reset();
    }
    runtimeState->timingsPanel = TimingsPanelState{};
    RecompileWaterTimingTracksForAnimation(runtimeState);
    runtimeState->water.flowTrailSettings = document.waterFlowTrailSettings;
    runtimeState->water.showFlowTrails = document.waterShowFlowTrails;
    runtimeState->water.defaultTrailGeometry = document.waterTrailGeometry;
    runtimeState->water.dynamicMeshFlowSettings =
        invisible_places::water::SanitizeWaterDynamicMeshFlowSettings(
            document.waterDynamicMeshFlowSettings);
    runtimeState->water.dynamicMeshFlowSettings.trailProfileName =
        NormalizeWaterProfileName(runtimeState->water.dynamicMeshFlowSettings.trailProfileName);
    runtimeState->water.dynamicMeshFlowSettings.particlePresetName = std::string{
        invisible_places::water::NormalizeWaterDynamicMeshParticlePresetName(
            runtimeState->water.dynamicMeshFlowSettings.particlePresetName)};
    runtimeState->water.dynamicMeshTrailProfileNameBuffer =
        BaseWaterProfileName(runtimeState->water.dynamicMeshFlowSettings.trailProfileName);
    // Schema-45 Mesh Flow has no authored attractor/source interaction.
    // Loading a project also clears any legacy in-memory placement state so
    // ordinary Flow emitters remain the only source markers handled by the
    // reachable viewport UI.
    runtimeState->water.selectedDynamicMeshAttractorIndex.reset();
    runtimeState->water.movingDynamicMeshAttractorIndex.reset();
    runtimeState->water.dynamicMeshAttractorPlacementArmed = false;
    runtimeState->water.activeWaterSurfaceSceneGroupName =
        document.activeWaterSceneGroupName;
    runtimeState->water.authoritativeWaterSurfaceSceneGroupName =
        document.activeWaterSceneGroupName;
    runtimeState->water.dynamicMeshFlowGpuSessionIndex.reset();
    runtimeState->water.dynamicMeshFlowLastUpdateSeconds = 0.0F;
    runtimeState->water.dynamicMeshFlowResetRequested = true;
    runtimeState->water.dynamicMeshFlowAllocationRevision = 0U;
    runtimeState->water.dynamicMeshFlowParameterRevision = 0U;
    runtimeState->water.dynamicMeshFlowDescriptorGeneration = 0U;
    runtimeState->water.dynamicMeshFlowDispatchCount = 0U;
    runtimeState->water.dynamicMeshFlowSharedGroundUploadRevision = 0U;
    runtimeState->water.dynamicMeshFlowContactEventCount = 0U;
    runtimeState->water.dynamicMeshSurfaceCache.reset();
    runtimeState->water.dynamicMeshSurfaceCachePath.clear();
    runtimeState->water.dynamicMeshSurfaceCacheSignature.clear();
    runtimeState->water.collisionRainSettings = document.waterRainSettings;
    runtimeState->water.rainVisual = document.waterRainVisualSettings;
    runtimeState->water.liveRainTimingTakeId.clear();
    runtimeState->water.liveRainProfileId.clear();
    runtimeState->water.rainProfileNameBufferBaseId.clear();
    EnsureWaterRainProfiles(&runtimeState->water);
    runtimeState->water.flowOverlay = {};
    runtimeState->water.flowTrailOverlay = {};
    runtimeState->water.defaultSourceSettings = document.waterSourceSettings;
    runtimeState->water.tempDefaultSourceSettings = document.tempWaterSourceSettings;
    runtimeState->water.defaultAnimationTrailSettings = document.waterAnimationTrailSettings;
    runtimeState->water.tempDefaultAnimationTrailSettings = document.tempWaterAnimationTrailSettings;
    runtimeState->water.animationTrailProfiles.clear();
    runtimeState->water.animationTrailProfiles.reserve(document.waterAnimationTrailProfiles.size());
    for (const auto& profile : document.waterAnimationTrailProfiles) {
        runtimeState->water.animationTrailProfiles.push_back({
            .name = NormalizeWaterAnimationTrailProfileName(profile.name),
            .settings = profile.settings,
        });
    }
    EnsureWaterAnimationTrailProfiles(&runtimeState->water);
    runtimeState->water.defaultPointVisualStyle = document.waterPointVisualStyle;
    runtimeState->water.tempDefaultPointVisualStyle = document.tempWaterPointVisualStyle;
    runtimeState->water.pathProfiles.clear();
    runtimeState->water.pathProfiles.reserve(document.waterPathProfiles.size());
    for (const auto& profile : document.waterPathProfiles) {
        runtimeState->water.pathProfiles.push_back(MakeWaterPathProfileState(profile));
    }
    runtimeState->water.laneProfiles.clear();
    runtimeState->water.laneProfiles.reserve(document.waterLaneProfiles.size());
    for (const auto& profile : document.waterLaneProfiles) {
        runtimeState->water.laneProfiles.push_back(MakeWaterLaneProfileState(profile));
    }
    runtimeState->water.trailProfiles.clear();
    runtimeState->water.trailProfiles.reserve(document.waterTrailProfiles.size());
    for (const auto& profile : document.waterTrailProfiles) {
        runtimeState->water.trailProfiles.push_back(MakeWaterTrailProfileState(profile));
    }
    runtimeState->water.selectedPathProfileName = document.selectedWaterPathProfileName;
    runtimeState->water.selectedLaneProfileName = document.selectedWaterLaneProfileName;
    runtimeState->water.selectedTrailProfileName = document.selectedWaterTrailProfileName;
    runtimeState->water.editedPathProfileSettings = document.tempWaterPathProfileSettings;
    runtimeState->water.editedLaneProfileSettings = document.tempWaterLaneProfileSettings;
    runtimeState->water.editedTrailProfile =
        document.tempWaterTrailProfile.has_value()
            ? std::optional<SavedWaterTrailProfileState>{
                  MakeWaterTrailProfileState(document.tempWaterTrailProfile.value())}
            : std::nullopt;
    runtimeState->water.editedDynamicMeshTrailProfile =
        document.tempWaterDynamicMeshTrailProfile.has_value()
            ? std::optional<SavedWaterTrailProfileState>{
                  MakeWaterTrailProfileState(
                      document.tempWaterDynamicMeshTrailProfile.value())}
            : std::nullopt;
    if (runtimeState->water.editedDynamicMeshTrailProfile.has_value()) {
        runtimeState->water.dynamicMeshFlowSettings.trailProfileName =
            NormalizeWaterProfileName(
                runtimeState->water.editedDynamicMeshTrailProfile->name);
    } else if (IsEditedWaterProfileName(
                   runtimeState->water.dynamicMeshFlowSettings
                       .trailProfileName)) {
        // Older project files could retain an `_edited` assignment without
        // the shadow's geometry/style. Resolve that dangling reference to its
        // saved base profile instead of leaking a prior project's edit.
        runtimeState->water.dynamicMeshFlowSettings.trailProfileName =
            UneditedWaterProfileName(
                runtimeState->water.dynamicMeshFlowSettings
                    .trailProfileName);
    }
    runtimeState->water.dynamicMeshTrailProfileNameBuffer =
        BaseWaterProfileName(
            runtimeState->water.dynamicMeshFlowSettings.trailProfileName);
    runtimeState->water.pointVisuals.clear();
    for (const auto& visualDocument : document.waterPointVisuals) {
        const auto normalized = NormalizePointVisualName(visualDocument.name);
        if (!IsWaterProjectCustomVisualName(normalized)) {
            continue;
        }
        AppendWaterPointVisualIfMissing(
            &runtimeState->water.pointVisuals,
            normalized,
            visualDocument.style);
    }
    bool importedLegacyWaterPointVisual = false;
    if (document.schemaVersion < 23U && document.waterPointVisuals.empty()) {
        if (document.tempWaterPointVisualStyle.has_value()) {
            ImportLegacyWaterPointVisualStyle(
                runtimeState,
                document.tempWaterPointVisualStyle.value());
        } else {
            ImportLegacyWaterPointVisualStyle(runtimeState, document.waterPointVisualStyle);
        }
        importedLegacyWaterPointVisual = true;
    }
    if (document.waterTrailProfiles.empty()) {
        ImportLegacyWaterVisualsAsTrailProfiles(runtimeState);
        if (document.schemaVersion < 25U &&
            !document.selectedWaterPointVisualName.empty()) {
            runtimeState->water.selectedTrailProfileName =
                NormalizeWaterProfileName(document.selectedWaterPointVisualName);
        }
        if (!runtimeState->water.editedTrailProfile.has_value() &&
            document.tempWaterPointVisualStyle.has_value()) {
            runtimeState->water.editedTrailProfile = MakeWaterTrailProfile(
                EditedWaterProfileName(runtimeState->water.selectedTrailProfileName),
                runtimeState->water.defaultTrailGeometry,
                document.tempWaterPointVisualStyle.value());
        }
    }
    MigrateLegacyWaterEmitterProfiles(&runtimeState->water);
    EnsureWaterProfiles(runtimeState);
    runtimeState->water.selectedPointVisualName =
        document.selectedWaterPointVisualName.empty()
            ? std::string{"Water Flow_preset"}
            : NormalizePointVisualName(document.selectedWaterPointVisualName);
    if (importedLegacyWaterPointVisual &&
        runtimeState->water.selectedPointVisualName == "Water Flow_preset" &&
        FindWaterProjectVisualIndex(runtimeState->water.pointVisuals, "Water Flow").has_value()) {
        runtimeState->water.selectedPointVisualName = "Water Flow";
    }
    if (document.schemaVersion < 23U) {
        const auto rawSelected = runtimeState->water.selectedPointVisualName;
        const auto legacySelected = NormalizeWaterPointVisualName(rawSelected);
        if (legacySelected != rawSelected &&
            !FindWaterProjectVisualIndex(runtimeState->water.pointVisuals, rawSelected).has_value()) {
            runtimeState->water.selectedPointVisualName = legacySelected;
        }
    }
    const bool selectedIsPreset =
        MakeProtectedWaterPointVisualStyle(*runtimeState, runtimeState->water.selectedPointVisualName).has_value();
    if (!selectedIsPreset &&
        !FindWaterProjectVisualIndex(
             runtimeState->water.pointVisuals,
             runtimeState->water.selectedPointVisualName)
             .has_value()) {
        runtimeState->water.selectedPointVisualName = "Water Flow_preset";
    }
    runtimeState->water.pointVisualNameBuffer = BasePointVisualName(runtimeState->water.selectedPointVisualName);
    runtimeState->water.nextEmitterId = NextWaterEmitterId(*runtimeState);
    runtimeState->water.nextSeepageNodeId = NextWaterSeepageNodeId(*runtimeState);
    runtimeState->water.selectedEmitterIndex.reset();
    runtimeState->water.selectedManualFlowPathIndex.reset();
    runtimeState->water.manualFlowPathEditor = {};
    ClearWaterSeepageSelection(&runtimeState->water);
    runtimeState->water.movingSeepageNodeIndex.reset();
    runtimeState->water.seepagePlacementArmed = false;
    runtimeState->water.seepageTopologyFingerprints.clear();
    runtimeState->water.seepageAttachmentSemanticKeys.clear();
    runtimeState->water.seepageParamsFingerprints.clear();
    runtimeState->water.seepageRuntimeGrids.clear();
    runtimeState->water.seepageSupportJob = {};
    runtimeState->water.seepageSupportSelections.clear();
    runtimeState->water.seepageSupportNodeFingerprints.clear();
    runtimeState->water.seepagePendingSupportSelections.clear();
    runtimeState->water.seepagePendingSupportNodeFingerprints.clear();
    runtimeState->water.seepageSupportFailedKeys.clear();
    runtimeState->water.seepageRuntimeGuideKeys.clear();
    runtimeState->water.seepageSurfaceGuides.clear();
    runtimeState->water.seepageSurfaceGuideFingerprints.clear();
    runtimeState->water.seepageSurfaceGuideNodeFingerprints.clear();
    runtimeState->water.seepageSurfaceGuideWarning.clear();
    runtimeState->water.seepageSupportWarning.clear();
    runtimeState->water.placementArmed = false;
    runtimeState->water.pathAttractorPlacementArmed = false;
    runtimeState->water.movingEmitterIndex.reset();
    SyncWaterAnimationTrailProfileFromCurrentAnimation(runtimeState);
    if (document.waterPathCache.has_value() && !document.waterPathCache->branches.empty()) {
        runtimeState->water.pathCache = document.waterPathCache.value();
        runtimeState->water.pathCacheLoaded = true;
        runtimeState->water.pathCacheStale = runtimeState->water.pathCache.stale;
        runtimeState->water.pathDirty = runtimeState->water.pathCacheStale;
        runtimeState->water.dirtyEmitterIds.clear();
        runtimeState->water.pathAnchors = WaterPathAnchorsFromCacheWithProfileSettings(*runtimeState);
    } else {
        runtimeState->water.pathCache = {};
        runtimeState->water.pathCacheLoaded = false;
        runtimeState->water.pathCacheStale = false;
        runtimeState->water.pathAnchors = {};
        if (runtimeState->water.emitters.empty()) {
            runtimeState->water.pathDirty = false;
            runtimeState->water.dirtyEmitterIds.clear();
        } else {
            MarkWaterPathDirty(runtimeState);
        }
    }
    ValidateWaterSourceSettingLinks(runtimeState);
    runtimeState->cameraShots = document.cameraShots;
    EnsureRuntimeCameraShotIds(runtimeState);
    runtimeState->cameraPanel.draftShotName = NextCameraShotName(*runtimeState);
    runtimeState->cameraPanel.selectedShotIndex.reset();
    runtimeState->cameraPanel.renamingShotIndex.reset();
    runtimeState->cameraPanel.pendingLinkedShotDeleteIndex.reset();
    runtimeState->cameraPanel.multiEditAllowedCameraIds.clear();
    runtimeState->cameraPanel.shotRenameBuffer.clear();
    runtimeState->cameraPanel.focusShotRename = false;
    runtimeState->cameraPanel.pathShotIndices = document.cameraPathShotIndices;
    runtimeState->cameraPanel.selectedPathItemIndex.reset();
    runtimeState->cameraPanel.pathDurationFrames =
        std::max<std::uint32_t>(1U, document.cameraPathDurationFrames);
    runtimeState->animationPanel.availableFiles.clear();
    runtimeState->animationPanel.availableFileAssociatedLayerPaths.clear();
    runtimeState->animationPanel.availableFileLoadedPaths.clear();
    runtimeState->animationPanel.availableFileEditedPaths.clear();
    runtimeState->animationPanel.availableFileDiskRevisions.clear();
    runtimeState->animationPanel.availableFileLoopEditPairIds.clear();
    runtimeState->animationPanel.reciprocalPanTimingTakeCloneIds.clear();
    runtimeState->animationPanel.availableFileDirtyFlags.clear();
    runtimeState->animationPanel.brokenVelocityLinkPathKeys.clear();
    runtimeState->animationPanel.projectVelocityLinksBaselineDirty = false;
    runtimeState->animationPanel.projectVelocityLinksDirty = false;
    runtimeState->animationPanel.selectedExportFiles.clear();
    if (document.hasSavedAnimationRegistry) {
        const auto roots = WorkspaceRoots(*runtimeState);
        for (const auto& animation : document.savedAnimations) {
            AddAnimationFileToRegistry(
                &runtimeState->animationPanel,
                animation.filePath,
                animation.associatedLayerPaths,
                &roots);
        }
        runtimeState->animationPanel.animationRegistryInitialized = true;
    } else {
        runtimeState->animationPanel.animationRegistryInitialized = false;
        const auto roots = WorkspaceRoots(*runtimeState);
        RefreshAnimationFileList(&runtimeState->animationPanel, AnimationDirectory(*runtimeState), &roots);
    }
    ValidateProjectAnimationVelocityLinks(document, runtimeState);
    runtimeState->animationPanel.renamingFileIndex.reset();
    runtimeState->animationPanel.fileRenameBuffer.clear();
    runtimeState->animationPanel.focusFileRename = false;
    runtimeState->animationPanel.currentPathUsesEdited = false;
    runtimeState->animationPanel.selectedFileUsesEdited = false;
    if (runtimeState->cameraPanel.pathShotIndices.empty() &&
        document.schemaVersion < 9U &&
        !runtimeState->cameraShots.empty()) {
        runtimeState->cameraPanel.pathShotIndices.reserve(runtimeState->cameraShots.size());
        for (std::size_t index = 0; index < runtimeState->cameraShots.size(); ++index) {
            runtimeState->cameraPanel.pathShotIndices.push_back(index);
        }
        std::uint32_t legacyDurationFrames = 0U;
        for (std::size_t index = 1; index < runtimeState->cameraShots.size(); ++index) {
            legacyDurationFrames += std::max<std::uint32_t>(1U, runtimeState->cameraShots[index].durationFrames);
        }
        runtimeState->cameraPanel.pathDurationFrames = std::max<std::uint32_t>(1U, legacyDurationFrames);
    }
    runtimeState->cameraPlayback.active = false;
    if (!runtimeState->cameraShots.empty()) {
        runtimeState->cameraPanel.selectedShotIndex = 0;
    }
    EnsureCameraShotSelections(&runtimeState->cameraPanel, runtimeState->cameraShots.size());
    runtimeState->persistence.queuedLoads.clear();
    const bool hasProjectCamera = document.cameraState.has_value();
    bool requestedLoadedLayer = false;

    for (std::size_t sessionIndex = 0; sessionIndex < runtimeState->sessions.size(); ++sessionIndex) {
        auto& session = runtimeState->sessions[sessionIndex];
        const auto layerIt = std::find_if(
            document.layers.begin(),
            document.layers.end(),
            [&session](const ProjectLayerDocument& layerDocument) {
                return PathsReferToSameLocation(
                    layerDocument.sourcePath,
                    session.sourcePath);
            });

        if (layerIt == document.layers.end()) {
            UnloadLayerByIndex(runtimeState, viewport, sessionIndex);
            continue;
        }

        if (session.kind == LayerKind::PointCloud) {
            if (!layerIt->sceneGroupName.empty()) {
                session.sceneGroupName = layerIt->sceneGroupName;
            }
            if (!layerIt->sceneRole.empty()) {
                session.sceneRole = layerIt->sceneRole;
            }
            if (layerIt->inferredPointSpacingMeters > 0.0F) {
                session.inferredPointSpacingMeters = layerIt->inferredPointSpacingMeters;
            }
            if (layerIt->pointSpacingMeters > 0.0F) {
                session.pointSpacingMeters = layerIt->pointSpacingMeters;
            }
            session.pointSpacingManualOverride = layerIt->pointSpacingManualOverride;
            session.scenePrimaryRole = layerIt->scenePrimaryRole;
            if (!layerIt->selectedSceneVariantPath.empty()) {
                session.selectedSceneVariantPath = layerIt->selectedSceneVariantPath;
            }
        }

        if (session.kind == LayerKind::PointCloud) {
            if (IsGeneratedWaterFlowOverlaySession(session)) {
                session.pointVisuals.clear();
                for (const auto& visualDocument : layerIt->pointVisuals) {
                    session.pointVisuals.push_back({
                        .name = NormalizePointVisualName(visualDocument.name),
                        .style = visualDocument.style,
                    });
                }
                session.selectedPointVisualName = NormalizePointVisualName(layerIt->selectedPointVisualName);
                if (layerIt->pointStyle.has_value()) {
                    session.pointStyle = layerIt->pointStyle.value();
                }
                EnsurePointVisuals(&session);
                SeedWaterFlowBuiltInVisuals(runtimeState, &session);
            } else {
                session.selectedPointVisualName =
                    runtimeState->pointVisualLibrary.selectedPointVisualName;
                session.pointVisualNameBuffer =
                    BaseNameFromProjectPointVisualName(
                        runtimeState->pointVisualLibrary,
                        session.selectedPointVisualName);
                ApplyProjectPointVisualToSession(runtimeState, &session);
            }
        } else if (session.kind == LayerKind::GaussianSplat) {
            ApplyProjectGsplatVisualStyleToSession(*runtimeState, &session);
        }

        if (session.kind == LayerKind::PointCloud) {
            session.pointBudget = MakePreviewPointBudgetState(session, session.totalPrimitives);
            ClearPreviewLodSampleCache(&session);
            if (session.loaded) {
                viewport->UpdatePointBudget(sessionIndex, {});
            }
        }

        SanitizePointCloudStyle(&session);
        if (session.kind == LayerKind::PointCloud && !IsProjectPointVisualSession(session)) {
            EnsurePointVisuals(&session);
            UpsertPointVisual(&session, session.selectedPointVisualName, session.pointStyle);
        }

        if (IsSceneGroupedPointCloud(session)) {
            // The v33 scene group record controls grouped residency/visibility.
            // Legacy layer flags remain compatibility mirrors only.
            continue;
        }

        requestedLoadedLayer |= layerIt->loaded;
        if (!layerIt->loaded) {
            UnloadLayerByIndex(runtimeState, viewport, sessionIndex);
            continue;
        }

        session.visible = layerIt->visible;
        if (!session.loaded) {
            QueueLayerLoad(runtimeState, sessionIndex, PointCloudLoadPurpose::Interactive);
        }
    }

    CanonicalizeRuntimeSceneAssociations(runtimeState);
    requestedLoadedLayer |= ApplyScenePointCloudGroupDocuments(
        document,
        runtimeState,
        viewport);

    const auto selectedLayerIndex =
        document.selectedLayerPath.empty()
            ? std::nullopt
            : FindSessionIndexBySourcePath(
                  *runtimeState,
                  document.selectedLayerPath);
    runtimeState->selectedSessionIndex = selectedLayerIndex;
    // Prefer the precise saved layer when it still belongs to the active
    // scene. The stable group identity repairs selection after a density or
    // source-file replacement makes that path obsolete.
    if (!document.activeSceneGroupName.empty() &&
        (!runtimeState->selectedSessionIndex.has_value() ||
         runtimeState->sessions[
             runtimeState->selectedSessionIndex.value()]
                 .sceneGroupName != document.activeSceneGroupName)) {
        if (const auto activeSceneIndex =
                FindSessionIndexForSceneGroup(
                    *runtimeState,
                    document.activeSceneGroupName);
            activeSceneIndex.has_value()) {
            runtimeState->selectedSessionIndex = activeSceneIndex;
        }
    }

    if (runtimeState->selectedSessionIndex.has_value()) {
        const auto selectedIndex = runtimeState->selectedSessionIndex.value();
        if (runtimeState->sessions[selectedIndex].loaded && !hasProjectCamera) {
            FocusSessionLayer(runtimeState, *viewport, selectedIndex);
        }
    }

    if (hasProjectCamera) {
        runtimeState->camera.ApplyState(document.cameraState.value());
        SyncPivotOverlayToCamera(runtimeState);
    }
    runtimeState->preserveProjectCameraOnNextLayerActivation =
        hasProjectCamera && requestedLoadedLayer && VisibleLayerCount(*runtimeState) == 0;
    bool restoredActiveAnimation = false;
    std::string activeAnimationRestoreError;
    if (!document.activeAnimationPath.empty()) {
        if (LoadAnimationPathFromFile(
                runtimeState,
                document.activeAnimationPath)) {
            restoredActiveAnimation = true;
            runtimeState->animationPanel.scrubAmount =
                std::clamp(
                    document.activeAnimationPosition,
                    0.0F,
                    1.0F);
            ApplyAnimationScrub(runtimeState);
            runtimeState->animationPanel.selectedFileIndex =
                FindAnimationRegistryIndex(
                    runtimeState->animationPanel,
                    document.activeAnimationPath);
            if (requestedLoadedLayer &&
                VisibleLayerCount(*runtimeState) == 0) {
                runtimeState->preserveProjectCameraOnNextLayerActivation =
                    true;
            }
        } else {
            activeAnimationRestoreError =
                runtimeState->errorMessage.empty()
                    ? "The saved active animation could not be loaded."
                    : runtimeState->errorMessage;
            runtimeState->animationPanel.currentPath.reset();
            runtimeState->animationPanel.currentFilePath.clear();
            runtimeState->animationPanel.currentPathUsesEdited = false;
            runtimeState->animationPanel.selectedFileUsesEdited = false;
            runtimeState->animationPanel.selectedFileIndex.reset();
            runtimeState->animationPanel.selectedKeyIndex.reset();
        }
    }
    runtimeState->statusMessage =
        "Loaded project with " + FormatPointCount(document.layers.size()) + " layer settings.";
    if (restoredActiveAnimation) {
        runtimeState->statusMessage +=
            " Restored active animation " +
            document.activeAnimationPath.filename().string() + ".";
    }
    runtimeState->persistence.projectName = document.projectName;
    if (activeAnimationRestoreError.empty()) {
        runtimeState->errorMessage.clear();
    } else {
        runtimeState->errorMessage =
            "The project loaded, but its active animation did not: " +
            activeAnimationRestoreError;
    }
    (void)SynchronizeLiveTimingTakeRain(
        runtimeState,
        viewport,
        true);
    return true;
}

std::filesystem::path ProjectRenderSetupDirectory(
    const PreviewRuntimeState& runtimeState) {
    const std::filesystem::path projectPath{
        runtimeState.persistence.projectFilePath};
    const auto projectDirectory = projectPath.empty()
                                      ? std::filesystem::path{"Saved"}
                                      : projectPath.parent_path();
    return projectDirectory / "render_setups";
}

std::filesystem::path LocalRenderSetupHistoryIndexPath(
    const PreviewRuntimeState& runtimeState) {
    return runtimeState.waterSurfaceCacheRoot / "render_setups" /
           "history.json";
}

std::filesystem::path ProjectRenderSetupHistoryIndexPath(
    const PreviewRuntimeState& runtimeState) {
    return LocalRenderSetupHistoryIndexPath(runtimeState);
}

std::string RenderSetupProjectIdentity(
    const PreviewRuntimeState& runtimeState) {
    const std::filesystem::path projectPath{
        runtimeState.persistence.projectFilePath};
    if (!projectPath.empty()) {
        std::error_code canonicalError;
        const auto canonical =
            std::filesystem::weakly_canonical(
                projectPath,
                canonicalError);
        return (canonicalError ? projectPath.lexically_normal()
                               : canonical)
            .generic_string();
    }
    return runtimeState.persistence.projectName;
}

PreservedAnimationRuntimeState CaptureAnimationRuntimeState(
    const PreviewRuntimeState& runtimeState) {
    PreservedAnimationRuntimeState state{
        .path = runtimeState.animationPanel.currentPath,
        .filePath = runtimeState.animationPanel.currentFilePath,
        .selectedFileIndex =
            runtimeState.animationPanel.selectedFileIndex,
        .currentPathUsesEdited =
            runtimeState.animationPanel.currentPathUsesEdited,
        .selectedFileUsesEdited =
            runtimeState.animationPanel.selectedFileUsesEdited,
        .scrubAmount = std::clamp(
            runtimeState.animationPanel.scrubAmount,
            0.0F,
            1.0F),
        .timelineViewRange =
            invisible_places::timing::SanitizeTimelineViewRange(
                runtimeState.animationPanel.timelineViewRange),
        .dirty = runtimeState.animationPanel.dirty,
    };
    const auto& panel = runtimeState.animationPanel;
    const auto editCount = std::min(
        panel.availableFiles.size(),
        panel.availableFileEditedPaths.size());
    state.edits.reserve(editCount);
    for (std::size_t index = 0U; index < editCount; ++index) {
        if (!panel.availableFileEditedPaths[index].has_value()) {
            continue;
        }
        state.edits.push_back({
            .filePath = panel.availableFiles[index],
            .path = panel.availableFileEditedPaths[index].value(),
            .loopPairId = index < panel.availableFileLoopEditPairIds.size()
                              ? panel.availableFileLoopEditPairIds[index]
                              : std::string{},
        });
    }
    if (panel.dirty && panel.currentPath.has_value() &&
        !panel.currentFilePath.empty()) {
        const std::filesystem::path currentFilePath{
            panel.currentFilePath};
        const auto currentEdit = std::find_if(
            state.edits.begin(),
            state.edits.end(),
            [&](const PreservedAnimationEdit& edit) {
                return edit.filePath.lexically_normal() ==
                       currentFilePath.lexically_normal();
            });
        if (currentEdit != state.edits.end()) {
            currentEdit->path = panel.currentPath.value();
        } else {
            std::string loopPairId;
            if (const auto currentIndex = FindAnimationRegistryIndex(
                    panel,
                    currentFilePath);
                currentIndex.has_value() &&
                currentIndex.value() <
                    panel.availableFileLoopEditPairIds.size()) {
                loopPairId = panel.availableFileLoopEditPairIds[
                    currentIndex.value()];
            }
            state.edits.push_back({
                .filePath = currentFilePath,
                .path = panel.currentPath.value(),
                .loopPairId = std::move(loopPairId),
            });
        }
    }
    return state;
}

const AnimationPath* PreservedAuthoritativeAnimationPath(
    const PreservedAnimationRuntimeState& state,
    const std::filesystem::path& filePath) {
    if (!filePath.empty()) {
        const auto edited = std::find_if(
            state.edits.begin(),
            state.edits.end(),
            [&](const PreservedAnimationEdit& candidate) {
                return PathsLexicallyEqual(
                    candidate.filePath,
                    filePath);
            });
        if (edited != state.edits.end()) {
            return &edited->path;
        }
    }
    if (!state.path.has_value()) {
        return nullptr;
    }
    if (filePath.empty() || state.filePath.empty() ||
        PathsLexicallyEqual(
            std::filesystem::path{state.filePath},
            filePath)) {
        return &state.path.value();
    }
    return nullptr;
}

void RestoreAnimationRuntimeState(
    PreviewRuntimeState* runtimeState,
    PreservedAnimationRuntimeState state) {
    if (runtimeState == nullptr) {
        return;
    }
    auto& panel = runtimeState->animationPanel;
    panel.currentPath = std::move(state.path);
    panel.currentFilePath = std::move(state.filePath);
    panel.selectedFileIndex = state.selectedFileIndex;
    panel.currentPathUsesEdited =
        state.currentPathUsesEdited || state.dirty;
    panel.selectedFileUsesEdited =
        state.selectedFileUsesEdited || state.dirty;
    EnsureAnimationAssociationStorage(&panel);
    for (auto& edit : state.edits) {
        auto registryIndex = FindAnimationRegistryIndex(
            panel,
            edit.filePath);
        if (!registryIndex.has_value()) {
            const auto roots = WorkspaceRoots(*runtimeState);
            AddAnimationFileToRegistry(
                &panel,
                edit.filePath,
                edit.path.associatedLayerPaths,
                &roots);
            registryIndex = FindAnimationRegistryIndex(
                panel,
                edit.filePath);
        }
        if (!registryIndex.has_value()) {
            continue;
        }
        EnsureAnimationAssociationStorage(&panel);
        panel.availableFileEditedPaths[registryIndex.value()] =
            std::move(edit.path);
        panel.availableFileLoopEditPairIds[registryIndex.value()] =
            std::move(edit.loopPairId);
        panel.availableFileDirtyFlags[registryIndex.value()] = true;
    }
    panel.selectedKeyIndex.reset();
    panel.selectedWaterKeyIndex.reset();
    panel.selectedSeepageNodeKeyIndex.reset();
    panel.scrubAmount = std::clamp(state.scrubAmount, 0.0F, 1.0F);
    panel.timelineViewRange =
        invisible_places::timing::SanitizeTimelineViewRange(
            state.timelineViewRange);
    panel.timelineViewDrag.reset();
    panel.dirty = state.dirty;
    panel.preparedPathCache = {};
    panel.motionStatsCache = {};
    panel.perceivedFlowCache = {};
    runtimeState->animationPlayback.active = false;
    if (panel.currentPath.has_value()) {
        ApplyAnimationScrub(runtimeState);
    }
}

invisible_places::serialization::WaterSourcesDocument
CaptureRenderSetupAuthoredWater(
    const ProjectDocument& project,
    std::string_view selectedTimingTakeId) {
    invisible_places::serialization::WaterSourcesDocument water;
    water.emitters = project.waterEmitters;
    water.manualFlowPaths = project.waterManualFlowPaths;
    water.seepageNodes = project.waterSeepageNodes;
    water.shorelineDefaultSettings.reset();
    water.shorelineProfiles = project.waterShorelineProfiles;
    water.selectedShorelineProfileName.clear();
    water.shorelineInstances = project.waterShorelineInstances;
    water.nextShorelineInstanceId = std::max(
        project.nextWaterShorelineInstanceId,
        NextAvailableShorelineInstanceId(water.shorelineInstances));
    water.seepageDefaultNodeSettings =
        project.waterSeepageDefaultNodeSettings;
    water.seepageNodeSettingsProfiles =
        project.waterSeepageNodeSettingsProfiles;
    water.seepageDefaultLook = project.waterSeepageDefaultLook;
    water.seepageLookProfiles = project.waterSeepageLookProfiles;
    water.seepageResponseProfiles =
        project.waterSeepageResponseProfiles;
    water.sourceSettings = project.waterSourceSettings;
    water.tempSourceSettings = project.tempWaterSourceSettings;
    water.settings = project.waterSettings;
    water.tempSettings = project.tempWaterSettings;
    water.pathProfiles = project.waterPathProfiles;
    water.laneProfiles = project.waterLaneProfiles;
    water.trailProfiles = project.waterTrailProfiles;
    water.keyedSettingsProfiles =
        project.waterKeyedSettingsProfiles;
    water.selectedPathProfileName =
        project.selectedWaterPathProfileName;
    water.selectedLaneProfileName =
        project.selectedWaterLaneProfileName;
    water.selectedTrailProfileName =
        project.selectedWaterTrailProfileName;
    water.tempPathProfileSettings =
        project.tempWaterPathProfileSettings;
    water.tempLaneProfileSettings =
        project.tempWaterLaneProfileSettings;
    water.tempTrailProfile = project.tempWaterTrailProfile;
    water.bakeSettings = project.waterBakeSettings;
    water.renderSettings = project.waterRenderSettings;
    water.flowTrailSettings = project.waterFlowTrailSettings;
    water.showFlowTrails = project.waterShowFlowTrails;
    water.trailGeometry = project.waterTrailGeometry;
    water.dynamicMeshFlowSettings =
        project.waterDynamicMeshFlowSettings;
    const auto rainExport = invisible_places::timing::
        BuildTimingTakeRainStandaloneExportState(
            project.waterRainProfiles,
            project.timingTakes,
            selectedTimingTakeId,
            project.waterRainSettings,
            project.waterRainVisualSettings);
    water.rainProfiles = rainExport.profiles;
    water.rainTimingTakeAssignments = rainExport.assignments;
    water.rainSettings = rainExport.compatibilitySettings;
    water.rainVisualSettings = rainExport.compatibilityVisual;
    // Render setups deliberately reference immutable terrain inputs and never
    // carry generated path cache payloads.
    water.pathCache.reset();
    return water;
}

