void DrawDebugExportSection(PreviewRuntimeState* runtimeState) {
    if (!BeginPanelSection("Export")) {
        return;
    }
    auto& job = runtimeState->offlineRenderJob;
    if (!job.active) {
        ImGui::TextDisabled("No export job is running.");
        ImGui::SeparatorText("Export Sources");
        bool anyCandidate = false;
        for (std::size_t sessionIndex = 0;
             sessionIndex < runtimeState->sessions.size();
             ++sessionIndex) {
            if (!IsExportPointCloudSourceCandidate(*runtimeState, sessionIndex)) {
                continue;
            }
            anyCandidate = true;
            const auto& session = runtimeState->sessions[sessionIndex];
            const bool ready =
                IsGpuAnimationExportPointCloudSourceReady(*runtimeState, sessionIndex);
            ImGui::TextWrapped(
                "%s %s (%.1fM points)",
                ready ? "[ready]" : "[loads on export]",
                session.sourcePath.filename().string().c_str(),
                static_cast<double>(session.totalPrimitives) / 1.0e6);
        }
        if (!anyCandidate) {
            ImGui::TextDisabled("No export point-cloud sources are available.");
        }
        if (!job.lastOutputPath.empty()) {
            ImGui::TextWrapped("Last: %s", job.lastOutputPath.string().c_str());
        }
        EndPanelSection();
        return;
    }
    ImGui::SeparatorText("Rendering Layers");
    for (const auto& layer : job.exportPointCloudLayers) {
        if (layer.layerId >= runtimeState->sessions.size()) {
            continue;
        }
        const auto& session = runtimeState->sessions[layer.layerId];
        ImGui::TextWrapped(
            "%s: drawing %.1fM / %.1fM points",
            session.sourcePath.filename().string().c_str(),
            static_cast<double>(layer.drawPointCount) / 1.0e6,
            static_cast<double>(session.totalPrimitives) / 1.0e6);
    }
    RefreshAnimationExportWriterProgress(&job);
    if (job.preparingExport && job.preparationState != nullptr) {
        std::size_t completedRequests = 0;
        std::size_t totalRequests = 0;
        std::string currentLayerName;
        {
            std::scoped_lock lock(job.preparationState->mutex);
            completedRequests = job.preparationState->completedRequests;
            totalRequests = job.preparationState->totalRequests;
            currentLayerName = job.preparationState->currentLayerName;
        }
        ImGui::Text("Preparing samples %zu / %zu", completedRequests, totalRequests);
        if (!currentLayerName.empty()) {
            ImGui::TextWrapped("Layer: %s", currentLayerName.c_str());
        }
    } else {
        ImGui::Text(
            "Captured %u / %zu, saved %u, queued %zu",
            std::min<std::uint32_t>(job.currentFrame, static_cast<std::uint32_t>(job.frames.size())),
            job.frames.size(),
            std::min<std::uint32_t>(job.writtenFrameCount, static_cast<std::uint32_t>(job.frames.size())),
            job.pendingFrameCount);
        DrawExportTimingSummary(job);
    }
    ImGui::Text("Elapsed: %s", FormatElapsedTime(std::chrono::steady_clock::now() - job.startedAt).c_str());
    if (!job.lastOutputPath.empty()) {
        ImGui::TextWrapped("Last: %s", job.lastOutputPath.string().c_str());
    }
    if (!job.exportLog.path.empty()) {
        ImGui::TextWrapped("Log: %s", job.exportLog.path.string().c_str());
    }
    EndPanelSection();
}

void DrawDiagnosticsWindow(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell& viewport) {
    if (runtimeState == nullptr || !runtimeState->showDiagnosticsPanel) {
        return;
    }

    bool open = true;
    ImGui::SetNextWindowSize(ImVec2{460.0F, 560.0F}, ImGuiCond_FirstUseEver);
    if (ImGui::Begin("Debug", &open, ImGuiWindowFlags_NoCollapse)) {
        if (!runtimeState->errorMessage.empty()) {
            ImGui::TextColored(ImVec4{0.74F, 0.18F, 0.14F, 1.0F}, "%s", runtimeState->errorMessage.c_str());
        } else if (!runtimeState->statusMessage.empty()) {
            ImGui::TextWrapped("%s", runtimeState->statusMessage.c_str());
        } else {
            ImGui::TextDisabled("Ready.");
        }
        ImGui::Separator();

        const auto drawSection = [&](ControlsTab tab) {
            switch (tab) {
                case ControlsTab::Visuals:
                    DrawDebugVisualsSection(runtimeState, viewport);
                    return;
                case ControlsTab::Water:
                    DrawDebugWaterSection(runtimeState);
                    return;
                case ControlsTab::Camera:
                    DrawDebugCameraSection(runtimeState);
                    return;
                case ControlsTab::Animation:
                    DrawDebugAnimationSection(runtimeState);
                    return;
                case ControlsTab::Timings:
                    DrawDebugTimingsSection(runtimeState);
                    return;
                case ControlsTab::Export:
                    DrawDebugExportSection(runtimeState);
                    return;
                case ControlsTab::Lidar:
                    DrawDebugLidarSection(runtimeState);
                    return;
                case ControlsTab::Gsplat:
                    DrawDebugGsplatSection(runtimeState);
                    return;
                case ControlsTab::Project:
                    return;
            }
        };

        // The active controls tab reads first; everything else follows in a
        // fixed order so the window stays scannable.
        const auto activeTab = runtimeState->activeControlsTab;
        drawSection(activeTab);
        DrawDebugGeneralSection(runtimeState, viewport);
        constexpr std::array<ControlsTab, 8> kDebugSectionOrder{{
            ControlsTab::Visuals,
            ControlsTab::Water,
            ControlsTab::Camera,
            ControlsTab::Animation,
            ControlsTab::Timings,
            ControlsTab::Export,
            ControlsTab::Lidar,
            ControlsTab::Gsplat,
        }};
        for (const auto tab : kDebugSectionOrder) {
            if (tab != activeTab) {
                drawSection(tab);
            }
        }
    }
    ImGui::End();

    runtimeState->showDiagnosticsPanel = open;
}

constexpr std::array<invisible_places::water::WaterTimingFeature, 5U> kWaterTimingFeatureOrder{{
    invisible_places::water::WaterTimingFeature::Shoreline,
    invisible_places::water::WaterTimingFeature::Seepage,
    invisible_places::water::WaterTimingFeature::Rain,
    invisible_places::water::WaterTimingFeature::Flow,
    invisible_places::water::WaterTimingFeature::MeshFlow,
}};

invisible_places::water::WaterTimingRun* FindWaterTimingRunById(
    WaterWorkflowState* water,
    const std::string& runId) {
    if (water == nullptr || runId.empty()) {
        return nullptr;
    }
    const auto found = std::find_if(
        water->timingRuns.begin(),
        water->timingRuns.end(),
        [&](const invisible_places::water::WaterTimingRun& candidate) {
            return candidate.id == runId;
        });
    return found != water->timingRuns.end() ? &*found : nullptr;
}

std::uint32_t WaterTimingRunIdSuffix(const std::string& runId) {
    constexpr std::string_view kPrefix = "timing_run_";
    if (runId.size() <= kPrefix.size() || runId.compare(0, kPrefix.size(), kPrefix) != 0) {
        return 0U;
    }
    std::uint32_t suffix = 0U;
    for (std::size_t index = kPrefix.size(); index < runId.size(); ++index) {
        const char character = runId[index];
        if (character < '0' || character > '9') {
            return 0U;
        }
        suffix = suffix * 10U + static_cast<std::uint32_t>(character - '0');
    }
    return suffix;
}

std::string MakeUniqueWaterTimingRunId(WaterWorkflowState* water) {
    if (water == nullptr) {
        return "timing_run_1";
    }
    for (const auto& run : water->timingRuns) {
        water->nextTimingRunSequence = std::max(
            water->nextTimingRunSequence,
            WaterTimingRunIdSuffix(run.id) + 1U);
    }
    return "timing_run_" + std::to_string(water->nextTimingRunSequence++);
}

std::string MakeUniqueWaterTimingKeyId(const invisible_places::water::WaterTimingRun& run) {
    std::size_t suffix = run.keys.size() + 1U;
    std::string id;
    do {
        id = "key_" + std::to_string(suffix++);
    } while (std::any_of(
        run.keys.begin(),
        run.keys.end(),
        [&](const invisible_places::water::WaterTimingKey& candidate) {
            return candidate.id == id;
        }));
    return id;
}

bool WaterTimingCompiledKeysEquivalent(
    const std::vector<invisible_places::water::WaterScenarioKey>& left,
    const std::vector<invisible_places::water::WaterScenarioKey>& right) {
    if (left.size() != right.size()) {
        return false;
    }
    constexpr float kTolerance = 1.0e-5F;
    for (std::size_t index = 0U; index < left.size(); ++index) {
        const auto& a = left[index];
        const auto& b = right[index];
        if (a.interpolation != b.interpolation ||
            std::abs(a.position - b.position) > kTolerance ||
            std::abs(a.state.seepageLevel - b.state.seepageLevel) > kTolerance ||
            std::abs(a.state.rainLevel - b.state.rainLevel) > kTolerance ||
            std::abs(a.state.flowLevel - b.state.flowLevel) > kTolerance ||
            std::abs(a.state.shorelineLevel - b.state.shorelineLevel) > kTolerance ||
            std::abs(a.state.meshFlowLevel - b.state.meshFlowLevel) > kTolerance ||
            std::abs(a.state.seepageSpread - b.state.seepageSpread) > kTolerance) {
            return false;
        }
    }
    return true;
}

// Recompiles every timing-assigned track of one animation against the current
// run library. Returns true when any track's compiled keys actually changed.
// Base-state-only differences (for example an edited scenario look) evaluate
// identically at the driven channels and intentionally do not count.
bool RecompileWaterTimingTracks(
    WaterWorkflowState* /*water*/,
    invisible_places::camera::AnimationPath* /*animationPath*/,
    bool /*useEditedScenario*/) {
    // Aggregate scenario timing is legacy data. Timing Takes evaluate their
    // explicit feature tracks directly, so old compiled keys stay untouched.
    return false;
}

void RecompileWaterTimingTracksForAnimation(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr || !runtimeState->animationPanel.currentPath.has_value()) {
        return;
    }
    auto& panel = runtimeState->animationPanel;
    if (!RecompileWaterTimingTracks(&runtimeState->water, &panel.currentPath.value())) {
        return;
    }
    panel.selectedWaterKeyIndex.reset();
    panel.dirty = true;
    InvalidateWaterSeepageParams(&runtimeState->water);
    runtimeState->previewRenderStateSignatureValid = false;
}

std::string MakeUniqueWaterScenarioId(
    const WaterWorkflowState& water,
    std::string_view name) {
    std::string slug;
    for (const char character : name) {
        if (std::isalnum(static_cast<unsigned char>(character)) != 0) {
            slug += static_cast<char>(std::tolower(static_cast<unsigned char>(character)));
        } else if (!slug.empty() && slug.back() != '-') {
            slug += '-';
        }
    }
    while (!slug.empty() && slug.back() == '-') {
        slug.pop_back();
    }
    if (slug.empty()) {
        slug = "scenario";
    }
    auto candidate = slug;
    std::size_t suffix = 2U;
    while (FindWaterScenarioDefinition(water, candidate) != nullptr) {
        candidate = slug + "-" + std::to_string(suffix++);
    }
    return candidate;
}

void DiscardEditedWaterScenario(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr || !runtimeState->water.editedScenario.has_value()) {
        return;
    }
    const auto editedName = runtimeState->water.editedScenario->name;
    runtimeState->water.editedScenario.reset();
    RecompileWaterTimingTracksForAnimation(runtimeState);
    InvalidateWaterSeepageParams(&runtimeState->water);
    runtimeState->previewRenderStateSignatureValid = false;
    runtimeState->statusMessage = "Discarded " + editedName + ".";
    runtimeState->errorMessage.clear();
}

void SaveEditedWaterScenario(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr || !runtimeState->water.editedScenario.has_value()) {
        return;
    }
    auto& water = runtimeState->water;
    const auto scenarioId = water.editedScenario->id;
    const auto savedIt = std::find_if(
        water.seepageScenarios.begin(),
        water.seepageScenarios.end(),
        [&](const auto& scenario) { return scenario.id == scenarioId; });
    if (savedIt == water.seepageScenarios.end()) {
        runtimeState->errorMessage =
            "The edited scenario no longer exists in the project; nothing was saved.";
        runtimeState->statusMessage.clear();
        return;
    }
    savedIt->state = invisible_places::water::SanitizeWaterScenarioState(
        water.editedScenario->state);
    water.editedScenario.reset();
    // Refresh the loaded animation's embedded snapshots so its file stays
    // reproducible with the newly saved state, then recompile timing runs.
    const auto* viewedAnimationPath = CurrentAnimationPath(*runtimeState);
    const bool refreshesEmbeddedTrack =
        viewedAnimationPath != nullptr &&
        std::any_of(
            viewedAnimationPath->waterScenarioTracks.begin(),
            viewedAnimationPath->waterScenarioTracks.end(),
            [&](const auto& track) {
                return track.scenarioId == scenarioId;
            });
    if (refreshesEmbeddedTrack) {
        auto* animationPath = CurrentAnimationPath(runtimeState);
        for (auto& track : animationPath->waterScenarioTracks) {
            if (track.scenarioId == scenarioId) {
                track.scenarioName = savedIt->name;
                track.fallbackScenario = *savedIt;
                runtimeState->animationPanel.dirty = true;
            }
        }
        RecompileWaterTimingTracksForAnimation(runtimeState);
    }
    InvalidateWaterSeepageParams(&water);
    runtimeState->previewRenderStateSignatureValid = false;
    runtimeState->statusMessage = "Saved scenario " + savedIt->name + ".";
    runtimeState->errorMessage.clear();
}

bool WaterTimingRunAppliedToCurrentAnimation(
    const PreviewRuntimeState& runtimeState,
    const std::string& runId) {
    if (!runtimeState.animationPanel.currentPath.has_value() || runId.empty()) {
        return false;
    }
    for (const auto& track : runtimeState.animationPanel.currentPath->waterScenarioTracks) {
        for (const auto& assignment : track.timingAssignments) {
            if (assignment.runId == runId) {
                return true;
            }
        }
    }
    return false;
}

void DrawExportBatchSection(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return;
    }
    if (!BeginPanelSection("Batch Export")) {
        return;
    }
    auto& panel = runtimeState->animationPanel;
    if (!panel.animationRegistryInitialized) {
        const auto roots = WorkspaceRoots(*runtimeState);
        RefreshAnimationFileList(&panel, AnimationDirectory(*runtimeState), &roots);
    }
    if (panel.availableFiles.empty()) {
        ImGui::TextDisabled("No saved animations are registered.");
        EndPanelSection();
        return;
    }
    ImGui::TextDisabled(
        "Each selected animation exports once with the saved display visual "
        "and its selected Timing Take.");
    if (ImGui::BeginListBox("Export Animations", ImVec2{-FLT_MIN, 112.0F})) {
        for (std::size_t index = 0; index < panel.availableFiles.size(); ++index) {
            ImGui::PushID(static_cast<int>(index));
            bool selectedForExport =
                AnimationFileSelectedForExport(panel, panel.availableFiles[index]);
            const auto displayName = AnimationDisplayNameFromPath(panel.availableFiles[index]);
            if (ImGui::Checkbox(displayName.c_str(), &selectedForExport)) {
                SetAnimationFileSelectedForExport(
                    &panel,
                    panel.availableFiles[index],
                    selectedForExport);
            }
            ImGui::PopID();
        }
        ImGui::EndListBox();
    }

    const auto selectedCount = panel.selectedExportFiles.size();
    const auto batchMode = ActiveExportMode(runtimeState);
    const bool batchModeCanExport =
        AnimationExportWritesVideo(batchMode) || AnimationExportWritesPngStack(batchMode);
    const std::string batchButtonLabel =
        "Export Selected " + std::string{AnimationExportModeLabel(batchMode)};
    const bool exportButtonDisabled =
        runtimeState->offlineRenderJob.active || !batchModeCanExport;
    if (exportButtonDisabled) {
        ImGui::BeginDisabled();
    }
    if (ImGui::Button(batchButtonLabel.c_str())) {
        StartSelectedQuickMp4Batch(runtimeState, viewport);
    }
    if (exportButtonDisabled) {
        ImGui::EndDisabled();
    }
    ImGui::SameLine();
    ImGui::TextDisabled("%zu selected", selectedCount);
    if (!batchModeCanExport) {
        ImGui::TextDisabled("Batch export needs a video or PNG-stack preset.");
    }
    EndPanelSection();
}

const RenderSetupHistoryEntry* SelectedRenderSetupHistoryEntry(
    const RenderSetupHistoryRuntimeState& history) {
    if (!history.selectedIndex.has_value() ||
        history.selectedIndex.value() >= history.entries.size()) {
        return nullptr;
    }
    return &history.entries[history.selectedIndex.value()];
}

std::string RenderSetupSuggestedCopyName(
    const std::filesystem::path& setupPath) {
    auto name = setupPath.filename().string();
    constexpr std::string_view suffix = ".iprender.json";
    if (EndsWith(name, suffix)) {
        name.resize(name.size() - suffix.size());
    }
    return name.empty() ? std::string{"Render_Setup"} : name;
}

bool SaveNamedRenderSetupCopy(
    PreviewRuntimeState* runtimeState,
    const std::filesystem::path& sourcePath,
    std::string_view requestedName) {
    if (runtimeState == nullptr) {
        return false;
    }
    const auto trimmedName = TrimText(requestedName);
    if (trimmedName.empty()) {
        runtimeState->errorMessage =
            "Enter a name for the render setup copy.";
        runtimeState->statusMessage.clear();
        return false;
    }

    const auto destination =
        ProjectRenderSetupDirectory(*runtimeState) /
        (SanitizeAnimationFileStem(trimmedName) + ".iprender.json");
    std::error_code existsError;
    if (std::filesystem::exists(destination, existsError)) {
        runtimeState->errorMessage =
            "A named render setup already exists at " +
            destination.string() + ".";
        runtimeState->statusMessage.clear();
        return false;
    }

    std::string errorMessage;
    auto document =
        invisible_places::serialization::LoadRenderSetupDocument(
            sourcePath,
            &errorMessage);
    if (!document.has_value()) {
        runtimeState->errorMessage =
            errorMessage.empty()
                ? "The selected render setup could not be read."
                : errorMessage;
        runtimeState->statusMessage.clear();
        return false;
    }
    invisible_places::app::workspace::ResolveRenderSetupDocument(
        &document.value(),
        WorkspaceRoots(*runtimeState));
    auto portableDocument = document.value();
    invisible_places::app::workspace::MakeRenderSetupDocumentPortable(
        &portableDocument,
        WorkspaceRoots(*runtimeState));
    if (!invisible_places::serialization::SaveRenderSetupDocument(
            portableDocument,
            destination,
            &errorMessage)) {
        runtimeState->errorMessage =
            errorMessage.empty()
                ? "The named render setup could not be saved."
                : errorMessage;
        runtimeState->statusMessage.clear();
        return false;
    }

    const auto entry =
        invisible_places::serialization::ReadRenderSetupHistoryEntry(
            destination,
            &errorMessage);
    if (!entry.has_value() ||
        !invisible_places::serialization::UpsertRenderSetupHistoryEntry(
            ProjectRenderSetupHistoryIndexPath(*runtimeState),
            entry.value(),
            invisible_places::serialization::
                kMaximumRenderSetupHistoryEntries,
            &errorMessage)) {
        runtimeState->statusMessage =
            "Saved named render setup to " + destination.string() + ".";
        runtimeState->errorMessage =
            "The setup was saved, but its history index could not be "
            "updated: " + errorMessage;
        runtimeState->renderSetupHistory.initialized = false;
        return true;
    }

    RefreshRenderSetupHistory(runtimeState);
    const auto savedIt = std::find_if(
        runtimeState->renderSetupHistory.entries.begin(),
        runtimeState->renderSetupHistory.entries.end(),
        [&](const RenderSetupHistoryEntry& candidate) {
            return candidate.setupPath.lexically_normal() ==
                   destination.lexically_normal();
        });
    if (savedIt != runtimeState->renderSetupHistory.entries.end()) {
        runtimeState->renderSetupHistory.selectedIndex =
            static_cast<std::size_t>(std::distance(
                runtimeState->renderSetupHistory.entries.begin(),
                savedIt));
    }
    runtimeState->statusMessage =
        "Saved named render setup to " + destination.string() + ".";
    runtimeState->errorMessage.clear();
    return true;
}

void DrawRenderSetupHistorySection(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr ||
        !BeginPanelSection("Render Setup History")) {
        return;
    }

    auto& history = runtimeState->renderSetupHistory;
    if (!history.initialized) {
        RefreshRenderSetupHistory(runtimeState);
    }
    UpdateActiveRenderSetupPreparation(runtimeState);

    const auto tooltip = [](std::string_view text) {
        if (ImGui::IsItemHovered(
                ImGuiHoveredFlags_DelayNormal |
                ImGuiHoveredFlags_AllowWhenDisabled)) {
            ImGui::SetTooltip(
                "%.*s",
                static_cast<int>(text.size()),
                text.data());
        }
    };

    if (runtimeState->activeRenderSetupOverride.has_value()) {
        const auto& active =
            runtimeState->activeRenderSetupOverride.value();
        ImGui::SeparatorText("Loaded Read-Only Setup");
        const ImVec4 stateColour = active.preparationFailed
                                       ? ImVec4{0.92F, 0.28F, 0.24F, 1.0F}
                                   : active.preparing
                                       ? ImVec4{0.92F, 0.66F, 0.20F, 1.0F}
                                       : ImVec4{0.30F, 0.78F, 0.45F, 1.0F};
        ImGui::TextColored(
            stateColour,
            "%s",
            active.preparationMessage.c_str());
        ImGui::TextWrapped(
            "%s",
            active.sourcePath.filename().string().c_str());
        ImGui::TextDisabled(
            "Scene: %s  |  Timing Take: %s",
            active.document.sceneGroupName.c_str(),
            active.document.timingTakeName.c_str());
        if (runtimeState->animationPanel.currentPath.has_value()) {
            ImGui::TextDisabled(
                "Active camera: %s",
                runtimeState->animationPanel.currentPath->name.c_str());
        }
        ImGui::TextWrapped(
            "Visuals, Water, Timings, and Project authoring are locked. "
            "Playback, scrubbing, camera editing, and export remain available.");
        ImGui::Spacing();
    }

    if (history.entries.empty()) {
        ImGui::TextDisabled(
            "No render setups have been recorded for this project yet.");
    } else if (ImGui::BeginListBox(
                   "Recorded Setups##RenderSetupHistory",
                   ImVec2{-FLT_MIN, 150.0F})) {
        for (std::size_t index = 0U;
             index < history.entries.size();
             ++index) {
            const auto& entry = history.entries[index];
            const auto status =
                invisible_places::serialization::RenderSetupStatusName(
                    entry.status);
            const auto videoName = entry.outputPath.empty()
                                       ? std::string{"No output"}
                                       : entry.outputPath.filename().string();
            const auto animationName = entry.animationName.empty()
                                           ? std::string{"Unnamed animation"}
                                           : entry.animationName;
            const auto takeName = entry.timingTakeName.empty()
                                      ? std::string{"Authored Timing"}
                                      : entry.timingTakeName;
            std::string label =
                entry.createdUtc + "  |  " + videoName + "  |  " +
                animationName + "  |  " + takeName + "  |  " +
                std::to_string(entry.editedSettingCount) +
                " edited  |  " + std::string{status};
            ImGui::PushID(static_cast<int>(index));
            const bool selected =
                history.selectedIndex.has_value() &&
                history.selectedIndex.value() == index;
            if (ImGui::Selectable(label.c_str(), selected)) {
                history.selectedIndex = index;
                history.saveAsEditing = false;
            }
            tooltip(label);
            if (selected) {
                ImGui::SetItemDefaultFocus();
            }
            ImGui::PopID();
        }
        ImGui::EndListBox();
    }

    const auto* selectedEntry =
        SelectedRenderSetupHistoryEntry(history);
    if (selectedEntry != nullptr) {
        ImGui::TextWrapped(
            "%s",
            selectedEntry->setupPath.string().c_str());
    }

    if (ImGui::Button("Refresh##RenderSetupHistory")) {
        RefreshRenderSetupHistory(runtimeState);
        selectedEntry =
            SelectedRenderSetupHistoryEntry(history);
    }
    tooltip("Reload the newest render-setup history entries from disk.");

    const bool canLoad =
        selectedEntry != nullptr &&
        !runtimeState->activeRenderSetupOverride.has_value() &&
        !runtimeState->offlineRenderJob.active &&
        runtimeState->pendingCurrentRenderSnapshot == nullptr &&
        runtimeState->pendingFramePreviewSnapshot == nullptr &&
        !runtimeState->pendingLoad.has_value() &&
        runtimeState->animationPanel.currentPath.has_value() &&
        runtimeState->animationPanel.currentPath->keys.size() >= 2U;
    ImGui::SameLine();
    ImGui::BeginDisabled(!canLoad);
    if (ImGui::Button("Load onto Active Animation")) {
        std::string errorMessage;
        auto setup =
            invisible_places::serialization::LoadRenderSetupDocument(
                selectedEntry->setupPath,
                &errorMessage);
        if (!setup.has_value()) {
            runtimeState->errorMessage =
                errorMessage.empty()
                    ? "The selected render setup could not be read."
                    : errorMessage;
            runtimeState->statusMessage.clear();
        } else {
            invisible_places::app::workspace::ResolveRenderSetupDocument(
                &setup.value(),
                WorkspaceRoots(*runtimeState));
            ActivateRenderSetupOverride(
                runtimeState,
                viewport,
                selectedEntry->setupPath,
                setup.value());
        }
    }
    ImGui::EndDisabled();
    tooltip(
        runtimeState->activeRenderSetupOverride.has_value()
            ? "Clear the loaded setup before loading another one."
        : !runtimeState->animationPanel.currentPath.has_value() ||
                  runtimeState->animationPanel.currentPath->keys.size() < 2U
            ? "Load an animation with at least two camera keys first."
        : selectedEntry == nullptr
            ? "Select a render setup from the history first."
        : runtimeState->offlineRenderJob.active ||
                  runtimeState->pendingCurrentRenderSnapshot != nullptr ||
                  runtimeState->pendingFramePreviewSnapshot != nullptr ||
                  runtimeState->pendingLoad.has_value()
            ? "Wait for the current load or export to finish."
            : "Apply this setup read-only while preserving the active camera path and normalized keys.");

    const bool canClear =
        runtimeState->activeRenderSetupOverride.has_value() &&
        !runtimeState->offlineRenderJob.active &&
        runtimeState->pendingCurrentRenderSnapshot == nullptr &&
        runtimeState->pendingFramePreviewSnapshot == nullptr &&
        !runtimeState->pendingLoad.has_value();
    ImGui::SameLine();
    ImGui::BeginDisabled(!canClear);
    if (ImGui::Button("Clear Loaded Setup")) {
        ClearActiveRenderSetupOverride(runtimeState, viewport);
    }
    ImGui::EndDisabled();
    tooltip(
        !runtimeState->activeRenderSetupOverride.has_value()
            ? "No historical render setup is currently loaded."
        : !canClear
            ? "Wait for the current load or export to finish."
            : "Restore the untouched project state while retaining active camera-path edits.");

    const bool canSaveAs = selectedEntry != nullptr;
    ImGui::BeginDisabled(!canSaveAs);
    if (ImGui::Button("Save Setup As...")) {
        history.saveAsEditing = true;
        history.focusSaveAsName = true;
        history.saveAsName =
            RenderSetupSuggestedCopyName(selectedEntry->setupPath);
    }
    ImGui::EndDisabled();
    tooltip(
        canSaveAs
            ? "Copy the selected immutable setup into this project's named render_setups directory."
            : "Select a render setup from the history first.");

    if (history.saveAsEditing && selectedEntry != nullptr) {
        if (history.focusSaveAsName) {
            ImGui::SetKeyboardFocusHere();
            history.focusSaveAsName = false;
        }
        const bool submitted = InputTextStringWithFlags(
            "Setup Name##RenderSetupSaveAs",
            &history.saveAsName,
            ImGuiInputTextFlags_EnterReturnsTrue);
        const bool validName = !TrimText(history.saveAsName).empty();
        ImGui::BeginDisabled(!validName);
        const bool saveClicked =
            ImGui::Button("Save##RenderSetupSaveAs") || submitted;
        ImGui::EndDisabled();
        tooltip(
            validName
                ? "Save a self-contained named copy without changing the source setup."
                : "Enter a non-empty setup name.");
        ImGui::SameLine();
        if (ImGui::Button("Cancel##RenderSetupSaveAs")) {
            history.saveAsEditing = false;
            history.saveAsName.clear();
        } else if (saveClicked && validName) {
            const auto sourcePath = selectedEntry->setupPath;
            const auto requestedName = history.saveAsName;
            if (SaveNamedRenderSetupCopy(
                    runtimeState,
                    sourcePath,
                    requestedName)) {
                history.saveAsEditing = false;
                history.saveAsName.clear();
            }
        }
    }

    EndPanelSection();
}

